// Generated by tools/build_docs.py from the engine's option list. Do not edit by hand.
// What the engine-lines editor shows under what was typed (EngineLineHelp).

enum EngineLineCatalog {
    struct Info { let title: String; let defaultValue: String; let note: String }
    static let byKey: [String: Info] = [
        "addr-scan": Info(title: "Quicker GPU-address lookups", defaultValue: "1", note: "Default on. Finding the buffer behind a GPU address (every vertex buffer, index buffer and root descriptor a game records) walks back only over entries that can still reach the address, instead of over every buffer within the largest buffe…"),
        "ags-rewrite": Info(title: "D3D12 AMD AGS 64-bit atomics rewrite", defaultValue: "", note: "read once; madeira.cfg ags-rewrite = 0 turns the rewrite off."),
        "alert-spin-us": Info(title: "", defaultValue: "0", note: "madeira.cfg alert-spin-us (default 0)"),
        "apicensus": Info(title: "", defaultValue: "", note: "top-level API census. Documents/madeira-apicensus.txt == \"1\" counts every call across the PE->unix winemetal boundary and classifies each as producer, consumer, lifetime, query, sync, presentation or bulk-memory. Needed because a ..."),
        "arena": Info(title: "", defaultValue: "", note: "FEX arena placeholder. Documents/madeira-arena.txt == \"1\" makes Wine reserve FEX's host arena before any PE loads. OFF by default: FEX still selects its own band, and on hardware that band IS the reservation, so enabling it starve..."),
        "arena-mb": Info(title: "", defaultValue: "0", note: "madeira.cfg arena-mb = N"),
        "arena-test": Info(title: "", defaultValue: "", note: "Arena carver self-test. Documents/madeira-arena-test.txt holds \"churn:N\", \"ramp:N\" or \"random:N\". Deliberately a SEPARATE file from madeira-arena.txt: a test that only runs when the feature is enabled cannot be used to decide whether to ..."),
        "args": Info(title: "", defaultValue: "", note: "Stray (UE4). Launch the shipping binary DIRECTLY rather than Stray.exe -- the launcher builds its child's command line itself and passed only \"Hk_project\", so Unreal picked its default RHI. That default is DX12 for this title and ..."),
        "async-present-ahead": Info(title: "", defaultValue: "1", note: "bounded run-ahead. Present enqueues and returns; the application may start the next frame while the worker encodes this one, but no more than async-present-ahead presents (default 1) may be queued behind it."),
        "async-submit": Info(title: "D3D12 asynchronous submission", defaultValue: "0", note: "asynchronous submission"),
        "attachless-split": Info(title: "", defaultValue: "0", note: "/ madeira-bcd skin-check: before the pass, its captures are blits madeira.cfg attachless-split = 1 gives every draw of an attachment-less pass its own encoder. On Apple GPUs the fragment work of consecutive draws in one..."),
        "avail-phys": Info(title: "Report the memory left before the app's limit as available", defaultValue: "0", note: "Default off. 1: Windows programs' available physical memory (GlobalMemoryStatusEx) is what remains before Madeira's memory limit instead of the phone's free memory, so Chromium (Social Club, Steam) frees caches below 1000 MB and 400 MB lef…"),
        "avail-phys-cef-mb": Info(title: "Available memory Chromium sees (MB)", defaultValue: "0", note: "0 (default): off. N: Social Club's SocialClubHelper.exe and Steam's steamwebhelper.exe see at most N MB of available physical memory, nobody else (the game and the launcher keep the real figure). Below 400 (e.g. 300) Chromium reports criti…"),
        "background-cpu": Info(title: "CPU cap in the background (% of one core)", defaultValue: "50", note: "While Madeira keeps a game or a download running in the background, its CPU use is held under this percent of one core on average (threads are paused for 100 ms at a time when it is over), because iOS ends a background app that averages mo…"),
        "background-download": Info(title: "Keep downloads running in the background (minutes)", defaultValue: "60", note: "Minutes a Steam, Epic, GOG, EA or itch.io download keeps going after you switch apps or lock the screen. Then it pauses cleanly and continues when Madeira is active again. 0: only iOS's short grace period, as before."),
        "background-gpu-gate": Info(title: "Hold GPU work in the background", defaultValue: "1", note: "On by default. While Madeira is not the active app, any thread other than the app's main thread that commits a Metal command buffer waits until Madeira is back, so a game that keeps loading in the background (Zink OpenGL, Direct3D, Vulkan)…"),
        "background-run": Info(title: "Keep a game running in the background (minutes)", defaultValue: "10", note: "Minutes a running game keeps going after you switch apps or lock the screen, so a long load finishes while you are away. Loading and other CPU work go on; drawing waits until Madeira is back (background-pause). The game's sound is muted me…"),
        "background-sound": Info(title: "Game sound in the background", defaultValue: "0", note: "Off by default: while a game keeps running in the background its sound is muted, and other apps' audio plays normally. 1: you keep hearing the game. A game's own config can set it."),
        "barrier-render": Info(title: "", defaultValue: "0", note: "; madeira.cfg barrier-render = 1 closes the render pass too (Astra's conservative experiment)"),
        "capture-big": Info(title: "", defaultValue: "0", note: "each) ate the whole budget in the first capture of a UE5 frame, so the G-buffer, lighting and final image were never written. Skip targets over 16 MB unless madeira.cfg capture-big = 1."),
        "capture-cs": Info(title: "", defaultValue: "", note: "re-read every CAP, so the target can change between captures of one run"),
        "capture-cs-indirect": Info(title: "", defaultValue: "0", note: "re-read every CAP, so the target can change between captures of one run"),
        "capture-cs-max": Info(title: "", defaultValue: "12", note: "re-read every CAP, so the target can change between captures of one run"),
        "capture-ps": Info(title: "", defaultValue: "", note: "re-read every CAP, like capture-cs"),
        "capture-raw": Info(title: "", defaultValue: "0", note: "madeira-bcd: contact sheets"),
        "capture-uav": Info(title: "", defaultValue: "1", note: "madeira-bcd: contact sheets"),
        "cbv-snapshot": Info(title: "", defaultValue: "0", note: "fix attempt: copy N bytes (1 = 4096) of every UPLOAD-heap root CBV at replay and bind the copy"),
        "census": Info(title: "", defaultValue: "", note: "wmtcmd census. Documents/madeira-census.txt == \"1\" counts which of the 59 render/compute/blit command types a workload actually emits, and how large their sidecar data gets. Needed before serialising wmtcmd_* for the remote Metal ..."),
        "clear-defer": Info(title: "Clears wait for the pass that draws to their target", defaultValue: "1", note: "On by default. A whole render-target or depth-stencil clear becomes the clear the next render pass that draws to that target starts with: a clear no longer ends the pass in progress unless it is one of that pass's own targets, and needs no…"),
        "clear-rects": Info(title: "Clear only the rectangles a game asks for", defaultValue: "0", note: "Default off: a render-target or depth-stencil clear with rectangles clears the whole view, as before. 1: only the rectangles are cleared, in a small pass of their own (as DXMT's D3D11 ClearView does); a rectangle that covers the view still…"),
        "cpu-count": Info(title: "Reported CPU count (0 = device)", defaultValue: "0", note: "(experiment: RDR2 sizes its job system from it; iPhone = 2 P + 4 E cores)."),
        "cs-dump": Info(title: "", defaultValue: "0", note: ""),
        "cs-split": Info(title: "", defaultValue: "0", note: "fix: 1 = every compute dispatch ends its compute encoder, so the next one waits on the encoder fence (FSR 3 black squares: ordering inside an encoder); 2 = only FidelityFX ('CS' entry) dispatches"),
        "ctx-frame": Info(title: "", defaultValue: "", note: "syscall-frame context A/B. Documents/madeira-ctx-frame.txt == \"1\" makes ios_fill_thread_context() report a thread parked inside a syscall using its saved Wine syscall frame (TEB+0x378) instead of the Mach-O registers it happens to..."),
        "d3d11": Info(title: "Direct3D 10/11 runtime (x64)", defaultValue: "", note: "Unset: DXMT, Direct3D 10/11 on Metal. \"dxvk\": this session's d3d11.dll, d3d10core.dll and dxgi.dll are DXVK's (Direct3D 10/11 and DXGI on Vulkan, the bundle's vulkan/ folder), replacing DXMT for Direct3D 10/11 and DXGI; Vulkan is on (see v…"),
        "d3d12": Info(title: "Direct3D 12 runtime (x64)", defaultValue: "", note: "Unset: madeira-d3d12, Direct3D 12 on Metal. \"vkd3d\": this session's d3d12.dll and d3d12core.dll are vkd3d-proton's (Direct3D 12 on Vulkan, the bundle's vulkan/ folder) and Vulkan is on (see vulkan). x64 programs only; read at session start…"),
        "d3d12-bc-decode": Info(title: "", defaultValue: "1", note: "1: decode BC uploads (no native BC), 0: raw copies"),
        "d3d12-binding-tier": Info(title: "Reported resource binding tier", defaultValue: "2", note: "Default 2. 3: OPTIONS reports resource binding tier 3, as Apple's D3DMetal and vkd3d-proton do; a game can take another binding path for it. Anything else keeps tier 2. Read once per game start."),
        "d3d12-caps-log": Info(title: "", defaultValue: "1", note: "2: format queries too"),
        "d3d12-core-dll": Info(title: "", defaultValue: "0", note: "1: load d3d12core.dll (Agility SDK layout); >1: also its D3D12SDKVersion"),
        "d3d12-fl-12-1": Info(title: "Claim feature level 12_1", defaultValue: "0", note: "Default off: 12_0 is the highest feature level the runtime claims. 1: 12_1, for a game that creates its device at 12_1 and stops when that is refused; OPTIONS still reports no conservative rasterization or ROVs. Read once per game start."),
        "d3d12-msaa8": Info(title: "", defaultValue: "0", note: "1: report 8x MSAA (rendered at 4x)"),
        "d3d12-pso-cached-blob": Info(title: "Cached blob of a pipeline", defaultValue: "0", note: "Default off: ID3D12PipelineState::GetCachedBlob fails (E_NOTIMPL), as before. 1: it answers a 16-byte blob, for an engine that treats the failure as fatal. Creating a pipeline never reads a blob handed back. Read once per game start."),
        "d3d12-raw-typed-views": Info(title: "Raw buffer views readable as typed", defaultValue: "0", note: "Default off. 1: raw and structured buffer views also carry a texture-buffer view (R32, or RG32/RGBA32 for a structured SRV whose stride allows it), as native drivers and vkd3d-proton do, so a shader that reads one as Buffer<T> gets the dat…"),
        "d3d12-raytracing-tier": Info(title: "Experiment: report a ray-tracing tier", defaultValue: "0", note: "Experiment, default 0. 10 or 11 reports DXR tier 1.0 or 1.1 in OPTIONS5 although the runtime has no ray tracing (its calls stay unimplemented stubs, logged once). Only for finding out whether a game's device check wants it."),
        "d3d12-reserved-max-mb": Info(title: "", defaultValue: "1024", note: "d3d12-tiled-resources: largest reserved resource backed in full, in MB (larger ones are refused with E_OUTOFMEMORY)"),
        "d3d12-shader-pack": Info(title: "D3D12 shader cache in two pack files", defaultValue: "0", note: "Off by default: one file per converted shader in Documents/shadercache, as before. 1: the converter keeps its DXBC and DXIL cache entries in two append-only files (shadercache/pack/dxbc.mdpk, dxil.mdpk); loose entries of earlier runs move…"),
        "d3d12-sm-6-7": Info(title: "Report shader model 6.7", defaultValue: "0", note: "Default off: SHADER_MODEL reports up to 6.6. 1: up to 6.7, for a game that requires it; the converter may still refuse a 6.7 shader, which fails its pipeline like any other conversion failure. Read once per game start."),
        "d3d12-tile-based": Info(title: "", defaultValue: "1", note: "0: TileBasedRenderer FALSE, as desktop GPUs report"),
        "d3d12-tiled-resources": Info(title: "", defaultValue: "0", note: "opt-in: TiledResourcesTier 2, 40 VA bits per resource, R32G32B32 vertex formats, fully backed reserved resources"),
        "d3d12-typed-uav-load": Info(title: "D3D12 typed UAV loads (report support)", defaultValue: "0", note: "FORMAT_SUPPORT below already reports UAV_TYPED_LOAD for every uncompressed colour format (Metal read-write textures), but this option stays FALSE by default: reporting it can move an engine that already runs onto different render..."),
        "d3d12-wave-ops": Info(title: "Report wave operations", defaultValue: "1", note: "On by default. 0: OPTIONS1 reports WaveOps FALSE, so a game with a fallback picks shaders without wave intrinsics (an A/B for the shader converter's wave code; Horizon Zero Dawn reads it). Read once per game start."),
        "d3d12-zero-extent-guard": Info(title: "", defaultValue: "1", note: "1 (default): zero-size textures refused with E_INVALIDARG; 0: passed to Metal, which aborts"),
        "d3d9": Info(title: "Direct3D 9 frontend", defaultValue: "", note: "Unset or \"emulated\": DXMT's D3D9 frontend, translated by FEX in 32-bit programs (x64 programs always get DXMT's native ARM64EC build). \"native\": 32-bit programs run DXMT's frontend as native ARM64 code. \"wined3d\": 32- and 64-bit programs g…"),
        "default-buffer-swap": Info(title: "", defaultValue: "0", note: "fix: 1 = large committed DEFAULT buffers (no UAV/RT/DS) on file-backed storage, 2 = UAV ones too; 0 = Metal-owned private memory (as before)"),
        "default-buffer-swap-max-mb": Info(title: "", defaultValue: "0", note: "default-buffer-swap moves buffers only while the moved total stays at or below this many MB; 0 = no limit"),
        "default-buffer-swap-mb": Info(title: "", defaultValue: "64", note: "fix: default-buffer-swap: the smallest DEFAULT buffer moved, in MB (at least 8)"),
        "default-buffer-swap-wire": Info(title: "", defaultValue: "0", note: "1 = VirtualLock (mlock) default-buffer-swap's storage so its pages stay resident; 0 = pageable (as before)"),
        "desc-guard": Info(title: "", defaultValue: "0", note: "diagnostic: log descriptor writes into shader-visible slots a running batch still uses"),
        "desktop-size": Info(title: "Virtual desktop size (WxH)", defaultValue: "", note: "The developer interface's Wine desktop size ; its Resolution menu writes it . Madeira Dock sessions without a game's Resolution use it too. Unset: this screen's shape at 1280x720's pixel count (1408x648 on a 19.5:9 iPhone, 1152x800 on an 1…"),
        "donor-only": Info(title: "Donor pool without a swap file", defaultValue: "1", note: "on (the default), donor-pool-mb set and swap-mb unset start the swap tier with the donor pool as its only stage: no swap file is made, and memory the pool cannot cover stays normal app memory (iOS compresses it inside the app's limit). 0:…"),
        "donor-pool-guard": Info(title: "Donor pool: memory-pressure guard", defaultValue: "0", note: "what iOS's memory-pressure notification does to the pool. Unset: nothing, the pool is spent like MeloNX's (on an 8 GB phone the critical notification refused 502 takes and left 2.6 GB of the pool unused while the title's own memory, compre…"),
        "donor-pool-kind": Info(title: "Donor pool memory kind", defaultValue: "", note: "how the extension creates each donated region. ledger (the default): a named memory entry tagged to the extension's ledger. purgeable: a purgeable allocation in the extension named by a memory entry (the way MeloNX donates RAM). Everything…"),
        "donor-pool-mb": Info(title: "Donor pool size", defaultValue: "0", note: "RAM for the swap tier that is not counted against Madeira's limit, donated by the MadeiraMemoryHost extension (512 MB regions, created untouched, handed over, then the extension exits). With swap-mb it is the swap tier's first stage, taken…"),
        "draw-dedup": Info(title: "Leave out render state the encoder already has", defaultValue: "1", note: "Default on. A draw no longer sends Metal the pipeline, viewport, scissor, depth-stencil state, blend colour, rasterizer state or buffer bindings the render encoder already holds from the draw before it; a buffer bound again with only a new…"),
        "dump-shaders": Info(title: "", defaultValue: "", note: "madeira.cfg dump-shaders = mdc_x,mdc_y -> Documents/capture/shader_<name>.dxbc, written BEFORE the cache lookup so a cached shader is dumped too."),
        "dxbc-register-spaces": Info(title: "Shader model 5.1 resources in register spaces other than 0", defaultValue: "0", note: "Default off: a DXBC shader (shader model 5.1) that declares a resource in a register space other than 0 is refused, and its pipeline is not created. 1: such shaders are converted, and each resource is bound from the root-signature entry wi…"),
        "dxil-dump": Info(title: "", defaultValue: "", note: "diagnostic: log the bytecode of pipelines with these entry names"),
        "dxil-tess": Info(title: "", defaultValue: "1", note: "(IRRuntimeNewGeometryTessellationEmulationPipeline): the vertex shader becomes the object function with tessellation on, the hull shader two functions linked into it (hull and tessellator), the domain shader a function linked into the me..."),
        "dxil-tess-max-factor": Info(title: "", defaultValue: "3", note: "particles through tessellated quads (ls_SetColor, max factor 9): 5,000-7,700 of them, drawn three times a frame, once the fires are going ([probe] log 2026-09-28 14:04) -- up to 162 triangles each through the emulation, and the GPU time ..."),
        "dxil-tess-patch-topology": Info(title: "Experiment: DXIL tessellation with the patch input topology", defaultValue: "0", note: "Experiment, default off. 1: the stages of a DXIL tessellation pipeline are converted with the converter's patch input topology instead of triangles; such shaders are cached apart."),
        "dxmt": Info(title: "DXMT options (a=b;c=d)", defaultValue: "", note: "Exported as DXMT_CONFIG with the options joined by ';', a library game's own dxmt options after these: e.g. d3d11.mipClampBC=1;d3d11.preferredMaxFrameRate=30. DXMT reads at most 259 characters of it, and nothing at all from a longer value ."),
        "eco": Info(title: "Eco scheduling", defaultValue: "0", note: "Runs guest threads at a lower iOS QoS class so the system favours efficiency and saves power; can cost speed. Class chosen by eco-qos."),
        "eco-qos": Info(title: "Eco QoS class", defaultValue: "", note: "The QoS class guest threads run at while eco is on."),
        "encode-batch": Info(title: "One Metal call per encoder, not per draw", defaultValue: "1", note: "Default on. The commands a replay hands to one Metal encoder (every draw's state and draw, the encoder's fence wait and update) are queued and handed over in one call when the encoder ends, instead of one call into the Metal bridge per dra…"),
        "encoder-labels": Info(title: "", defaultValue: "0", note: "madeira.cfg encoder-labels = 1 names every Metal encoder after the pass that opened it (\"R#<seq> <vs>|<ps>\", \"C#<seq> <kernel>\", \"B#<seq> copy\"), so Instruments' Metal System Trace attributes GPU time per pass. Off by default: on..."),
        "env.": Info(title: "", defaultValue: "", note: "`env.NAME` from madeira.cfg, then the process environment. \"0\" is off."),
        "env.DOTNET_EnableWriteXorExecute": Info(title: ".NET runtime: W^X mapping", defaultValue: "", note: "Passed into the game's environment and read by the .NET (CoreCLR) runtime itself. 0 turns off its write-xor-execute double mapping of JIT code, for a .NET game whose JIT stops at start."),
        "env.DOTNET_GCRegionRange": Info(title: ".NET runtime: GC region reservation", defaultValue: "", note: "Passed into the game's environment and read by the .NET runtime: the size (hex bytes) of the address range its regions GC reserves at start, for a .NET game whose default reservation fails."),
        "env.DXMT_AIRCONV_DUMP": Info(title: "", defaultValue: "", note: "Env-gated metallib dump: point DXMT_AIRCONV_DUMP at a directory and every DXSOCompile call drops a {kind}_{hash}.metallib there. Disassemble with `xcrun air-objdump -d <file>` to inspect what AGX actually receives. Only meant for triage ..."),
        "env.DXMT_API_CENSUS": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_CACHE_STATS": Info(title: "", defaultValue: "", note: "Opt-in diagnostics: DXMT_CACHE_STATS=1 logs hit/miss counts."),
        "env.DXMT_CAPTURE_EXECUTABLE": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_CAPTURE_FRAME": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_CENSUS_THROTTLE": Info(title: "", defaultValue: "32-bit only", note: "first report of the process is always emitted too, so a run that dies inside the first 10 s still leaves one. * Wall time, not the seq id: the seq id advances at the GPU's pace, so a per-N-seq gate throttles by frame rate and not by time..."),
        "env.DXMT_CLEAR_DISCARD_STORE": Info(title: "", defaultValue: "32-bit only", note: "MADEIRA : DXMT_CLEAR_DISCARD_STORE is a Madeira switch (util_madeira_switch.hpp), on by default only in the i386 build."),
        "env.DXMT_CMDLIST_KEEP_BLOCK": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_CMD_CENSUS": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_CONFIG": Info(title: "", defaultValue: "", note: "Load either $DXMT_CONFIG_FILE or $PWD/dxmt.conf"),
        "env.DXMT_CONFIG_FILE": Info(title: "", defaultValue: "", note: "Load either $DXMT_CONFIG_FILE or $PWD/dxmt.conf"),
        "env.DXMT_D9_ANISO_LIMIT": Info(title: "", defaultValue: "", note: "Written only by the encode thread (Resolve allocates, commit seals); opt into the DXMT_DEBUG single-writer assertion. single_writer= true"),
        "env.DXMT_D9_BATCH_READBACK": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_D9_BINDING_PRUNE": Info(title: "", defaultValue: "", note: "The compiler emits bindings only for sampled stages. Avoid sampler-cache probes, Metal texture-view creation and resource retention for stale bindings outside that mask. Fixed-function combiners retain their path."),
        "env.DXMT_D9_CANONICAL_BLEND": Info(title: "", defaultValue: "", note: "Disabled blending ignores all six operation/factor fields. Canonicalize before both hashing and collision checks to share the same Metal PSO."),
        "env.DXMT_D9_EXTENTLOG": Info(title: "", defaultValue: "", note: "— THE EXTENT LINE IS NOT A TRACE, IT IS THE ANSWER. \"The right fifth of the picture is missing\" has exactly one arithmetic cause in this path -- a back buffer presented 1:1 into a destination narrower than it is -- and exactly one..."),
        "env.DXMT_D9_LATE_READBACK": Info(title: "", defaultValue: "", note: "Opt-in (default off). Serves tiny GetRenderTargetData readbacks, such as a 1x1 exposure sample, one frame late instead of waiting on the GPU. Applies to 32-bit D3D9 games that read a small render target back every frame."),
        "env.DXMT_D9_LOCKLOG": Info(title: "", defaultValue: "", note: "managed sweep, a plain lock pushes its own rect, and a SYSTEMMEM lock pushes nothing because UpdateTexture is the consumer. Those are four different bugs wearing one symptom. Deduped on (pool, usage, format, extent, full-vs-sub, flags) a..."),
        "env.DXMT_D9_NODIRTY_SWEEP": Info(title: "", defaultValue: "", note: "mirror, the GPU copy kept whatever it last received, and only an explicit AddDirtyRect or EvictManagedResources could ever dislodge them. A texture that is written once, drawn, then rewritten in place therefore kept showing its first con..."),
        "env.DXMT_D9_PIPELINE_STATS": Info(title: "", defaultValue: "", note: "reference compiles a cold pipeline synchronously at the draw site (wined3d on its CS thread, DXVK's default and non-GPL-fallback paths, and the d3d11 sibling's blocking GetPipeline). Skipping the draw instead, the way an async fork does,..."),
        "env.DXMT_D9_QUERY_ADAPTIVE": Info(title: "", defaultValue: "", note: "the old lifetime count penalized an asynchronous culling loop after its third check, even if those checks were a frame apart. Keep cooperative back-pressure for tight polling only. A 250us gap starts a new burst; completed querie..."),
        "env.DXMT_D9_READBACK_STATS": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_D9_RENAME_WAIT": Info(title: "", defaultValue: "", note: "Rename drain from thebcd69/bcd-dxmt, commit 8ae252b (LGPL-2.1-or-later)."),
        "env.DXMT_D9_SCENE_BATCH": Info(title: "", defaultValue: "", note: "Written only by the encode thread (Resolve allocates, commit seals); opt into the DXMT_DEBUG single-writer assertion. single_writer= true"),
        "env.DXMT_D9_SHADER_PRUNE": Info(title: "", defaultValue: "", note: "The compiler's binding pre-scan and this metadata mask use the same dxso_opcode_samples/dxso_sampling_slot helpers (including SM1 implicit stages). Unread slots never enter its signature or lowering. Keeping their live texture kinds in t..."),
        "env.DXMT_D9_SMALL_MIRROR_CACHE": Info(title: "", defaultValue: "", note: "Small MANAGED mirrors are inexpensive, but reconstructing even a tiny one drains the GPU queue. Keep a bounded working set without changing LockRect visibility or discarding the CPU's authoritative bytes. Shared across devices in this mo..."),
        "env.DXMT_D9_SUBMIT_STATS": Info(title: "", defaultValue: "", note: "Device lock serializes callers. Report causes, not just GPU totals: an upload queue can also submit buffers independently of these chunks."),
        "env.DXMT_D9_UPLOAD_COMMIT_MB": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_D9_VIRTUAL_MODE": Info(title: "", defaultValue: "", note: "Fullscreen rect: the window's monitor origin plus the backbuffer extent. on iOS the old borderless-only path left a large fullscreen window on a smaller virtual desktop, so pointer clamping stopped short. This is a virtual win32u..."),
        "env.DXMT_DISPLAY_MODE_STATS": Info(title: "", defaultValue: "", note: "MADEIRA : opt-in diagnostics, DXMT_DISPLAY_MODE_STATS=1."),
        "env.DXMT_DUMP_D9_LAYOUT": Info(title: "", defaultValue: "", note: "Triage: dump unique layouts under DXMT_DUMP_D9_LAYOUT=1 so we can see what D3DDECLTYPE -> MTLAttributeFormat the host is feeding the manual-fetch path. Useful when a class of draws renders wrong and the suspect is a format mismatch insid..."),
        "env.DXMT_DUMP_D9_SHADER": Info(title: "", defaultValue: "", note: "One-shot env-var read. DXMT_DUMP_D9_SHADER=1 enables a per-create summary line via Logger::warn (so it shows up in d3d9.log alongside the first-call traces). Off by default to avoid unconditional spam from apps that create hundreds of sh..."),
        "env.DXMT_DUMP_PATH": Info(title: "", defaultValue: "", note: "Optional bytecode-to-disk dump. Empty -> disabled. Set to a writable directory path; we write one file per unique bytecode hash, so the session ends with a directory containing every shader the app created."),
        "env.DXMT_DYN_KEEP": Info(title: "", defaultValue: "", note: "retires ~600 names a frame; as soon as the GPU catches up, the trim below frees all but 64, and the next frame mints ~540 brand-new Metal buffers for it again: 15-30k fresh MTLBuffers a second (~1000 a frame, avg 438 bytes), each a newBu..."),
        "env.DXMT_DYN_KEEP_KB": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_ENABLE_NVEXT": Info(title: "Report an NVIDIA GPU (all games)", defaultValue: "", note: "1: DXGI names NVIDIA as the vendor, DXMT's NVAPI answers and win32u registers the display adapter as a GeForce RTX 3060 (driver 581.57). Per game: Game details > Report an NVIDIA GPU, which also sets the matching DXGI device id."),
        "env.DXMT_IOS_CACHE_DIR": Info(title: "", defaultValue: "", note: "shader cache persists. With the switch on, a relative path resolves under the app's NSCachesDirectory instead and a directory that cannot be created fails cleanly. * Decided per caller, like winemetal_unix.c's madeira_switch_for_caller: ..."),
        "env.DXMT_LOG_LEVEL": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_LOG_PATH": Info(title: "", defaultValue: "", note: "guard on the bool, NOT on the stream -- see log.hpp."),
        "env.DXMT_MAX_VRAM_MB": Info(title: "", defaultValue: "", note: "Returning the strictly-truthful UMA answer (0) drives era-typical engines into recreate-every-frame fallbacks. Mirror dxgi/d3d11: half of recommendedMaxWorkingSetSize (available_texture_mem_bytes halves on unified memory), clamped below ..."),
        "env.DXMT_METALFX_SPATIAL_SWAPCHAIN": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_PRECISE_MINMAX": Info(title: "", defaultValue: "", note: "madeira DXBC min/max are IEEE minNum/maxNum: when one operand is NaN the other one is returned, and shaders rely on max(0, x) to throw NaNs away. Metal's fast_fmin/fast_fmax leave the NaN case undefined, so a NaN from a degenerat..."),
        "env.DXMT_QUERY_SETTLE_EMPTY": Info(title: "", defaultValue: "32-bit only", note: ""),
        "env.DXMT_REMOTE_BATCH": Info(title: "", defaultValue: "", note: "coalescing is OPT-IN. With it off this build behaves exactly as did, which is what makes a matched baseline measurement possible."),
        "env.DXMT_REMOTE_METAL": Info(title: "", defaultValue: "", note: "Decided once. DXMT_REMOTE_METAL=<host-ip> turns it on. Decided exactly once. The gate sits on EVERY dispatch entry, so without this two threads racing the first call would each open a socket: one leaks and wmtr_fd changes under a call al..."),
        "env.DXMT_RING_OVERSIZE_REUSE": Info(title: "", defaultValue: "32-bit only", note: "DXMT_RING_OVERSIZE_REUSE is a Madeira switch (util_madeira_switch.hpp): on by default only in the i386 build. Every 64-bit build keeps the upstream block lifetime unless it is set."),
        "env.DXMT_SHADER_CACHE": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_SHADER_CACHE_PATH": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_SHADOW_PACK": Info(title: "", defaultValue: "", note: ""),
        "env.DXMT_SMALL_RINGS": Info(title: "Small DXMT staging rings for these programs", defaultValue: "", note: "Read by DXMT's d3d11 with the small-rings change. Program file names separated by ';' (e.g. Launcher.exe;SocialClubHelper.exe), or 1 for every program: in those programs DXMT's staging ring, copy-temp ring and upload heap use 4 MB Metal bl…"),
        "env.DXMT_USE_DEFAULT_METAL_CACHE": Info(title: "", defaultValue: "", note: "Pin Metal's own shader and pipeline cache to the per-executable directory the disk shader cache uses (the d3d11 backend does the same at provider init). Without it the OS cache keys off the wine loader's identity and pipeline links never..."),
        "env.DXMT_WAIT_ON_ADDRESS": Info(title: "", defaultValue: "32-bit only", note: "A Madeira switch (util_madeira_switch.hpp): the i386 build uses the address wait by default; every 64-bit build keeps std::atomic, which is upstream behaviour, unless DXMT_WAIT_ON_ADDRESS is set. Only the non-upstream choice is logged."),
        "env.DXMT_WSI_MODE_TABLE": Info(title: "", defaultValue: "32-bit only", note: ""),
        "env.DXMT_WSI_MONITOR_IDENTITY": Info(title: "", defaultValue: "32-bit only", note: "The native frontend (DXMT_MADEIRA) has no user32 boundary and always uses the internal singleton."),
        "env.DXMT_ZERO_BUFFER_POW2": Info(title: "", defaultValue: "32-bit only", note: "MADEIRA : with DXMT_ZERO_BUFFER_POW2, grow to the next power of two (at least 1 MB) instead of the exact request. Each growth costs a flushInternal(), and a loading screen asking for slowly rising sizes regrew the buffer 322 time..."),
        "env.DXVK_CONFIG": Info(title: "DXVK options", defaultValue: "", note: "dxvk.conf options inline, separated by ';' (e.g. dxgi.maxFrameRate=60;d3d11.cachedDynamicResources=a); applied after the config file; with d3d11 = dxvk."),
        "env.DXVK_CONFIG_FILE": Info(title: "DXVK config file", defaultValue: "", note: "A dxvk.conf to read instead of the one in the program's working folder (a Windows path, e.g. C:\\users\\madeira\\dxvk.conf); with d3d11 = dxvk. See DXVK's dxvk.conf for the options."),
        "env.DXVK_LOG_LEVEL": Info(title: "DXVK log level", defaultValue: "", note: "DXVK's log (none, error, warn, info, debug, trace), written to the session log through Wine's debug output. d3d11 = dxvk sets info unless this is set."),
        "env.LC_ALL": Info(title: "Wine's locale for this game", defaultValue: "", note: "Empty: Wine takes the user locale from the device's language. en_US.UTF-8 gives the game an English system and user locale, for a game that fails right after loading a non-English OEM code page. Read at session start."),
        "env.MADEIRA_AFD_EVENT_HANDLE": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_AGS_ROUNDTRIP_ONLY": Info(title: "", defaultValue: "", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1"),
        "env.MADEIRA_ALIAS_PER_PROCESS": Info(title: "", defaultValue: "", note: "Default on. 0 restores the old pushes: every image goes to the emulator that registered last, and a registration drains every process's images."),
        "env.MADEIRA_ALIAS_RELEASE": Info(title: "Drop a released arena's code copies", defaultValue: "0", note: "Default off. 1: anonymous memory the game made executable (copied into the JIT pool) follows the game's MEM_RELEASE and MEM_DECOMMIT: a released view drops its copies' records, a decommit zeroes each copy in its pool slot. For a game that…"),
        "env.MADEIRA_ANON_CAS_FLUSH": Info(title: "Atomic code patches go through the emulator", defaultValue: "0", note: "Default off: a compare-and-swap the game does on its own executable memory (a .NET runtime patching a stub it ran) is completed by the host. 1: it is handed to the emulator, which discards its translation of the page first, as in older bui…"),
        "env.MADEIRA_APC_BUSY_QUEUE": Info(title: "", defaultValue: "", note: "thread runs it at its next wait in the server: check_wait returns STATUS_KERNEL_APC for any interruptible wait, and a fastsync wait parks in process for at most MADEIRA_FASTSYNC_CAP_US (2 ms) before it falls through to the server. It is ..."),
        "env.MADEIRA_APC_REQUEUE": Info(title: "", defaultValue: "", note: "On by default: an async I/O completion for a busy thread goes to a waiting thread of its process, if there is one, instead of failing the I/O. 0 always drops it again."),
        "env.MADEIRA_APP_DLL_SHADOW": Info(title: "Ignore these DLLs in the game's folder", defaultValue: "", note: "Default empty. DLL names separated by ';' (e.g. vcruntime140.dll): a plain x64 copy of one of them outside C:\\windows (the game's own folder) is reported as not loadable, so the loader binds the system's, as it already does for ucrtbase.dl…"),
        "env.MADEIRA_APP_IMAGE_UUID": Info(title: "", defaultValue: "", note: "set by the app: not a switch"),
        "env.MADEIRA_APP_UCRT": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_ARENA_GUARD": Info(title: "", defaultValue: "", note: "On by default. MADEIRA_ARENA_GUARD=0 lets a fixed or hinted guest reservation take FEX arena space again."),
        "env.MADEIRA_ARENA_TEST": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_ARGS": Info(title: "", defaultValue: "", note: "Optional MADEIRA_ARGS: Windows command-line quoting (CommandLineToArgvW rules), at most 64 arguments in 4 KB. Malformed or oversized input fails the launch instead of silently dropping or splitting arguments."),
        "env.MADEIRA_ATOM_ARG": Info(title: "Atoms in a 32-bit program's class and property names", defaultValue: "1", note: "Default on: a class or property name given as an atom that arrives offset by the 32-bit program's window base (inside its never-mapped first 64 KB) is taken as the atom, not read as a string pointer. 0 turns it off."),
        "env.MADEIRA_AUDIO_DOWNMIX": Info(title: "Mix surround sound down to stereo", defaultValue: "1", note: "On by default: a game that plays 5.1 or 7.1 sound has every channel folded into the two speakers, so voices (in the centre channel), bass and the rear channels are heard. Off keeps only the front left and right channels, as Madeira did bef…"),
        "env.MADEIRA_AUDIO_GAIN": Info(title: "Game volume at the output (%)", defaultValue: "100", note: "Percent of the game's level, 10-200; unset or 100 leaves it unchanged. Read once, at the first audio endpoint. Set it in the game's own file."),
        "env.MADEIRA_AUDIO_IO_MS": Info(title: "", defaultValue: "", note: "A shared-mode client that keeps only one 10 ms engine period queued (IAudioClient3 low latency) loses audio when RemoteIO pulls a larger slice per callback (iOS's default is ~1024 frames, 21 ms): every callback empties the queue and play..."),
        "env.MADEIRA_AUDIO_IO_US": Info(title: "", defaultValue: "", note: "The shared-mode engine period, in 100 ns units. A client that keeps one period queued (IAudioClient3) must cover a whole RemoteIO slice, or every render callback empties its queue and plays silence for the rest: at least two slices of th..."),
        "env.MADEIRA_AUDIO_LEAD_MS": Info(title: "Sound buffer", defaultValue: "", note: "How much sound Madeira keeps queued ahead of the speaker (10-500 ms, default 60). If a game's sound crackles or sounds scratchy, a larger buffer usually clears it, at the cost of sound lagging slightly behind the picture: Black Ops II's Zo…"),
        "env.MADEIRA_AUDIO_PERIOD_MS": Info(title: "", defaultValue: "", note: "The shared-mode engine period, in 100 ns units. A client that keeps one period queued (IAudioClient3) must cover a whole RemoteIO slice, or every render callback empties its queue and plays silence for the rest: at least two slices of th..."),
        "env.MADEIRA_AUDIO_RESUME": Info(title: "Bring game audio back after an interruption", defaultValue: "0", note: "Default off: after a call, Siri, an alarm or a suspension the sound stays off until the game restarts. 1: the audio session is activated again and the output restarted; while iOS holds it stopped the game's audio clock keeps running. Logge…"),
        "env.MADEIRA_AUDIO_SPATIAL": Info(title: "", defaultValue: "", note: "0: no spatial audio (a game falls back to a plain stream); unset or 1: Wine's spatial audio, as before"),
        "env.MADEIRA_AUX_IAT_HEAL": Info(title: "", defaultValue: "", note: "0: EC import stubs keep the exec-fault redirect"),
        "env.MADEIRA_BACKGROUND_DOWNLOADS": Info(title: "", defaultValue: "1", note: "On iOS 26 and later, Steam downloads continue in the background as a continued-processing task that iOS shows with its progress. 0: only the short grace period, then a clean pause until Madeira is active again."),
        "env.MADEIRA_BAND_CENSUS": Info(title: "Log the 64 GB address band by piece", defaultValue: "0", note: "Default off. 1: about once a minute and when a large reserve fails, [band] lines say what each piece of [0x7000000000, 0x8000000000) uses (Social Club's pools and metadata, the furniture, the V8 and Oilpan cages, the FEX arena), the larges…"),
        "env.MADEIRA_BG_QOS_DELAY_S": Info(title: "", defaultValue: "", note: "seconds the game must present before the listed processes are demoted (default 60)"),
        "env.MADEIRA_BG_QOS_PROCS": Info(title: "", defaultValue: "", note: "';'-separated exe names demoted to utility QoS while the game presents; empty = off"),
        "env.MADEIRA_BIG_PICTURE_DOCK_LIBRARIES": Info(title: "Big Picture: every library Madeira lists", defaultValue: "1", note: "on (default): Big Picture's libraryfolders.vdf gets every library Madeira's Steam list reads: the Dock client's folder, the other C: libraries its libraryfolders.vdf names and the external drives' libraries. The log names each library with…"),
        "env.MADEIRA_BIG_PICTURE_GPU": Info(title: "Big Picture: draw the UI with the GPU", defaultValue: "0", note: "1 starts steam.exe without -cef-disable-gpu, so the web helper may draw with Chromium's ANGLE on the 32-bit D3D11 (DXMT) instead of the CPU. Off by default (software drawing, as before); a test switch."),
        "env.MADEIRA_BIG_PICTURE_LIBRARIES": Info(title: "Big Picture: list Madeira's Steam games", defaultValue: "1", note: "on (default): before each Big Picture start, Big Picture's libraryfolders.vdf (config/ and steamapps/) gets Madeira's Steam library (the Dock client's folder) and the libraries on connected drives, beside the client's own entries, so the g…"),
        "env.MADEIRA_BIG_PICTURE_PIN": Info(title: "Big Picture: keep the installed 32-bit client", defaultValue: "1", note: "on (default): once Big Picture's folder holds the 32-bit client's web helper (bin/cef/cef.win7), steam.exe starts with -nobootstrapperupdate -skipinitialbootstrap, so it cannot move itself to the 64-bit client, whose CEF pools do not fit t…"),
        "env.MADEIRA_BLOCK_RING": Info(title: "", defaultValue: "", note: "the block-entry ring, when MADEIRA_BLOCK_RING is set (32 KB per thread, never freed)."),
        "env.MADEIRA_BUILD_LABEL": Info(title: "", defaultValue: "1", note: "Which build is installed, shown in light grey in the developer interface, and logged once at start ([build]). A build that writes `MadeiraBuild` into Info.plist (a round tag and build time) shows that; other builds show the bundle versio..."),
        "env.MADEIRA_BUS_SYSCALL_FAULT": Info(title: "", defaultValue: "", note: "frame is inside the stack limits, and the process ended. A program that probes memory the IsBadReadPtr way (for example NtReadVirtualMemory on a guard page of its own stack) expects the call to fail with a status, not to die. * When a __..."),
        "env.MADEIRA_CAGE_RELEASE": Info(title: "", defaultValue: "", note: "1: when the guest band is exhausted, hand the unclaimed 8 GB V8 cage holdback to it. Set by the app for a Madeira Dock session; off otherwise."),
        "env.MADEIRA_CALLRET_RESET_RATE": Info(title: "", defaultValue: "", note: "MADEIRA: rate-limit the call-ret reset that follows a code invalidation. * On the iOS host nothing reads the stack's contents: the RET shortcut (BranchOps.cpp, ) and the EnterEC return (Dispatcher.cpp) are compiled out, so a skipped..."),
        "env.MADEIRA_CA_BUNDLE": Info(title: "", defaultValue: "", note: "iOS-Madeira: no system root store API on iOS. WineProcessBridge.m points MADEIRA_CA_BUNDLE at the bundled Mozilla cacert.pem (concatenated PEM — same format as ca-certificates.crt, which import_certs_from_file already parses)."),
        "env.MADEIRA_CEF_VERBOSE": Info(title: "Steam web helper: verbose CEF log", defaultValue: "1", note: "on (default): steamwebhelper.exe gets --enable-logging=file --v=1 --log-severity=verbose, CEF's verbose file log. 0 (the Steam Big Picture list): Steam's own log level, which saves the UI threads the writes."),
        "env.MADEIRA_CFG_EARLY_DOCS": Info(title: "", defaultValue: "", note: "Directory that holds the configuration: $MADEIRA_DOCS_DIR, else the app container's Documents from $CFFIXED_USER_HOME, else $HOME/Documents. * The in-app wineserver thread sets HOME to the Wine prefix (Documents/wine) before it creates i..."),
        "env.MADEIRA_CFG_GAME": Info(title: "", defaultValue: "", note: "set by the app for a library game's own lines; not a madeira.cfg option"),
        "env.MADEIRA_CHILD_ARGS": Info(title: "", defaultValue: "", note: "madeira-bcd: env.MADEIRA_CHILD_ARGS -- see child_extra_args."),
        "env.MADEIRA_CHILD_BOOT_SERIAL": Info(title: "", defaultValue: "", note: "0: child processes boot at once, side by side, as before"),
        "env.MADEIRA_CHILD_DESKTOP": Info(title: "", defaultValue: "", note: "Default on; 0 keeps a child without a desktop window, as before."),
        "env.MADEIRA_CHILD_NTDLL_STRICT": Info(title: "", defaultValue: "", note: "do not start a process on the SHARED ntdll copy. Its .data (PEB-derived loader state, module list, loader lock) belongs to another process: device log 95's conhost (started by a 32-bit browser's AllocConsole while the JIT pool wa..."),
        "env.MADEIRA_CLICK_FOCUS": Info(title: "", defaultValue: "", note: "0: a tap or click on an active window leaves its keyboard focus as it is"),
        "env.MADEIRA_CLIP_NOTIFY_ALWAYS": Info(title: "", defaultValue: "", note: "1: notify the foreground thread on every ClipCursor, as before"),
        "env.MADEIRA_CONHOST_HEADLESS": Info(title: "", defaultValue: "", note: "madeira-conhost-headless: a pipe cannot be a --unix console's tty (the server calls tcgetattr on it); --headless takes the same standard handles and needs no terminal device. env.MADEIRA_CONHOST_HEADLESS = 1."),
        "env.MADEIRA_CONSOLE_WINDOW": Info(title: "", defaultValue: "", note: "1: consoles keep their conhost window (default: none, as with CREATE_NO_WINDOW)"),
        "env.MADEIRA_CONTROLS_EDITOR_DONE": Info(title: "", defaultValue: "1", note: "while editing, a Done button ends the edit (keeping it in the active custom layout) in place of the checkmark, and the show/hide glyph is hidden. MADEIRA_CONTROLS_EDITOR_DONE=0 restores the previous bar."),
        "env.MADEIRA_CONTROL_PRESETS": Info(title: "", defaultValue: "1", note: "Owns madeira-control-presets.json and applies layouts to TouchControlsModel. Main thread only, like the overlay that drives it."),
        "env.MADEIRA_COW_OLD_PROT_RW": Info(title: "", defaultValue: "", note: "Windows reports a copy-on-write image page as read-write once it has been written (its private copy exists). Wine maps image pages writable from the start and cannot tell, so it always said WRITECOPY; V8 CHECKs that the flags pag..."),
        "env.MADEIRA_CPU_COUNT": Info(title: "", defaultValue: "", note: "MADEIRA_CPU_COUNT, a per-launch setting the app exports for one program, wins over the global key; unset = the key's behaviour."),
        "env.MADEIRA_CREATE_VIEW_REFUSE": Info(title: "", defaultValue: "", note: "Create a view. virtual_mutex must be held by caller. create-view refuse: a title died here 89 s in, while FEX started a thread and asked for 16 MB: \"Assertion failed: (view->protect & VPROT_SYSTEM), function create_view\", exit 0x80000101..."),
        "env.MADEIRA_CS_X64": Info(title: "", defaultValue: "0", note: "x64 fast path for EnterCriticalSection/LeaveCriticalSection/TryEnterCriticalSection. Default off (experimental). 1: an uncontended or recursive critical section is taken and released inside the x64 JIT code instead of a round trip into n..."),
        "env.MADEIRA_CTX_CPU_AREA": Info(title: "Cross-thread GetThreadContext from the x64 snapshot", defaultValue: "", note: "Another thread's GetThreadContext when the server has no control registers for it. Unset or 0 (default): off; the answer is the server's registers. 1 (upstream's opt-in): the control registers (Pc/Sp/Fp/Lr) from the thread's last exit from…"),
        "env.MADEIRA_CTX_FP": Info(title: "", defaultValue: "", note: "MADEIRA_CTX_FP=0: a cross-thread GetThreadContext returns zeroed vector registers, as before. madeira.cfg (and the game's own lines) are read first: this server starts before the app exports env.* lines and runs again for the ne..."),
        "env.MADEIRA_CTX_FRAME": Info(title: "", defaultValue: "", note: "a live mirror, which is why four of five stalled threads reported rip=0. * Selector mirrors is_inside_syscall() exactly: kernel_stack <= sp <= syscall_frame. NOT \"native pc is not EC\" -- FEX JIT code is also non-EC but its frame may be s..."),
        "env.MADEIRA_D3D12_CAPS_BY_FAMILY": Info(title: "Report 64-bit atomics and wave operations by GPU", defaultValue: "0", note: "Default off: both are claimed on every GPU, as before. 1: 64-bit atomics (OPTIONS9, OPTIONS11) only on Apple9 GPUs (A17 Pro, A18, M3 and later) and wave operations (OPTIONS1) only from Apple7 (A14, M1), for an engine that picks shader path…"),
        "env.MADEIRA_D3D12_CS_DUMP": Info(title: "", defaultValue: "", note: "400 files into C:\\madeira-cs on every run cost startup time for a diagnostic that is only wanted while chasing one kernel."),
        "env.MADEIRA_D3D12_DXIL_CACHE": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_D3D12_DXIL_CACHE_MB": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_D3D12_ONEPASS": Info(title: "", defaultValue: "", note: "one conversion call instead of two. The size-then-fill protocol ran the whole compiler for the size query and again for the fill (the DXIL path had no cache to catch the second). A first buffer of four times the input plus 64 KB ..."),
        "env.MADEIRA_D3D12_RS_DESERIALIZER": Info(title: "", defaultValue: "", note: "Read once. The switch exists so a device regression can be separated from this path without a rebuild."),
        "env.MADEIRA_D3D12_TYPED_UAV_LOAD": Info(title: "", defaultValue: "", note: "FORMAT_SUPPORT below already reports UAV_TYPED_LOAD for every uncompressed colour format (Metal read-write textures), but this option stays FALSE by default: reporting it can move an engine that already runs onto different render..."),
        "env.MADEIRA_D3D9": Info(title: "", defaultValue: "", note: "the d3d9 key's value: emulated (default) or native = DXMT's i386 shim; wined3d = Wine's d3d9 on wined3d/OpenGL for 32- and 64-bit programs"),
        "env.MADEIRA_D3D9_BATCH_BUDGET": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_D3D9_BATCH_USED": Info(title: "", defaultValue: "", note: "charge used bytes and trim sparse small captures, so retention and the pressure submit follow real work. MADEIRA_D3D9_BATCH_USED=0 restores 's capacity charge and 8 MiB threshold."),
        "env.MADEIRA_D3D9_CENSUS": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_D3D9_CENSUS_EVERY": Info(title: "", defaultValue: "", note: "the ring is opt-in now. See the note in d3d9_census.hpp -- it is forensics, not a measurement, and it was the second emulated locked RMW on a 5540-calls-per-frame path. MADEIRA_D3D9_LAST=1 in Documents/madeira-env.txt brings it ba..."),
        "env.MADEIRA_D3D9_DIRECT_MAP": Info(title: "", defaultValue: "", note: "Direct mapping (d3d9_buffer_map.hpp): a 64-bit guest can address Metal's own allocation, so both premises of the mirror are gone for it. The native ARM64 frontend also builds without __i386__ but serves 32-bit guests (DXMT_MADEIRA), so i..."),
        "env.MADEIRA_D3D9_INDEX_RANGE": Info(title: "Direct3D 9: upload only the index bytes a draw reads", defaultValue: "1", note: "On by default. A 32-bit Direct3D 9 game writes its index buffers through a copy Madeira keeps; an indexed draw now copies only the indices it reads into the buffer the GPU reads, instead of the whole buffer before every draw after a lock (…"),
        "env.MADEIRA_D3D9_LAST": Info(title: "", defaultValue: "", note: "the ring is opt-in now. See the note in d3d9_census.hpp -- it is forensics, not a measurement, and it was the second emulated locked RMW on a 5540-calls-per-frame path. MADEIRA_D3D9_LAST=1 in Documents/madeira-env.txt brings it ba..."),
        "env.MADEIRA_D3D9_LOCKCHECK": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_D3D9_LUMINANCE_RT": Info(title: "Direct3D 9: luminance formats as render targets", defaultValue: "1", note: "On by default. A Direct3D 9 program may render into an L8, A8L8 or L16 texture (one-channel targets for ambient occlusion, blur passes or masks), as native drivers and DXVK allow; DXMT used to refuse the texture, and a program that builds…"),
        "env.MADEIRA_D3D9_MIRROR_BATCH": Info(title: "", defaultValue: "", note: "ensureMirror (run by the surface before this) re-allocated a blank backing; download the face's bytes back from the Metal texture so the Lock hands out the real contents. every stale face/level in one drain (see MTLD3D9Texture::m..."),
        "env.MADEIRA_D3D9_NATIVE_CENSUS": Info(title: "", defaultValue: "", note: "Read the two knobs once, from _d3d9_init, on the guest's own thread."),
        "env.MADEIRA_D3D9_NATIVE_CENSUS_EVERY": Info(title: "", defaultValue: "", note: "Read the two knobs once, from _d3d9_init, on the guest's own thread."),
        "env.MADEIRA_D3D9_TRACE": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_D3D9_X64": Info(title: "", defaultValue: "", note: "MADEIRA: the 64-bit (ARM64EC) build is the x64 programs' d3d9.dll, in place of Wine's, which needs OpenGL and so always failed to create here. MADEIRA_D3D9_X64=0 makes creation fail the same way again."),
        "env.MADEIRA_D9_LOCK_BACKOFF": Info(title: "", defaultValue: "", note: "~2000 pauses + a yield per round: 256 rounds is several milliseconds of pure yielding before the waiter starts parking for 1 ms at a time."),
        "env.MADEIRA_D9_LOCK_DIAG": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_DEAD_RELEASE": Info(title: "", defaultValue: "", note: "getenv once, not per release"),
        "env.MADEIRA_DEBUG_VERBOSE": Info(title: "", defaultValue: "", note: "Wine trace channels. * 2026-05-19 perf pivot: the verbose default (err+all, fixme+all, warn+module, warn+file, trace+process, trace+module, trace+loaddll, trace+loadorder, trace+win, trace+user32, trace+syscall, trace+file) was generatin..."),
        "env.MADEIRA_DEFER_SECTION_ABORT": Info(title: "", defaultValue: "", note: "MADEIRA_DEFER_SECTION_ABORT=0: a killed thread exits at once, even inside a section"),
        "env.MADEIRA_DEP_PER_PROCESS": Info(title: "", defaultValue: "", note: "(SetProcessDEPPolicy, permanent) therefore switched DEP back on for a running 32-bit game that had turned it off, and virtual_set_force_exec's sweep re-protected every view of every pseudo-process from the browser's thread: every executa..."),
        "env.MADEIRA_DESKTOP": Info(title: "", defaultValue: "", note: "X-desktop probe: shared user32 .data means the 2nd GUI pseudo-process can resolve a NULL winproc (crash: blr NULL in call_window_proc). Log func + resolved procW for the first few calls per process."),
        "env.MADEIRA_DESKTOP_FIT": Info(title: "", defaultValue: "", note: "DESKTOP FIT. A presenting window whose client area does not fit the wine desktop (a 1920x1080 window on a 1280x720 desktop) was cropped: only its top-left showed, under a title bar, which looked like a frozen, non-fullscreen game. Its Me..."),
        "env.MADEIRA_DETACHED": Info(title: "", defaultValue: "", note: "≤30min at 2s — covers the 20-min cap"),
        "env.MADEIRA_DEVICE_STATS": Info(title: "", defaultValue: "0", note: "Opt-in (env.MADEIRA_DEVICE_STATS = 1): a line every 10 s during every session is a diagnostic, so it is off by default."),
        "env.MADEIRA_DIAG": Info(title: "", defaultValue: "", note: "MADEIRA_DIAG=1 lifts the cap; read once. Local to this file so the media unix side links against nothing but upstream's libntdll_unix.a."),
        "env.MADEIRA_DINPUT_PAD": Info(title: "DirectInput joystick from the host gamepad", defaultValue: "", note: "Default OFF: see \"OPT-IN\" at the top of this file. MADEIRA_DINPUT_PAD=1 turns the DirectInput view on for DirectInput-only games."),
        "env.MADEIRA_DINPUT_TRACE": Info(title: "", defaultValue: "", note: "Opt-in (MADEIRA_DINPUT_TRACE=1) and limited by a PROCESS-wide call counter: the per-device millisecond limiter never engaged for a title that re-creates its device constantly, and 260,000 trace lines in one session cost more than the inp..."),
        "env.MADEIRA_DIRCACHE": Info(title: "Remember directory listings for file lookups", defaultValue: "1", note: "Kill switch, default 1: a file name that does not match in its exact case is looked up in an in-memory copy of its directory instead of a volume query and a directory read each time (twice when the name is absent). Source-engine games such…"),
        "env.MADEIRA_DIRCACHE_TTL_MS": Info(title: "Directory listing trust window (ms)", defaultValue: "1000", note: "How long a remembered listing is used without checking the directory, while no file was created, renamed, linked or deleted through Wine. After that one stat of the directory decides whether it is read again. 0 checks it on every lookup. R…"),
        "env.MADEIRA_DIRECT_CURSOR": Info(title: "", defaultValue: "1", note: "MADEIRA_DIRECT_CURSOR=0: no cursor is drawn on the game view, motion stays relative there and the pointer never locks by itself; the driver reports nothing."),
        "env.MADEIRA_DIRECT_WINDOW_SIZE": Info(title: "", defaultValue: "", note: "MADEIRA_DIRECT_WINDOW_SIZE=1: keep an opted-in presenting window's client at the selected resolution, including an engine resize after startup. Default off; desktop sessions and ordinary windowed games are unchanged."),
        "env.MADEIRA_DIR_BY_PATH": Info(title: "", defaultValue: "", note: "entries skipped because their stat failed"),
        "env.MADEIRA_DISPLAY_SYNC": Info(title: "Metal layer: keep display sync", defaultValue: "0", note: "A/B: 1 leaves the game's Metal layer in CoreAnimation's display-sync scheduling. Off (the default) sets the private displaySyncEnabled=false (the MeloNX pattern, 2026-07-03). For a title parked 18-72 ms a frame in nextDrawable with the dis…"),
        "env.MADEIRA_DNSAPI_UNIXLIB": Info(title: "", defaultValue: "", note: "dnsapi's unix side is bound unless MADEIRA_DNSAPI_UNIXLIB=0, which keeps the stub table (every dnsapi unix call STATUS_NOT_SUPPORTED) as before."),
        "env.MADEIRA_DNS_TIMEOUT_MS": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_DOCK": Info(title: "", defaultValue: "1", note: "`env.MADEIRA_DOCK = 0` hides Dock. Without a built dockhost.exe it is hidden too."),
        "env.MADEIRA_DOCK_AUTO_REVEAL": Info(title: "", defaultValue: "1", note: "0: a window that may need the user never reveals the desktop by itself (Show desktop still does)"),
        "env.MADEIRA_DOCK_CEG": Info(title: "", defaultValue: "1", note: "The install record lists per-user executables: Dock asks Valve's client to prepare them before it launches. env.MADEIRA_DOCK_CEG = 0 never asks."),
        "env.MADEIRA_DOCK_CLEAR_STEAM_ID": Info(title: "", defaultValue: "1", note: "A Dock session publishes no fixed Steam game identity to its guests (WineProcessBridge.m): Valve's client runs in the host and gives each game its own. Every other launch clears the flag and is unchanged. env.MADEIRA_DOCK_CLEAR_STEAM_ID ..."),
        "env.MADEIRA_DOCK_COMPACT_POOL": Info(title: "", defaultValue: "0", note: "Opt-in per launch: a 512 MB JIT pool instead of the standard one."),
        "env.MADEIRA_DOCK_GAME_SCM": Info(title: "", defaultValue: "", note: "1: Wine's service manager in every Dock game session, 0: never; unset: only when the prefix registers an automatic-start service outside Windows"),
        "env.MADEIRA_DOCK_GAME_SCM_FASTSYNC": Info(title: "", defaultValue: "1", note: "0: such a session runs Wine's standard sync, as before 2026-10-28"),
        "env.MADEIRA_DOCK_GAME_SCM_SERVER_SYNC": Info(title: "", defaultValue: "1", note: "0: a session that starts the service manager keeps madsync"),
        "env.MADEIRA_DOCK_HIDE_DESKTOP": Info(title: "", defaultValue: "1", note: "0: a Dock start's starting screen ends on the desktop's first frame, as before"),
        "env.MADEIRA_DOCK_IMAGE_MAP_GUARD": Info(title: "", defaultValue: "1", note: "While the loader loads Valve's client and its many imports, the emulator's image-map handler can commit a page of its own heap under its interval lock; the commit's notification then waits for that same lock and the host parks for good (..."),
        "env.MADEIRA_DOCK_IMAGE_RETIRE": Info(title: "", defaultValue: "1", note: "Valve's client unloads DLLs while it starts and the loader can map a different DLL of the same size at the same address. The engine's opt-in image-retire switch (MADEIRA_JIT_IMAGE_RETIRE, off for every other session) gives that DLL fresh..."),
        "env.MADEIRA_DOCK_INSTALLERS": Info(title: "", defaultValue: "1", note: "0: Dock starts run no install-script programs"),
        "env.MADEIRA_DOCK_INSTALLER_REVEAL": Info(title: "", defaultValue: "1", note: "0: a one-time installer's dialog never reveals the desktop by itself"),
        "env.MADEIRA_DOCK_INSTALL_CHOICE": Info(title: "", defaultValue: "1", note: "0: no per-game choice, every start runs what is pending"),
        "env.MADEIRA_DOCK_INSTALL_LAYOUT": Info(title: "", defaultValue: "1", note: "0: a session of one-time installs keeps the game's layout lines"),
        "env.MADEIRA_DOCK_INSTALL_REGISTRY": Info(title: "", defaultValue: "1", note: "0: the install scripts' Registry values are not written"),
        "env.MADEIRA_DOCK_INSTALL_SCM": Info(title: "", defaultValue: "1", note: "Installers expect a service manager, and a Dock session starts none before the host. With madsync, Wine's services.exe never answered its RPC clients in the fork's device runs, so the service step and then every installer waited; msiexec..."),
        "env.MADEIRA_DOCK_INSTALL_SEPARATE": Info(title: "", defaultValue: "1", note: "0: the host follows the installers in the same session"),
        "env.MADEIRA_DOCK_INSTALL_SERVER_SYNC": Info(title: "", defaultValue: "1", note: "Installers expect a service manager, and a Dock session starts none before the host. With madsync, Wine's services.exe never answered its RPC clients in the fork's device runs, so the service step and then every installer waited; msiexec..."),
        "env.MADEIRA_DOCK_OFFLINE_LOGON": Info(title: "", defaultValue: "1", note: "out a connection that cannot happen; - a note of the last online start in which Valve's client confirmed a licence and said the account can log on offline (the host's `session-offline-ready=1`), for the Game details mark. Steam's offline..."),
        "env.MADEIRA_DOCK_RESET_CLEAN": Info(title: "", defaultValue: "1", note: "0: Reset only forgets the records; installed files stay"),
        "env.MADEIRA_DOCK_SESSION": Info(title: "", defaultValue: "", note: "\"EnterEC wrote it\" does NOT name the origin — Core.cpp says so explicitly: EnterEC storing an x64 target in State.rip is its job. The upstream producer still needs finding via x9 at DispatchJump/RetToEntryThunk/ExitToX64. A game in a Mad..."),
        "env.MADEIRA_DOCK_STATUS": Info(title: "", defaultValue: "1", note: "0: the starting screen does not watch the host's result"),
        "env.MADEIRA_DOCK_STEAM_RUN": Info(title: "", defaultValue: "1", note: "On by default: when a game in a Madeira Dock session asks Steam to start another game (steam.exe with steam://run/<App ID>, as Black Ops II's campaign does for Zombies), steam.exe is not started and Madeira starts that game when it is next…"),
        "env.MADEIRA_DOCK_VULKAN_STANDIN": Info(title: "", defaultValue: "1", note: "0: a Vulkan loader an installer wrote stays in system32"),
        "env.MADEIRA_DOCK_X64_TITLE": Info(title: "", defaultValue: "1", note: "0: a 32-bit helper in the game's folder keeps the 64-bit title's memory on the swap file first"),
        "env.MADEIRA_DOCS_DIR": Info(title: "", defaultValue: "", note: "Which rule chose the directory, for logging: \"env\", \"container\", \"home\" or \"none\"."),
        "env.MADEIRA_DONOR_BROWSERS": Info(title: "Browsers take donor RAM", defaultValue: "0", note: "Off by default: memory of the Chromium browsers next to a game (Social Club's SocialClubHelper.exe, Steam's steamwebhelper.exe) is backed by the swap file, never by the donor pool. The pool is handed out by reserved size whether the pages…"),
        "env.MADEIRA_DONOR_CHURN": Info(title: "Short-lived memory takes donor RAM", defaultValue: "1", note: "On by default: memory a game frees and allocates again soon takes donor RAM while the pool has room, instead of counting against the app's memory limit. 0: it stays in the app's own memory as before. Read at session start."),
        "env.MADEIRA_DONOR_POOL_MARGIN_MB": Info(title: "Donor pool free-RAM margin (MB)", defaultValue: "", note: "the donor pool takes no more memory while the host's free RAM is below this many MB. Off (0) since iOS keeps free RAM low on purpose, so 1024 and then 256 refused most takes on device; the memory-pressure notification alone guards. Set 256…"),
        "env.MADEIRA_DONOR_WHOLE_MAX_MB": Info(title: "Largest reservation given donor RAM (MB)", defaultValue: "0", note: "0 (default): no limit. N: a reservation larger than N MB is backed by the swap file only, never by the donor pool (a test; a game's own big heap is usually hot and runs faster in donor RAM). Read at session start."),
        "env.MADEIRA_DONOR_WINDOWS": Info(title: "Donor pool: permanent region windows", defaultValue: "0", note: "1 maps every donated region into the address space when it is registered, as the first port did. Off (the default) maps only the range being freed, for its zeroing: the permanent windows were placed before Wine held the 32-bit guest-window…"),
        "env.MADEIRA_DOTNET_FUSION": Info(title: "", defaultValue: "1", note: ""),
        "env.MADEIRA_DOWNLOAD_NOTIFICATIONS": Info(title: "", defaultValue: "1", note: "Local notifications when a Steam download finishes, fails or pauses while Madeira is in the background (permission asked at the first download). 0: none, and no permission request."),
        "env.MADEIRA_DUMP_SURFACES": Info(title: "", defaultValue: "", note: "would be frame-to-frame change rather than corruption. That would have looked exactly like a finding. * So: a src dump arms `wph_pair`, and the very next present of any window dumps its surface under the SAME pair number. That is the tig..."),
        "env.MADEIRA_DXGI_BUDGET_EVENTS": Info(title: "Tell the game when its video memory budget changes", defaultValue: "0", note: "Read by DXMT's dxgi with the budget-event change. The video memory budget DXGI reports shrinks as Madeira nears its memory limit (vram-trim-mb below it). 1: a game's budget-change event is registered for real, signalled at once and again w…"),
        "env.MADEIRA_DXGI_VK_SWAPCHAIN": Info(title: "DXGI swapchains for vkd3d-proton", defaultValue: "1", note: "On (default): DXMT's DXGI presents for a Direct3D 12 device on Vulkan (d3d12 = vkd3d) by wrapping vkd3d-proton's swapchain (IDXGIVkSwapChainFactory); windowed only, a fullscreen request keeps the window. 0: CreateSwapChain fails with \"Unsu…"),
        "env.MADEIRA_DXMT_EXTRA": Info(title: "", defaultValue: "", note: "madeira-bcd: the game's options from BCDLaunch.applyExtras (LibraryPrefs' NVIDIA device id), last, as before the merge. An option whose key is already set above is replaced, not repeated: DXMT reads at most 259 characters."),
        "env.MADEIRA_DXMT_SCHED_FIFO": Info(title: "", defaultValue: "", note: "no thread handles exist here; refuse rather than lie"),
        "env.MADEIRA_EA": Info(title: "", defaultValue: "1", note: "Off with `env.MADEIRA_EA = 0`."),
        "env.MADEIRA_EA_CEF": Info(title: "A store launcher's Chromium in one process", defaultValue: "0", note: "Default off; set with env.MADEIRA_SC_PA_POOLS = 2 for the EA app's launcher. EADesktop.exe runs --single-process with V8 --jitless (MADEIRA_JITLESS = 0 keeps V8's JIT), its --type= children are refused, and its four PartitionAlloc pools ge…"),
        "env.MADEIRA_EA_CEF_CMDLINE": Info(title: "Rewrite EADesktop.exe's command line", defaultValue: "1", note: "Default on. 0: while env.MADEIRA_EA_CEF is on, EADesktop.exe's command line is not rewritten; its --type= children are still refused. For testing a switch the launcher may not know."),
        "env.MADEIRA_EA_CEF_FLAGS": Info(title: "Extra EADesktop.exe switches", defaultValue: "", note: "Appended verbatim to EADesktop.exe's command line while env.MADEIRA_EA_CEF is on (e.g. --disable-gpu)."),
        "env.MADEIRA_ECO_NATIVE": Info(title: "Runtime helper threads on efficiency cores", defaultValue: "0", note: "1: the JIT-pool warmer (page warming and the periodic memory walks) and the stale-pointer healer run at utility QoS, on the efficiency cores, ECO on or off; neither does work a frame waits for. The wineserver thread, the exception thread,…"),
        "env.MADEIRA_ECO_PRIO": Info(title: "", defaultValue: "", note: "1: under eco, a thread that raises itself to TIME_CRITICAL keeps user-interactive QoS; 2: HIGHEST and above; unset/0: off"),
        "env.MADEIRA_EC_CONHOST": Info(title: "", defaultValue: "", note: "conhost.exe is refused in an ARM64EC session, where it would crash the app (see ec_conhost_refuse); MADEIRA_EC_CONHOST=1 starts it anyway."),
        "env.MADEIRA_EC_HOOK_TRACE": Info(title: "Log code patches the emulated copy misses", defaultValue: "0", note: "Default off, logging only. 1 compares executable PE sections and their pool copies before sync, including x64 entry thunks. Separate budgets preserve later graphics-jump records after native startup rewrites. A difference alone does not pr…"),
        "env.MADEIRA_EC_NATIVE_CHILD": Info(title: "Start aarch64 programs in a 64-bit x86 session", defaultValue: "0", note: "off (default): an aarch64 program (services.exe, cmd.exe, conhost.exe) started in a session whose first program is 64-bit x86 (ARM64EC) is refused and CreateProcess fails at once. The session's ntdll loads the emulator into it and its thre…"),
        "env.MADEIRA_ENV_LOCKED": Info(title: "", defaultValue: "", note: "madeira-env-locked: MADEIRA_ENV_LOCKED is a comma-separated list of names the host set on purpose. Without it a madeira.cfg line -- or a library game's own config -- could replace the program the front end was asked to launch, and the us..."),
        "env.MADEIRA_EPIC": Info(title: "", defaultValue: "1", note: "Off with `env.MADEIRA_EPIC = 0`."),
        "env.MADEIRA_EPIC_CLOUD": Info(title: "", defaultValue: "1", note: "Settings › Epic Games: whether saves sync, and whether this device's newer saves are sent without being asked. `env.MADEIRA_EPIC_CLOUD = 0` turns the sync off; downloads and the comparison are on by default, uploading is not (`env.MADEIR..."),
        "env.MADEIRA_EPIC_CLOUD_AUTO_UPLOAD": Info(title: "", defaultValue: "0", note: ""),
        "env.MADEIRA_EPIC_LAUNCHER_PARENT": Info(title: "Start Epic games under the Epic client's name", defaultValue: "1", note: "on (default): an Epic library game's x64 program starts as the child of C:\\windows\\system32\\EpicGamesLauncher.exe (build/epic-parent: starts its command line, waits, returns its exit code; not the Epic client, no window, no network), as it…"),
        "env.MADEIRA_EXCL_LOGICAL": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_EXE": Info(title: "Program to start at launch (Windows path or name)", defaultValue: "", note: "Pick which exe to run (env var override, default = cube.exe). Set MADEIRA_EXE=hello-x64.exe in env to launch the ARM64EC test path."),
        "env.MADEIRA_EXECREQ_LEAVE": Info(title: "", defaultValue: "", note: "Default off. 1 makes NtProtectVirtualMemory's [exec-req] path clear InSyscallCallback again, so the emulator hears about the memory changes that follow an executable protect on the same thread (GTA V Enhanced, the NoExec crash)."),
        "env.MADEIRA_EXE_WINDOW_HANDOFF": Info(title: "", defaultValue: "", note: "0 restores the old fixed-base handoff: claims are matched without rounding the image size to host pages, and a new main image never waits for the previous owner of the executable window to exit."),
        "env.MADEIRA_EXE_WINDOW_SMALL_FIXED": Info(title: "", defaultValue: "", note: "0 keeps the executable window from a fixed-base (relocations stripped) image smaller than 64 MB, as before; such a program then fails to start."),
        "env.MADEIRA_EXE_WINDOW_WAIT_MS": Info(title: "", defaultValue: "", note: "how long a new main image with stripped relocations waits for the previous owner of the executable window to exit, in milliseconds; 0 does not wait"),
        "env.MADEIRA_EXIT_REPORT": Info(title: "", defaultValue: "1", note: "Why a session ended by itself (not Quit): the program the app launched exited with a Windows error (wine_crash_exit_status, WineProcessBridge.m). MADEIRA_EXIT_REPORT=0 returns to the library without a message."),
        "env.MADEIRA_EXTENDED_MODES": Info(title: "", defaultValue: "", note: "1: list modes up to 4x the session default's pixels"),
        "env.MADEIRA_EXT_PROBE": Info(title: "", defaultValue: "0", note: "MADEIRA_EXT_PROBE=1: at session start the JIT helper extension reports the address space and memory limit its own process gets ( feasibility probe for extension processes)"),
        "env.MADEIRA_FASTSYNC": Info(title: "Fastsync (in-process sync, default)", defaultValue: "", note: "Fastsync is the default engine: with neither this nor inproc-sync set, the app exports auto. Settings > Sync engine > Fastsync removes both keys. Never runs while madsync is on. auto arms the fast wake path on heavy event traffic, 1 from t…"),
        "env.MADEIRA_FASTSYNC_CAP_US": Info(title: "", defaultValue: "", note: "longest fast park before server_wait, 50..50000 us (2000)"),
        "env.MADEIRA_FASTSYNC_SEM": Info(title: "", defaultValue: "", note: "1: semaphores use cells too (off by default)"),
        "env.MADEIRA_FASTSYNC_SPIN_US": Info(title: "", defaultValue: "", note: "adaptive spin ceiling, 0..1000 us (40); 0 = none"),
        "env.MADEIRA_FAST_SERVER_START": Info(title: "", defaultValue: "1", note: "Wine starts as soon as the wineserver has finished starting up (its registry is loaded), normally within tens of milliseconds, instead of after a fixed 2 s pause. 0 restores the fixed pause."),
        "env.MADEIRA_FAULT_ESR_DIR": Info(title: "", defaultValue: "", note: "The data abort's ESR says whether the access wrote (WnR, bit 6). The encoding guess below calls the LSE atomics (LDADD, SWP, CAS...: an x86 lock xadd / xchg) reads, because they have bit 22 set, so a write was reported to the guest as a ..."),
        "env.MADEIRA_FAULT_GUARD_GUEST_RIP": Info(title: "Fault guards tell FEX's invalid instructions apart", defaultValue: "0", note: "Default off. 1: the fault-storm guards also key an invalid-instruction delivery on the guest instruction FEX saved, so a program that steps over a long run of them in its own handler is not ended while it advances, and the 50-fault page br…"),
        "env.MADEIRA_FAULT_GUARD_RATE": Info(title: "Fault-storm guards end only a real storm", defaultValue: "0", note: "Default off. 1: a run of 2000 faults at one instruction ends the game only when it is dense (inside half a second) or presenting makes no progress, and the 5-repeat guard counts per thread within 5 ms; for a Unity title that throws managed…"),
        "env.MADEIRA_FAULT_LOOP_GUEST_PROGRESS": Info(title: "A run of breakpoints at different addresses is not a stuck thread", defaultValue: "0", note: "Default off. 1: the loop breaker (50 faults at one place end the thread) no longer counts int3 traps at different guest addresses as one stuck fault, though the emulator raises all of them from one host instruction. Logged as [fault-progre…"),
        "env.MADEIRA_FAULT_OPERANDS": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_FEX_ARENA": Info(title: "", defaultValue: "", note: "Wine reserves a band; the emulator still runs its own selector and picks a different one. Holding 8GB therefore pushes it into whatever is left, and when that band is exhausted its 16MB requests fail, a thread-creation path dereferences ..."),
        "env.MADEIRA_FEX_ARENA_GROW": Info(title: "", defaultValue: "", note: "1: a full FEX arena adds a FEX_ONLY band below it (default off: on the Social Club layout a band lies in address space the browser helper's allocators were granted, and their writes corrupted it); default: the request fails as before"),
        "env.MADEIRA_FEX_AVX": Info(title: "", defaultValue: "", note: "iOS-Madeira: MADEIRA_FEX_AVX=2, AVX without AVX2 (see HideAVX2 in CPUID.h). Exactly \"2\"; \"1\" and unset are unchanged."),
        "env.MADEIRA_FEX_BAND_KEEP_MB": Info(title: "Keep the lowest MB of the emulator's address range for the emulator", defaultValue: "0", note: "Default 0 (off). N MB: reservations of 32 MB to 1 GB that are placed above the game's own range because that range is tight may not take the lowest N MB of the emulator's 16 GB range; what no longer fits goes below it. For a game that rese…"),
        "env.MADEIRA_FEX_BRANCH_HISTORY": Info(title: "", defaultValue: "", note: "Recorder emitted only for this executable, before CTX/JIT creation."),
        "env.MADEIRA_FEX_CALLRET_ELIDE": Info(title: "64-bit JIT without the call-return shadow stack", defaultValue: "1", note: "Default on. The 64-bit (ARM64EC) JIT no longer keeps FEX's call-return shadow stack, which nothing reads on iOS: 9 instructions less per guest CALL and per RET, and linked calls become `bl`, so the CPU's return predictor follows guest call…"),
        "env.MADEIRA_FEX_EC_BITMAP_CACHE": Info(title: "Native-code check with the thread's bitmap pointer", defaultValue: "1", note: "Default on. The 64-bit JIT's dispatcher tests the native-code bitmap through a pointer kept in the thread's state instead of walking TPIDRRO_EL0, the TEB and the PEB: 4 instructions less on every call into a system DLL through its import t…"),
        "env.MADEIRA_FEX_EC_EXIT_LEAN": Info(title: "Lean exit from the JIT into native code", defaultValue: "1", note: "Default on while AFP is off (the default). Calls from the 64-bit JIT into native (ARM64EC) code use a shorter stub: no FPCR read, the CPU area and suspend doorbell from the thread's state, the call counted per thread instead of with an ato…"),
        "env.MADEIRA_FEX_EC_RET": Info(title: "Returns from native code through the return predictor", defaultValue: "1", note: "Default on. A guest call into native (ARM64EC) code leaves the JIT with BLR and its return comes back with RET after an L1 lookup (10 instructions instead of 22), so the CPU's return-address predictor stays in step with the guest's calls.…"),
        "env.MADEIRA_FEX_EC_RET_DIRECT": Info(title: "Returns from native code straight into the JIT", defaultValue: "1", note: "Default on. When a native (ARM64EC) function returns to the game's x64 code, the return enters the 64-bit JIT at once instead of testing the native-code bitmap first; the JIT's dispatcher already tests every address it has no translation f…"),
        "env.MADEIRA_FEX_FAIL_CALLRET": Info(title: "", defaultValue: "", note: "MADEIRA_FEX_FAIL_CALLRET=threadstate:N fails the Nth thread-state allocation, so this containment path can be proven rather than assumed -- it only occurs naturally once the band is exhausted."),
        "env.MADEIRA_FEX_HEADROOM_LOG": Info(title: "", defaultValue: "", note: "0: no [fex-headroom] lines"),
        "env.MADEIRA_FEX_PRELOADED_IMAGES": Info(title: "FEX: record images loaded before it starts", defaultValue: "1", note: "on (default): when FEX starts in a 64-bit process it records the code sections of every image already loaded (kernel32, kernelbase, ucrtbase are mapped for it before its notifications work). Before, their x64 export thunks were not known a…"),
        "env.MADEIRA_FEX_SMC_FASTPATH": Info(title: "", defaultValue: "", note: "madeira-bcd: smc-store-fastpath v1. MADEIRA_FEX_SMC_FASTPATH=0 restores the locked path."),
        "env.MADEIRA_FILE_INFO_FULL": Info(title: "File size queries read attributes too", defaultValue: "0", note: "Kill switch, default 0: a file's size, index or end-of-file query (GetFileSizeEx and the like) is answered from one fstat; the two extended-attribute reads that came after it fed only file attributes, which these queries do not return. 1:…"),
        "env.MADEIRA_FILE_TRACE": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_FILE_TRACE_LIMIT": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_FIXED_BASE_GUARD": Info(title: "Keep 0x140000000 for a fixed-base game", defaultValue: "0", note: "Default off. 1: a resource-only image view (a version or resource query, e.g. the Rockstar Games Launcher reading Social-Club-Setup.exe) never takes the reserved executable window at 0x140000000; it is mapped elsewhere. The window then sta…"),
        "env.MADEIRA_FONT_KEYS_REPAIR": Info(title: "Repair the registry's font list", defaultValue: "1", note: "On (default): a session that found no fonts leaves the registry's Fonts key alone, stale external entries that name a font of C:\\windows\\Fonts are dropped, and the Windows directory's fonts get their Fonts values back (DirectWrite lists on…"),
        "env.MADEIRA_FORCE_CONSOLE": Info(title: "", defaultValue: "", note: "iOS denies pty allocation, so isatty() above can never be true and every console-only session lands on CONSOLE_HANDLE_SHELL_NO_WINDOW -- the one value init_console excludes from every console-creating branch (kernelbase/console.c:2400). ..."),
        "env.MADEIRA_FOREGROUND_FIX": Info(title: "", defaultValue: "", note: "0: never make the game's main window foreground"),
        "env.MADEIRA_FPS_CAP": Info(title: "Fixed frame cap (fps)", defaultValue: "", note: "Unset (default): no cap beyond the FPS limit. 10-120: frames start at most N times a second for the whole session: a Direct3D 12 game's thread waits after each Present, a DXMT game's encode thread before each present (a timed kernel wait,…"),
        "env.MADEIRA_FPS_COUNT_HIDDEN": Info(title: "", defaultValue: "", note: "1: the FPS readouts count hidden windows' presents too (as before 2026-10-26)"),
        "env.MADEIRA_FPS_GOV_BAND_MJ": Info(title: "Frame-cap governor: energy band (mJ)", defaultValue: "1500", note: "Only with env.MADEIRA_FPS_GOV_MW set: how much energy the running balance may drift above or below the target before the cap moves one step (100-100000; unset or out of range: 1500). Smaller moves the cap sooner and more often. Read at ses…"),
        "env.MADEIRA_FPS_GOV_MAX": Info(title: "Frame-cap governor: highest cap (fps)", defaultValue: "60", note: "Only with env.MADEIRA_FPS_GOV_MW set: the highest frame cap the governor uses, the largest of 60, 40, 30, 24 and 20 at or below this value (20 when lower). Unset: 60. Read at session start."),
        "env.MADEIRA_FPS_GOV_MIN": Info(title: "Frame-cap governor: lowest cap (fps)", defaultValue: "20", note: "Only with env.MADEIRA_FPS_GOV_MW set: the lowest frame cap the governor goes down to, the smallest of 60, 40, 30, 24 and 20 at or above this value, never above the highest cap. Unset: 20. Read at session start."),
        "env.MADEIRA_FPS_GOV_MW": Info(title: "Hold CPU power with a frame cap (mW)", defaultValue: "", note: "Unset (default): off. N: while the game presents, the process's CPU power ([xp]'s energy) is held at N mW on average by moving a frame cap between 60, 40, 30, 24 and 20 fps (at most one step per 3 s; held while nothing presents). Unlike en…"),
        "env.MADEIRA_FRAMEGEN": Info(title: "", defaultValue: "", note: "3. runs MetalFX's frame interpolator (MTLFXFrameInterpolator, iOS 26) on the two frames, that motion field and a flat depth, 4. presents the generated frame at once and the real one half a frame later (presentDrawable:atTime:). The panel..."),
        "env.MADEIRA_FRAMEGEN_ONE_LAYER": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_FRAME_STATS": Info(title: "", defaultValue: "", note: "[frame] once a second: unset/0 off (default), anything else on"),
        "env.MADEIRA_FRAME_TIMES": Info(title: "", defaultValue: "", note: "0: no frame-time marks; the overlay's graph and 1% cells stay empty"),
        "env.MADEIRA_FREE_DELAY_MS": Info(title: "", defaultValue: "", note: "How long a released 1-16 MB guest allocation stays mapped before it is really freed (default 0: freed at once; 2000 ms is the tested hold)."),
        "env.MADEIRA_FREE_DELAY_REUSE": Info(title: "", defaultValue: "", note: "MADEIRA_FREE_DELAY_REUSE=0: a reservation over held releases fails until the delay runs out, as before; default 1: those held ranges are freed at once"),
        "env.MADEIRA_FRONTEND": Info(title: "", defaultValue: "", note: "Which interface Madeira starts with: the library (the default) or the developer interface. The choice is made in either interface, stored in UserDefaults and read once per run, so a change applies at the next start. Without a stored choi..."),
        "env.MADEIRA_FRONTEND_CONTROLLER": Info(title: "", defaultValue: "1", note: ""),
        "env.MADEIRA_FRONTEND_DEFAULT_NEW": Info(title: "", defaultValue: "1", note: "Which interface Madeira starts with: the library (the default) or the developer interface. The choice is made in either interface, stored in UserDefaults and read once per run, so a change applies at the next start. Without a stored choi..."),
        "env.MADEIRA_FRONTEND_KEYBOARD": Info(title: "", defaultValue: "1", note: "MADEIRA_FRONTEND_KEYBOARD=0: the game view's own keyboard instead."),
        "env.MADEIRA_FS_AUTO_REQS": Info(title: "", defaultValue: "", note: "auto: operations in 10 s that arm the wake path (20000, min 1000)"),
        "env.MADEIRA_FS_POLLPEEK": Info(title: "", defaultValue: "", note: "0: no local answer to zero-timeout polls"),
        "env.MADEIRA_FULLSCREEN_FOREGROUND": Info(title: "", defaultValue: "", note: "0: a full-screen window shown with activation is left to the foreground lock"),
        "env.MADEIRA_GAME_DIALOG_CURSOR": Info(title: "Cursor over a game's launcher or message box", defaultValue: "1", note: "Default on. A game session draws no cursor: the finger is the pointer. While the game shows a launcher or message box, the arrow is drawn where the finger last touched (where the click lands) and goes away with the box. Tap the button itse…"),
        "env.MADEIRA_GAME_INPUT_WAKE": Info(title: "", defaultValue: "", note: "Default on: a launcher / message box over a game takes taps and keys; 0 = off."),
        "env.MADEIRA_GAME_WINDOWS": Info(title: "", defaultValue: "", note: "Game-mode windows. Outside desktop mode a window got win32u's offscreen surface and its position never reached the app, so a launcher or a message box a game opens before (or instead of) its 3D window was drawn nowhere: a game's Play / O..."),
        "env.MADEIRA_GDI_SECTION_ALWAYS": Info(title: "", defaultValue: "", note: "upstream's anonymous allocation -- and any 32-bit program started LATER in such a session (a 64-bit launcher's 32-bit child, or the app's in-session launcher starting the 32-bit Steam client into an explorer desktop) kept the host table ..."),
        "env.MADEIRA_GDI_SHARED_SECTION": Info(title: "", defaultValue: "", note: "was armed for 32-bit code when win32u initialised, so a 64-bit session kept upstream's anonymous allocation -- and any 32-bit program started LATER in such a session (a 64-bit launcher's 32-bit child, or the app's in-session launcher sta..."),
        "env.MADEIRA_GESTURE_ZONES": Info(title: "", defaultValue: "1", note: "A swipe zone turns a swipe into a short press of one input per direction (D-pad by default), optionally limited to horizontal or vertical swipes, and a tap into another. - A look zone moves the mouse by the finger's motion, like a trackp..."),
        "env.MADEIRA_GL_BACKEND": Info(title: "", defaultValue: "", note: "With the GLES backend there is no desktop GL context, so make LOVE ask for OpenGL ES first. LOVE 11 checks this SDL hint (read from the environment) before trying desktop GL; SDL then creates the context through WGL_EXT_create_context_es..."),
        "env.MADEIRA_GL_COMPILE_TIMEOUT": Info(title: "", defaultValue: "", note: "seconds a Metal shader compile may take under Zink (default 20); then the shader fails and its draws are skipped. 0: no limit"),
        "env.MADEIRA_GL_DIR": Info(title: "", defaultValue: "", note: "Load OSMesa and prove Zink actually runs: a throwaway core-profile context must report the Zink renderer. Mesa quietly falls back to softpipe when Zink cannot start (no MoltenVK, missing Vulkan features), and a software rasterizer is not..."),
        "env.MADEIRA_GL_EXTENSIONS_MAX": Info(title: "", defaultValue: "", note: "byte limit of GL_EXTENSIONS in 32-bit OpenGL contexts (opengl32, patches/wine-opengl-winios.patch): unset = 3072, 0 = none; d3d9 = wined3d makes it 0 unless set"),
        "env.MADEIRA_GL_FPS_CAP": Info(title: "", defaultValue: "", note: "0: OpenGL games ignore the session's FPS limit, as before"),
        "env.MADEIRA_GL_PERF": Info(title: "", defaultValue: "", note: "0: no GL perf line (presents/s, flush-ms ...) and no stall reports"),
        "env.MADEIRA_GL_QUERY_BUFFER_OFFSETS": Info(title: "32-bit GL query results as buffer offsets", defaultValue: "1", note: "On (default): a 32-bit program's glGetQueryObject*v result pointer is an offset into the bound GL_QUERY_BUFFER (wined3d reads occlusion results that way; converting it as a pointer left the game spinning at 1 fps, ). 0: the old pointer con…"),
        "env.MADEIRA_GL_SHADER_CACHE": Info(title: "", defaultValue: "", note: "0: no Mesa shader disk cache for desktop OpenGL (Zink); every run converts and compiles all shaders again"),
        "env.MADEIRA_GL_VULKAN": Info(title: "", defaultValue: "", note: "Vulkan driver for Zink when madeira.cfg gl-vulkan is unset: moltenvk (default), kosmickrisp, or a .dylib name/path"),
        "env.MADEIRA_GOG": Info(title: "", defaultValue: "1", note: "Off with `env.MADEIRA_GOG = 0`."),
        "env.MADEIRA_GOG_GALAXY": Info(title: "", defaultValue: "1", note: "GOG Galaxy's game services (sign-in, achievements, stats, leaderboards) for GOG games, answered by Madeira on 127.0.0.1:9977 while one runs (docs/GOG.md, \"Galaxy\"); 0 turns them off, in madeira.cfg or in one game's own config"),
        "env.MADEIRA_GPU_DEVICE": Info(title: "Windows' display adapter: PCI device id (hex)", defaultValue: "", note: "With MADEIRA_GPU_VENDOR: the adapter's device id. Per game: Game details > Graphics card the game sees."),
        "env.MADEIRA_GPU_NAME": Info(title: "Windows' display adapter: name", defaultValue: "", note: "The adapter name Windows reports with MADEIRA_GPU_VENDOR and MADEIRA_GPU_DEVICE; unset, the name of the PCI id. Per game: Game details > Graphics card the game sees."),
        "env.MADEIRA_GPU_VENDOR": Info(title: "Windows' display adapter: PCI vendor id (hex)", defaultValue: "", note: "With MADEIRA_GPU_DEVICE: the display adapter win32u registers (EnumDisplayDevices, SetupAPI, the display driver key, D3DKMT), instead of Apple 106B:0001 or the RTX 3060 of Report an NVIDIA GPU. Per game: Game details > Graphics card the ga…"),
        "env.MADEIRA_GRAPHICS_SETTINGS": Info(title: "", defaultValue: "1", note: "0: no Settings › Graphics section; d3d9, d3d11, d3d12 and vulkan are back in All settings"),
        "env.MADEIRA_GUEST_CTX": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_GUEST_IMAGE_WRITE": Info(title: "", defaultValue: "", note: "memory is decided by its own rule (ios_guest_anon_rwx_is_host_data, below): a managed runtime's code buffers keep the pool alias and the store emulator, and those views are not SEC_IMAGE. The test is the view, not the address range. * vi..."),
        "env.MADEIRA_GUEST_LOG": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_GUEST_LOG_ERRORS": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_GUEST_LOG_LIMIT": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_GUEST_RWX_DATA": Info(title: "", defaultValue: "", note: "On by default: a guest's anonymous RWX data heap (Mono's Boehm GC) is plain read/write memory. 0 maps it through the JIT pool again, with every store emulated, as before."),
        "env.MADEIRA_HIDDEN_LAYER_FPS": Info(title: "", defaultValue: "", note: "frames a second a hidden desktop window's Metal layer may present (default 10); 0 = no limit"),
        "env.MADEIRA_HIDPAD": Info(title: "", defaultValue: "", note: "Set by the app at session start from env.MADEIRA_PAD_MODE (dualsense or generic) for the wineserver and ntdll; not meant to be set by hand."),
        "env.MADEIRA_HIDPAD_AUTO_GENERIC": Info(title: "HID mode: other pads as a generic HID gamepad", defaultValue: "0", note: "1: with env.MADEIRA_PAD_MODE = hid, a pad that is not a PlayStation one becomes a generic HID gamepad and leaves XInput (the old behaviour). Off: it stays on XInput."),
        "env.MADEIRA_HIDPAD_NAME": Info(title: "", defaultValue: "", note: "Set by the app: the product string a generic HID gamepad reports (the physical pad's name)."),
        "env.MADEIRA_HIDPAD_XINPUT": Info(title: "HID mode: keep player 1 on XInput too", defaultValue: "0", note: "1: with the HID controller on, player 1 also stays an XInput pad. Off by default, so a game that reads both APIs does not see the same pad twice."),
        "env.MADEIRA_HWINPUT": Info(title: "", defaultValue: "1", note: "MADEIRA_HWINPUT=0: no keyboard/mouse bridging, no pointer recognisers, no touch filter, no drawn cursor; the app behaves as it did before this file existed."),
        "env.MADEIRA_HW_REGISTRY": Info(title: "", defaultValue: "", note: "Default 1: wineboot's volatile HKLM\\HARDWARE\\DESCRIPTION\\System keys. 0: none (no session had them before). 2: also the Session Manager\\Environment values."),
        "env.MADEIRA_IAT_SYNC_KEEP": Info(title: "", defaultValue: "", note: "0 = the iat-sync translates unchanged file words too (old rule)"),
        "env.MADEIRA_IDX_REALIGN": Info(title: "", defaultValue: "", note: "madeira-bcd: realigned 16-bit indices -- reserve argument-buffer room for a 16-bit draw whose index offset is not 4-byte aligned; 0 = not needed."),
        "env.MADEIRA_ILONLY_WOW64": Info(title: "", defaultValue: "", note: "Kill switch, read once: 0 turns the check off."),
        "env.MADEIRA_IMAGE_PATCH_TRACE": Info(title: "DLL code patch trace", defaultValue: "0", note: "1 logs up to 64 successful 1–16 byte executable-image protection requests and their PE/pool bytes. Read-only, owner-aware diagnostics; does not alter hooks or code."),
        "env.MADEIRA_IMAGE_RELOAD": Info(title: "", defaultValue: "", note: "MADEIRA_IMAGE_RELOAD (default 1): 1 the same image reloaded at the same base by the same process gets its copy rebuilt in place (same pool address, fresh bytes, relocations and x18 patches redone); any other reuse of an unmapped copy get..."),
        "env.MADEIRA_INITIAL_CWD": Info(title: "", defaultValue: "", note: "iOS-Madeira override: MADEIRA_INITIAL_CWD env var lets the bridge specify the initial NT path directly (e.g. \"C:\\\\Program Files\\\\Thumper\\\\\") when iOS unix_to_nt_file_name can't resolve drive_c via dosdevices."),
        "env.MADEIRA_INPUT_FOCUS": Info(title: "", defaultValue: "1", note: "MADEIRA_INPUT_FOCUS=0: keyboard and mouse reach the program whatever has focus (the program still gets nothing while the app is inactive: held input is released then)."),
        "env.MADEIRA_INPUT_FOREGROUND": Info(title: "Bring the game to the front when no window is", defaultValue: "0", note: "Default off. iOS has no window manager: a game that shows its window without activating it and reads no XInput stays in the background, and Windows sends raw keyboard and mouse input only to the program in front (Horizon Zero Dawn ignored…"),
        "env.MADEIRA_INSTALL_DEFAULT_KEY": Info(title: "", defaultValue: "1", note: "The install scripts' programs of a game: its own folder (one level down) and the shared redistributables Steam keeps next to it, and how many scripts were read."),
        "env.MADEIRA_INSTALL_SKIP_DOTNET": Info(title: "", defaultValue: "1", note: "0: .NET Framework setups run too"),
        "env.MADEIRA_INVALIDATION_NESTED": Info(title: "", defaultValue: "", note: "MADEIRA: CodeInvalidationMutex is not recursive. When this thread already write-owns it, a second exclusive lock parks the thread behind itself, and every other thread queues behind it for good (log 56: one thread waiting on the lock it ..."),
        "env.MADEIRA_IOSB_DEAD_TARGET": Info(title: "", defaultValue: "", note: "IO_STATUS_BLOCK32 one guest window iOS maps nothing below 4 GB"),
        "env.MADEIRA_IO_STATUS_OWNER": Info(title: "", defaultValue: "", note: "leaves it pointing at the last WoW64 child, so neither value identifies the CALLER's I/O ABI (an I/O status block must be written in the layout of the process that owns it). The guest-window base of the calling pseudo-process does: nonze..."),
        "env.MADEIRA_IRCAP_MODULE": Info(title: "", defaultValue: "", note: "arm the targeted IR capture (PassManager.cpp) once the module that owns the instruction under investigation is mapped. Module + RVA come from the environment so chasing a different miscompile never needs a rebuild; the defaults ar..."),
        "env.MADEIRA_IRCAP_RVA": Info(title: "", defaultValue: "", note: "arm the targeted IR capture (PassManager.cpp) once the module that owns the instruction under investigation is mapped. Module + RVA come from the environment so chasing a different miscompile never needs a rebuild; the defaults ar..."),
        "env.MADEIRA_IR_NO_BOUNDS_CHECK": Info(title: "", defaultValue: "", note: "madeira-bcd: switches the converter service reads (madeira_ir_unix.mm, madeira_ags.cpp); set in madeira.cfg, as an env.NAME export there, or in the environment. \"msc\" = position invariance, strict NaN/Inf, sampler LOD bias (the MSC compa..."),
        "env.MADEIRA_IR_TOPO": Info(title: "", defaultValue: "", note: "iOS-Madeira name the pass that breaks the intrusive node list. DFE and RA both detect corruption at their own entry, but by then the damage is upstream and anonymous. This sweeps every block after every pass and reports the FIRST ..."),
        "env.MADEIRA_IR_TOPO_MIN": Info(title: "", defaultValue: "", note: "only sweep BIG functions. swept every block after every pass on every compile and that alone stalled the renderer -- it spent as much time in ValidateBlockTopology as in the whole x86 decoder, and Steam never reached the UI..."),
        "env.MADEIRA_ITCH": Info(title: "", defaultValue: "1", note: "Off with `env.MADEIRA_ITCH = 0`."),
        "env.MADEIRA_JAPANESE": Info(title: "Japanese locale and fonts", defaultValue: "0", note: "Default off. 1: the game runs with a Japanese system and user locale (LC_ALL = ja_JP.UTF-8, ANSI and OEM code page 932) and the extra code page tables (env.MADEIRA_NLS_EXTRA), and a Japanese font (Noto Sans JP) is installed in C:\\windows\\F…"),
        "env.MADEIRA_JITLESS": Info(title: "", defaultValue: "", note: "Interpreted V8 costs 5-20x on all of Steam's UI JavaScript, so this is the largest single startup lever we have. MADEIRA_JITLESS=0 turns it off; default stays ON (unchanged). (device logs 111-112, Big Picture): CEF's verbose file ..."),
        "env.MADEIRA_JIT_ATTACH_CHECK": Info(title: "", defaultValue: "1", note: "0 treats JIT as ready whenever CS_DEBUGGED is set, as before, without asking whether a debugger is attached."),
        "env.MADEIRA_JIT_DUMP": Info(title: "", defaultValue: "", note: "1: write Documents/fex-jit-dump.bin (the JIT pool, sparse) on the first mach UNHANDLED / SIGILL ; default 0."),
        "env.MADEIRA_JIT_ENV_INHERIT": Info(title: "", defaultValue: "", note: "0: a child's environment stays as its creator built it"),
        "env.MADEIRA_JIT_IMAGE_RETIRE": Info(title: "", defaultValue: "", note: "new module runs the old module's translated code. Tombstone every pool mapping that overlaps the unmapped range before the VA can be reused, so the next image mapped there gets a fresh copy. The pool bytes themselves stay in the process ..."),
        "env.MADEIRA_JIT_SHORTCUT": Info(title: "", defaultValue: "0", note: "Settings › JIT › Madeira JIT shortcut: when LocalDevVPN's loopback does not answer, Enable JIT runs the shortcut. Off unless it is 1."),
        "env.MADEIRA_JIT_SIGNING_CHECK": Info(title: "", defaultValue: "1", note: "Explains why JIT cannot be enabled on a copy signed without get-task-allow; 0 opens StikDebug regardless. A debugger can attach only to a process whose signature carries get-task-allow (a development signature). A copy signed with a dist..."),
        "env.MADEIRA_JIT_TRAP_FALLBACK": Info(title: "", defaultValue: "1", note: "With no debugger attached, a JIT request fails the launch with a message; 0 lets it crash the app as before. CS_DEBUGGED stays set after a debugger detaches (JIT enabled by a tool that attaches and leaves, or without Madeira's script), a..."),
        "env.MADEIRA_JUMBO_ALIGNED": Info(title: "", defaultValue: "", note: "0: a hinted reservation at a 4 GB boundary (V8's trusted range) takes a kernel pick as before, and furniture may fill the 4 GB-aligned gigabyte above a guest window (default 1: 4 GB-aligned bases are tried first and that gigabyte is left..."),
        "env.MADEIRA_JUMBO_HALF": Info(title: "Give a too-large probe reservation half its size", defaultValue: "0", note: "Default off. 1: a reserve-only request of 4 GB or more (a power of two) that finds no hole gets half its size at a half-aligned free slot below the emulator's arena, for a game that finds each aligned arena with a double-size probe and kee…"),
        "env.MADEIRA_KEYED_EVENT_PER_PROCESS": Info(title: "A default keyed event per process", defaultValue: "1", note: "On (default): each Windows process gets its own keyed event for the waits and wakes that pass no handle (RtlRunOnce among them), created on first use. 0: every process uses the one the first process created, as before, whose handle is not…"),
        "env.MADEIRA_KMT_ADAPTER": Info(title: "D3DKMT adapter for the GPU (WDDM 3.1)", defaultValue: "0", note: "1: D3DKMTEnumAdapters2 lists the GPU DXGI and D3D12 report (same LUID) and D3DKMTQueryAdapterInfo answers like a WDDM 3.1 driver (driver version, caps, device ids, memory, performance data). Off (default): no adapter is listed, as before.…"),
        "env.MADEIRA_KMT_TRACE": Info(title: "", defaultValue: "", note: "The [vkmt] entry-point trace; MADEIRA_KMT_TRACE=0 turns it off."),
        "env.MADEIRA_KUSD_AVX": Info(title: "", defaultValue: "", note: "with MADEIRA_FEX_AVX=1 FEX runs AVX/AVX2 and its CPUID says so, but Wine fills the XSAVE configuration only on x86 hosts, so GetEnabledXStateFeatures still said \"no AVX\" and runtimes that ask it (.NET's JIT) kept AVX off. Describ..."),
        "env.MADEIRA_LAA": Info(title: "", defaultValue: "", note: "WHAT STAYS LOW regardless (unchanged by this policy, and deliberately so): the first TEB block and the PEB32/TEB32 derived from it (virtual_alloc_teb and the first-block allocation both hardcode limit_2g - 1), the KUSER_SHARED_DATA emula..."),
        "env.MADEIRA_LAA_HIGH_IMAGES": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_LAA_LOWFIRST": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_LAUNCH_EARLY": Info(title: "", defaultValue: "1", note: "0: Play keeps the Game details page up until the session begins"),
        "env.MADEIRA_LAUNCH_FLOOD": Info(title: "", defaultValue: "1", note: "0: the starting screen fades in without growing out of the Play button"),
        "env.MADEIRA_LAUNCH_WIDE": Info(title: "", defaultValue: "1", note: "0: the starting screen is one centred column in landscape too"),
        "env.MADEIRA_LAZY_PLACEHOLDERS": Info(title: "", defaultValue: "", note: "MADEIRA_LAZY_PLACEHOLDERS=0 reserves 64 MB to 1 GB placeholders whole again"),
        "env.MADEIRA_LEAN_DIAG": Info(title: "Lean diagnostics (no thread-suspending samplers)", defaultValue: "0", note: "1: the samplers that suspend threads stop ([thread-sample] bursts every 20 s, the guest RIP profile behind [rip-profile] and [cpu-split], [wprof]); the warmer's address-space walks ([phys-map], slot and window inventory) run every ~10 min…"),
        "env.MADEIRA_LIBRARY_AMBIENT": Info(title: "", defaultValue: "1", note: "The library's ambient light: a glow behind every grid card that has reported its frame (only the cards the lazy grids have built). MADEIRA_LIBRARY_AMBIENT=0 turns it off."),
        "env.MADEIRA_LIBRARY_COLLAPSE": Info(title: "", defaultValue: "1", note: "MADEIRA_LIBRARY_COLLAPSE=0: the section titles do not collapse."),
        "env.MADEIRA_LIBRARY_HIDE_ENDED_DESKTOP": Info(title: "", defaultValue: "1", note: ""),
        "env.MADEIRA_LIBRARY_TABS": Info(title: "", defaultValue: "1", note: "The library's store tabs: with Group by Platform, a segmented control at the top of the page shows one store's section at a time (Steam, the games you added, GOG, itch.io, Epic Games, EA app) or All of them. Only the sections the page wo..."),
        "env.MADEIRA_LIQUID_METAL": Info(title: "", defaultValue: "0", note: "Whether the app's liquid metal is on: Settings › Appearance › Liquid metal, kept in madeira.cfg as env.MADEIRA_LIQUID_METAL (off, plain Liquid Glass, unless it is 1). It covers the Desktop button's fill (LiquidMetalFill) and the bars' gl..."),
        "env.MADEIRA_LOCAL_PROCESS_WRITE": Info(title: "", defaultValue: "", note: "Keep local writes disabled by default: enabling them globally regressed Steam. Explicitly opt in only for pseudo-processes in this Unix task. The request handler has already checked PROCESS_VM_WRITE rights."),
        "env.MADEIRA_LOCK_ORPHAN": Info(title: "Orphan-lock reaper mode", defaultValue: "", note: "Default and stamped: only a lock seen held by FEX can be released, after three monitor cycles with the same lock word and no live owner stamp. Guest locks are never released. 0: no orphan-lock releases. The dead-thread reaper is unchanged.…"),
        "env.MADEIRA_LOG_THROTTLE": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_LOG_VIA_STDERR": Info(title: "", defaultValue: "1", note: "Once Wine points stderr at madeira-log.txt, the app's own log lines are written through stderr too (appendToFile); 0 keeps a per-call file handle."),
        "env.MADEIRA_LOW_ALLOC": Info(title: "", defaultValue: "", note: "a low pointer usable by other APIs. Handing a low address to the guest is therefore not viable without translating every API boundary that can receive a buffer pointer, which is a far larger surface than this experiment. * The machinery ..."),
        "env.MADEIRA_MACH_ALIGN_FAULT": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_MADSYNC_SESSION": Info(title: "", defaultValue: "", note: "Madeira Dock: the app sets MADEIRA_MADSYNC_SESSION=0 only for a session that runs a game's one-time installers first (Wine's services.exe never answered its RPC clients under madsync on device). Unset, or any other value: unchanged. Read..."),
        "env.MADEIRA_MAP_RETRY_ANY": Info(title: "", defaultValue: "", note: "iOS: mach_vm_map can return KERN_INVALID_ADDRESS (→ ENOMEM) at certain addresses due to ASLR/system mappings. Keep scanning instead of aborting. ANY refusal means \"not here, try the next spot\" -- also the errno of an mmap over a ..."),
        "env.MADEIRA_MENU_BLUR": Info(title: "", defaultValue: "1", note: "0: the in-game menu's solid panel, as before 2026-10-28"),
        "env.MADEIRA_METAL_HUD_MAIN": Info(title: "", defaultValue: "", note: "1: Apple's Metal HUD only on the largest shown desktop window's Metal layer (its main layer), off on the other layers; default: Apple's own choice"),
        "env.MADEIRA_MFC": Info(title: "Microsoft MFC (mfc140.dll, mfc140u.dll)", defaultValue: "1", note: "On by default. MFC comes from the same Microsoft VC++ package as the C++ runtime and is linked into the game's system32; games that import it (Horizon Zero Dawn) stop at once without it. Wine has no MFC of its own. 0 leaves it out. Read at…"),
        "env.MADEIRA_MIP_CLAMP_AUTO": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_MONO_DEFAULTS": Info(title: "", defaultValue: "", note: "Wine Mono, 32- and 64-bit: mscoree sets MONO_THREADS_SUSPEND=coop and adds keep-delegates to MONO_DEBUG before Mono loads, and puts the previous values back once Mono has read them ; values already set win. 0 sets nothing."),
        "env.MADEIRA_MOUSE_ROUTING": Info(title: "Mouse routing and pointer-lock fixes", defaultValue: "1", note: "Default on. 0 restores the previous desktop cursor routing, mouse button callbacks, surface-touch handling and key-window-only pointer lock. Keyboard input and manual Ctrl+Alt+P remain available. Fully restart Madeira after changing this s…"),
        "env.MADEIRA_MSC_DYLIB": Info(title: "", defaultValue: "", note: "Host-only: lets the offline round-trip test point at the converter in the extracted package. Compiled out of the device build entirely, so the shipping runtime has exactly one place it will load the converter from."),
        "env.MADEIRA_NAV_KEYS_E0": Info(title: "", defaultValue: "", note: "Wine's own UI never noticed, because dialogs read the VK out of wParam. A GAME does notice: Unity reads the keyboard through raw input and DirectInput identifies keys by scan code (DIK_W is 0x11, not 'W'), so W/A/S/D were delivered, acce..."),
        "env.MADEIRA_NLS_EXTRA": Info(title: "Extra code page tables", defaultValue: "0", note: "Default off. 1: a code page table that is not loaded for every game (932, 936, 949, 950, 874, 1250, 1251, 1253-1258) is read from the app's nls/extra folder when the game asks for it; without the line such a request fails (GetCPInfo and Mu…"),
        "env.MADEIRA_NO_DFE": Info(title: "", defaultValue: "", note: "iOS-Madeira TARGETED A/B for the post-login hang. The renderer thread was sampled 9x at 97-100% CPU inside DeadFlagCalculationEliminination while everything else idled and Steam presented no further frames. FEX_O0 is the wro..."),
        "env.MADEIRA_NO_GL": Info(title: "", defaultValue: "", note: "Real opengl32 unix side (OpenGL ES / desktop GL through the winios WGL driver). MADEIRA_NO_GL=1 keeps the old GL-absent stub table. The wow64 table's thunks convert every embedded guest pointer with ios_wow_host_ptr() (patches/wine-openg..."),
        "env.MADEIRA_NO_HEAL": Info(title: "", defaultValue: "", note: "Healing default-ON since 2026-07-07: the patcher now rewrites ONLY IAT/delay-IAT slots (parsed from each pool copy's PE headers), so the 2026-07-04 breakage class — arm64x metadata slots whose consumers need PE VAs for identity/range com..."),
        "env.MADEIRA_NO_HEAL_ESCALATE": Info(title: "", defaultValue: "", note: ".data GLOBAL, not an IAT — the IAT-restricted pass finds nothing and the same VA keeps costing one Mach exception per Metal call (118K+ observed; handler saturation = the desktop \"freezes\"). When the IAT pass strikes out, scan each copy'..."),
        "env.MADEIRA_NO_IMAGE_LOW_ALIAS": Info(title: "", defaultValue: "", note: "ios_lowalloc_translate, whole-span bounds-checked) instead. Registration refuses on collision with an image window, another alias, the arena or the bottom 16 MB, so it can never shadow a real name. * Scope: only images whose PREFER..."),
        "env.MADEIRA_NO_IMAGE_RETIRE": Info(title: "", defaultValue: "", note: "drops virtual_mutex before returning, so the interval is genuinely free for a moment and another thread may legitimately take it. That is reported as a named loss, never overwritten. * MADEIRA_NO_IMAGE_RETIRE=1 disables the handoff entir..."),
        "env.MADEIRA_NO_LOW_ALIAS": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_NO_PLAIN_EXEC": Info(title: "", defaultValue: "", note: "1: never ask mprotect for PROT_EXEC; every executable request takes the JIT-pool path, as on a TXM device. For iOS 18 and iOS 26 devices without TXM, where it would succeed in place. Default off: as before."),
        "env.MADEIRA_NO_QUERY_CLIP": Info(title: "", defaultValue: "", note: "min_address)) report MEM_RESERVE up to the floor; - otherwise ask the kernel where the next host mapping is. Host ranges inside a Wine reserved area stay free (map_fixed_area may overwrite them); any other host mapping ends the free regi..."),
        "env.MADEIRA_NO_STEAM_IDENTITY": Info(title: "", defaultValue: "", note: "set by the library for one launch of a game from another store; not a setting"),
        "env.MADEIRA_NO_SUBFLOOR_XQUERY": Info(title: "", defaultValue: "", note: "a window above 4GB (between it and the task's floor) is marked with bit 63, which no PE base carries, so FEX files it as a window, not as a JIT alias (IosJitAlias.cpp)."),
        "env.MADEIRA_NO_UNIXCALL_DIRECT": Info(title: "", defaultValue: "", note: "iOS-Madeira Round 7 (2026-07-04): de-fault the unix-call path. Pool-executing EC callers read this slot and `blr` its value. With the baseline PE VA they exec-fault (~100 Mach round trips/present, ~0.5ms wall each = the bulk of the gamep..."),
        "env.MADEIRA_NSI_CACHE_MS": Info(title: "", defaultValue: "", note: "On by default (500 ms): an identical interface, address or route table read within this many milliseconds reuses the last result. 0 reads the host every time; at most 5000."),
        "env.MADEIRA_NSI_DEVICE_CACHE": Info(title: "", defaultValue: "", note: "On by default: without \\\\.\\Nsi, the failed open is remembered instead of being retried on every call. 0 retries every time."),
        "env.MADEIRA_NSI_NETWORK_TABLES": Info(title: "", defaultValue: "", note: "On by default: programs see this device's network interfaces, IP addresses and routes. 0 serves none of them, as before."),
        "env.MADEIRA_NSI_NOTIFY_PENDING": Info(title: "", defaultValue: "", note: "On by default: without \\\\.\\Nsi, an address-change request stays pending (the addresses do not change) instead of failing at once. 0 fails it as before."),
        "env.MADEIRA_NTDLL_DATA_SYNC_RANGE": Info(title: "ntdll data patches copy only the bytes asked for", defaultValue: "0", note: "Default off. 1: when a 64-bit game changes the protection of a few bytes of ntdll's writable data, only those bytes are copied to the copy ntdll runs from, not the whole page (which also overwrote live callbacks next to the slot). Logged a…"),
        "env.MADEIRA_ODD_VTABLE_REPAIR": Info(title: "", defaultValue: "", note: "mov rax, [rcx] ; loads RAX = klass | 1 mov rdx, [rax + 0x210] ; 1-byte misaligned read -> (slot1 >> 8) | (slot2 << 56) call [rax + 0x208] ; 1-byte misaligned read -> (slot0 >> 8) | (slot1 << 56) while bit 0 is set. The shifted read place..."),
        "env.MADEIRA_ONBOARDING": Info(title: "First-run Steam setup", defaultValue: "1", note: "`env.MADEIRA_ONBOARDING = 0` (madeira.cfg or the environment) never opens setup and hides \"Run setup again\". On by default."),
        "env.MADEIRA_ONE_SESSION_PER_RUN": Info(title: "", defaultValue: "1", note: "One Wine session per app run (see LibraryModel.sessionsThisRun)."),
        "env.MADEIRA_OPENGL": Info(title: "OpenGL through Mesa on D3D12", defaultValue: "0", note: "On: x64 games get Mesa's opengl32.dll (OpenGL 3.3 on D3D12, then Metal) when build/mesa-d3d12/build.sh has put it in the app. 0: Wine's builtin opengl32, which uses the native WGL OpenGL ES/Zink route. A game folder's own opengl32.dll stil…"),
        "env.MADEIRA_PAD_KBM": Info(title: "", defaultValue: "1", note: "Availability of the mode. 0 removes the per-game choice; the physical pad then always feeds XInput."),
        "env.MADEIRA_PAD_MODE": Info(title: "Controller API (player 1)", defaultValue: "", note: "XInput (default): every controller is an Xbox pad. hid: player 1 becomes a HID game controller, a DualSense (054C:0CE6) when it is a PlayStation pad, and leaves XInput; any other pad stays on XInput. dualsense/generic force the identity. R…"),
        "env.MADEIRA_PAD_OUTPUT": Info(title: "Rumble, adaptive triggers and lightbar to the pad", defaultValue: "", note: "On (default): XInput rumble plays on the controller (CoreHaptics), and in DualSense HID mode the game's output reports drive rumble, adaptive triggers (closest GameController mode), lightbar and player LEDs. hid: only the DualSense's; xinp…"),
        "env.MADEIRA_PANEL_IDLE": Info(title: "", defaultValue: "0", note: "hold the panel at 60 Hz under the 60 and 30 caps too. Without any display link a ProMotion iPhone lets the panel idle once nothing drives it: a 32-bit title under the 60 cap presented at a steady 9.9 FPS with the GPU 1% busy, eve..."),
        "env.MADEIRA_PASTE_INTERVAL_MS": Info(title: "Clipboard typing interval (ms)", defaultValue: "10", note: "Default 10 ms between pasted characters. Range 1-100 ms; use a longer interval for games that miss fast text input. Enforced at delivery as well as queueing. Restart the session after changing it."),
        "env.MADEIRA_PHONE_HOVER": Info(title: "", defaultValue: "0", note: "1: on iPhone, pointer interactions attach their drivers as on iPad, so hover from the AssistiveTouch cursor reaches the game view"),
        "env.MADEIRA_PHONE_IPAD_IDIOM": Info(title: "", defaultValue: "0", note: "1: the app runs with the iPad interface idiom on iPhone, so pointer lock is requested (Madeira's screens use iPad layouts)"),
        "env.MADEIRA_PIN_GRAPHICS_DLLS": Info(title: "Keep graphics DLLs loaded", defaultValue: "0", note: "Default off. On a D3D12 device/probe call, pins already loaded D3D12, DXGI and Wine Metal DLLs until normal process shutdown, preventing repeated unload/reload copies. Keeps DLL data live; does not recycle executable ranges or change GPU c…"),
        "env.MADEIRA_PIPE_TRACE": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_PIPE_TRACE_BYTES": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_PIPE_TRACE_LIMIT": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_PLACE_PROOF": Info(title: "", defaultValue: "", note: "0 walks the whole map on every failed large mapping; by default a failed walk is trusted for 2 s until a release."),
        "env.MADEIRA_POINTER_ABSOLUTE": Info(title: "", defaultValue: "1", note: "MADEIRA_POINTER_ABSOLUTE=0: the program's cursor never follows the iOS pointer's position; all motion is relative."),
        "env.MADEIRA_POINTER_AUTOLOCK": Info(title: "", defaultValue: "1", note: "MADEIRA_POINTER_AUTOLOCK=0: the pointer locks only on request, not while the program hides its cursor (see `AutoLock`)."),
        "env.MADEIRA_POINTER_HIDDEN_ABSOLUTE": Info(title: "", defaultValue: "", note: "MADEIRA_POINTER_HIDDEN_ABSOLUTE=1 (a game's own config): the program's cursor follows the iOS pointer's position even while it hides the Windows cursor, and the pointer never locks by itself. For a game that hides the cursor only to draw..."),
        "env.MADEIRA_POINTER_LOCK": Info(title: "", defaultValue: "1", note: "MADEIRA_POINTER_LOCK=0: the pointer is never locked and no lock button or chord is offered."),
        "env.MADEIRA_POOL_BIG_SLOT_BELOW": Info(title: "", defaultValue: "", note: "1 puts the existing image slot below the native hole; 0/default keeps it above."),
        "env.MADEIRA_POOL_BIG_SLOT_MB": Info(title: "", defaultValue: "", note: "N MB adjacent to a split-pool hole for one image of 64 MB or more (Social Club's libcef.dll); off by default."),
        "env.MADEIRA_POOL_CODE_DEFER_FREE": Info(title: "", defaultValue: "", note: "0: a FEX code buffer released while a thread runs in it is refused and stays live, as before"),
        "env.MADEIRA_POOL_CODE_EXIT_RECLAIM": Info(title: "Return an exited program's code buffers", defaultValue: "1", note: "On by default. When a program of the session exits (a launcher restarting itself, RockstarService.exe, a setup step), the emulator's code buffers it held go back to the JIT pool: reusable 3 seconds later, once no thread runs in them. Befor…"),
        "env.MADEIRA_POOL_CODE_KEEP_BIG": Info(title: "", defaultValue: "", note: "0: a code buffer request takes the smallest free buffer that fits, however much larger, as before"),
        "env.MADEIRA_POOL_HEAD_RESERVE_MB": Info(title: "", defaultValue: "", note: "48 to 256 MB of image headroom in the FEX pool-tail budget; 48/default keeps the existing policy. Region C is unchanged."),
        "env.MADEIRA_POOL_LOW_IMAGES": Info(title: "Small images in spare code-buffer space", defaultValue: "0", note: "Default off. If the normal JIT image allocation fails, copies up to 16 MB may use unallocated region C, preserving 4 MB for code buffers. Requires pool-low; 64-bit processes only. Does not shrink live buffers or the pool-low-margin."),
        "env.MADEIRA_POOL_NOEXEC_GIVEUP": Info(title: "", defaultValue: "", note: "code again (the [pool-poison] class). When the faulting code is the process's own ntdll copy, the exception dispatcher sits on the same dead pages, so delivering the fault faults again at the dispatcher, forever: device log 81, tw..."),
        "env.MADEIRA_POOL_QUARANTINE": Info(title: "", defaultValue: "", note: "OUT NON-EXEC off=0xa848000...). The next process started in that session (the windowed taskbar's in-session launcher: services.exe, then steam.exe) got its ntdll copy there and faulted NOEXEC at LdrInitializeThunk's first instruction, fo..."),
        "env.MADEIRA_POOL_RECYCLE_IMAGES": Info(title: "Images in retired code-buffer space", defaultValue: "0", note: "Default off. If other image allocations fail, retired region-C code buffers up to 64 MB may enter the image freelist after a 3-second grace, executable-page and thread-PC checks. Requires pool-low; 64-bit processes only. Live buffers and t…"),
        "env.MADEIRA_POOL_SECTION_CLAMP": Info(title: "", defaultValue: "", note: "EXECUTE from max_protection for good , so every later hand-out there was born non-executable: device logs 80-83 show [pool-poison] starting exactly at such an image's allocation end, after which every process started later in the ..."),
        "env.MADEIRA_POWER_GOV_BAND_MJ": Info(title: "", defaultValue: "", note: "energy (mJ) the running balance may drift before ECO switches (1000)"),
        "env.MADEIRA_POWER_GOV_MW": Info(title: "", defaultValue: "", note: "process CPU power target (mW) while a game presents; unset/0 = off"),
        "env.MADEIRA_POWER_PROBE": Info(title: "Log GPU and device power every 5 s", defaultValue: "0", note: "1: every 5 s a [power] line next to [xp]'s CPU energy: the GPU energy and time the driver charged to the app's coalition, the SoC's Energy Model counters (IOReport) and the battery's voltage and current (the whole device while unplugged),…"),
        "env.MADEIRA_PRELOAD_DLLS": Info(title: "Load these DLLs with the D3D12 device", defaultValue: "", note: "Default empty. DLL names separated by ';' (e.g. xinput1_4.dll): each program loads and pins them at its first D3D12 device or probe call, while the JIT pool still has room for their copies. RDR2 loads xinput1_4.dll only at its first contro…"),
        "env.MADEIRA_PRESENT_LIMITER": Info(title: "", defaultValue: "", note: "sleeps to an absolute deadline on the same timebase the scheduler uses, so it does not accumulate the per-iteration error a relative nanosleep ladder does and it does not quantise to a timer tick -- the failure mode the brief calls out, ..."),
        "env.MADEIRA_PRESENT_PIXELS": Info(title: "", defaultValue: "32-bit only", note: "WSI window extents are Windows pixels, not UIKit points. Applying the phone's 3x scale again made a 720p present render into a 4K drawable. Core Animation already maps that drawable onto the host view in points. Keep the correcti..."),
        "env.MADEIRA_PROBES": Info(title: "", defaultValue: "", note: "Madeira: MADEIRA_PROBES picks which always-on profilers start, for timing runs: unset/1 = all (as before); \"light\" = only the xprobe ([xp]/[xp-t]/[xp-api], counters read 4x a second, no thread is ever suspended); 0 = none. The thread sam..."),
        "env.MADEIRA_PROCESS_APC_QUEUE": Info(title: "", defaultValue: "", note: "duplicated that handle, so the action returned 5 and the install ended with 1603. * Instead queue it on the process's first live thread; that thread runs system APCs at its next interruptible server wait (check_wait returns STATUS_KERNEL..."),
        "env.MADEIRA_PROC_GATE_STEAM": Info(title: "", defaultValue: "", note: "the full Windows Steam client (steam.exe, started by the in-session launcher or a library entry) runs its own crash reporter, hardware survey and GPU probes. These names were refused because, before a helper's crash or sel..."),
        "env.MADEIRA_PROFILE_LOCALLOW": Info(title: "", defaultValue: "", note: "0 leaves the profile's AppData\\LocalLow folder missing, as before."),
        "env.MADEIRA_PROMOTE": Info(title: "Hold the display at its maximum rate", defaultValue: "0", note: "The opt-in above; read when a session's pacing is applied."),
        "env.MADEIRA_PROMOTE_KICK": Info(title: "Display link: commit a transaction per tick", defaultValue: "0", note: "experiment: 1 adds a one-pixel layer whose opacity alternates on every display-link tick, so each tick commits a CoreAnimation transaction. For a title parked 80 ms a frame in nextDrawable with the 120 Hz link armed: if the waits fall with…"),
        "env.MADEIRA_PSO_ARCHIVE_INLINE": Info(title: "Pipeline archive: compile once", defaultValue: "1", note: "With pso-archive on: 1 (default) compiles a pipeline the saved archive does not have once, into an open archive, and creates it from there. 0: created, then compiled again on one queue to be added (the first version; it kept about a quarte…"),
        "env.MADEIRA_PSO_ARCHIVE_MB": Info(title: "Pipeline archive: size cap (MB)", defaultValue: "1024", note: "With pso-archive on: the most a game's pipeline archive folder keeps across builds. Over it, the oldest chunks are deleted at launch down to three quarters; a session adds none once it is reached."),
        "env.MADEIRA_PSO_ARCHIVE_PER_BUILD": Info(title: "Pipeline archive: one per build", defaultValue: "0", note: "1: the archive folder sits in the build's shader cache directory and goes with it when a new build prunes it (the first version). Off: Madeira/PipelineArchive in LOCALAPPDATA, kept across builds."),
        "env.MADEIRA_QUIET": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_RDR2_VA_HOLD": Info(title: "Keep 8960 MB free for Red Dead Redemption 2", defaultValue: "0", note: "Default off; only with env.MADEIRA_SC_PA_POOLS = 2. 1: Social Club's layout 2 keeps libcef.dll's PartitionAlloc pools at 256 MB and its metadata at 1 GB, chrome_elf.dll's metadata at 6.25 GB, gives the rest of the app's 4 GB hold to Wine's…"),
        "env.MADEIRA_REAL_SUSPEND": Info(title: "", defaultValue: "", note: "Read on every call: the app sets it per session (a game's \"Pause threads fully\" switch, BCDLaunch.realSuspend), and this server runs again in the same process for the next session of the app run. Logged when it changes."),
        "env.MADEIRA_RECOVERY_LOG_SAMPLE": Info(title: "Sample routine instruction recovery logs", defaultValue: "0", note: "Default off. 1: of FEX's records about each recovered invalid instruction (C000001D) only the first 16 and every 1024th are kept, and of the shared-trap ILL reports the first 8 and every 1024th; only the log changes. For a game that recove…"),
        "env.MADEIRA_REDELIV_CHILD_ONLY": Info(title: "A fault storm in a helper program ends only that program", defaultValue: "1", note: "Default on: when the fault-storm guard gives up on a thread of a program the session started (a launcher's helper), that program ends and the app keeps running; the session's first program keeps the old ending. 0: the whole app ends for ev…"),
        "env.MADEIRA_REDELIV_VPROTECT": Info(title: "", defaultValue: "", note: "A protection change between two deliveries (FEX's self-modifying-code cycle: unprotect, recompile, protect again) is real progress. Tag redeliv_guest_rip with the protection sequence number so the consecutive counter below starts a new r..."),
        "env.MADEIRA_REGFLUSH_SAVE": Info(title: "", defaultValue: "", note: "MADEIRA_REGFLUSH_SAVE=0: RegFlushKey does nothing again; the registry is saved periodically and at exit"),
        "env.MADEIRA_REPLACE_READONLY_LINK": Info(title: "", defaultValue: "", note: "On by default: an overwrite (supersede, overwrite, overwrite-if) through a link to a read-only file replaces the link with a new file. 0 fails it with access denied."),
        "env.MADEIRA_REPLY_OWN_WRITABLE": Info(title: "Server replies: a writable page is written in place", defaultValue: "1", note: "on (default): a server reply whose buffer lies in the JIT pool's address range but on a page that is writable at its own address (a page the pool gave up, which the system reused for a thread stack) is stored there, not through the pool's…"),
        "env.MADEIRA_RESERVED_REMAP": Info(title: "Last resort for a refused window placement", defaultValue: "1", note: "Default on, and only on the path that already fails: when the system refuses every placement of a 32-bit program's request inside its 4 GB window (ENOMEM), the first refused range, which Wine's tables call free, is unmapped and mapped agai…"),
        "env.MADEIRA_RESERVED_RETRY": Info(title: "", defaultValue: "", note: "So, on a small address map only (ios_wow_small_va_slots != 0, which is 0 on a 512 GB map) and only after the MAP_FIXED itself failed with ENOMEM, the next free range of the same area is tried, at most IOS_RESERVED_RETRY_MAX times, each o..."),
        "env.MADEIRA_RESOURCE_MAP_COPY": Info(title: "", defaultValue: "", note: "version queries and kept both copies until it exited; the pool ran out 1.4 s later. Set by virtual_map_section around the map, cleared by map_image_into_view for an image with a CLR header (CoreCLR maps its R2R assemblies this way and ru..."),
        "env.MADEIRA_RESTORE_BORN_MINIMIZED": Info(title: "", defaultValue: "", note: "0: while a Dock start's census runs, a window first shown minimized stays minimized"),
        "env.MADEIRA_RESTORE_BORN_MINIMIZED_LATE": Info(title: "", defaultValue: "", note: "0: a window first shown minimized after a Dock start's starting screen has ended stays minimized"),
        "env.MADEIRA_RTCS_LOG": Info(title: "", defaultValue: "", note: "all: every \"[rtcs] pre\" line; N: at most N a second per thread (default 10, 0 none)"),
        "env.MADEIRA_RUNTIME_SETTINGS": Info(title: "", defaultValue: "1", note: "The Display and Memory and sync settings, on the long page and as pages."),
        "env.MADEIRA_RW_ALIAS_RETRY": Info(title: "", defaultValue: "1", note: "A process without the extended-virtual-addressing entitlement has a map that ends at 0xfc0000000 (63 GB). The 0x7000000000 hint is past its end, and an ANYWHERE search that starts past the end of the map does not wrap: every alias failed..."),
        "env.MADEIRA_SCM_ON_DEMAND": Info(title: "Start the service manager when a program needs it", defaultValue: "1", note: "on (default): when a 64-bit program opens the service manager and services.exe is not running (the session did not start Windows services first), sechost starts it once per process, waits up to 20 s for its pipe and asks again. Before, the…"),
        "env.MADEIRA_SCREEN_H": Info(title: "", defaultValue: "", note: "MADEIRA_SCREEN_W/H: the virtual monitor's session default size, exported by the app before Wine starts (1024x768 when unset); a program's ChangeDisplaySettings changes the current size from there. MADEIRA_SCREEN_SRC names where the defau..."),
        "env.MADEIRA_SCREEN_SRC": Info(title: "", defaultValue: "", note: "MADEIRA_SCREEN_W/H: the virtual monitor's session default size, exported by the app before Wine starts (1024x768 when unset); a program's ChangeDisplaySettings changes the current size from there. MADEIRA_SCREEN_SRC names where the defau..."),
        "env.MADEIRA_SCREEN_W": Info(title: "", defaultValue: "", note: "MADEIRA_SCREEN_W/H: the virtual monitor's session default size, exported by the app before Wine starts (1024x768 when unset); a program's ChangeDisplaySettings changes the current size from there. MADEIRA_SCREEN_SRC names where the defau..."),
        "env.MADEIRA_SC_CEF": Info(title: "Social Club's Chromium in one process", defaultValue: "1", note: "On by default; 0 turns it off. SocialClubHelper.exe runs --single-process with PartitionAllocBackupRefPtr disabled and V8 --jitless (MADEIRA_JITLESS = 0 keeps V8's JIT), its --type= children are refused, and a process with socialclub.dll m…"),
        "env.MADEIRA_SC_CEF_FLAGS": Info(title: "Extra SocialClubHelper.exe switches", defaultValue: "", note: "Appended verbatim to SocialClubHelper.exe's command line while env.MADEIRA_SC_CEF is on, e.g. --disable-gpu or --enable-logging=file --v=1. A --js-flags= in it gets --jitless as its first flag (Chromium keeps only the last --js-flags=), un…"),
        "env.MADEIRA_SC_GAME_CEF": Info(title: "", defaultValue: "", note: "env.MADEIRA_SC_GAME_CEF = 1 (experiment): the game keeps its libcef.dll. GTA log 2026-10-02 23:03 (file trace): GTA5_Enhanced.exe's socialclub.dll probes the Social Club files, loads libcef.dll -- refused here -- and later the helper con..."),
        "env.MADEIRA_SC_IPC_SPLIT": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_SC_PA_POOLS": Info(title: "Room for Social Club's PartitionAlloc pools", defaultValue: "", note: "1: Wine boots with the emulator's arena at 0x7d00000000 (12 GB instead of 16 GB) and keeps 0x7c00000000 +4 GB free, so SocialClubHelper.exe's 32 GB PartitionAlloc reservation, which must start on a 32 GB boundary, gets 0x7800000000 (20 GB…"),
        "env.MADEIRA_SC_RENDER_HANDLER": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_SECTION_PROCESS_LIMIT": Info(title: "", defaultValue: "", note: "map_section serves both guest and native helpers. The shared WoW ceiling remains nonzero after a guest starts, but a later native helper has no guest window. Passing that ceiling to its locale/API-set mapping forces an impossible..."),
        "env.MADEIRA_SESSION_DIAGNOSTICS": Info(title: "", defaultValue: "0", note: "The in-game menu's Diagnostics (frame capture, GPU sync), for testing: off unless madeira.cfg sets env.MADEIRA_SESSION_DIAGNOSTICS = 1. A capture writes render-target pixels to Documents/capture, which Files shows."),
        "env.MADEIRA_SESSION_TOOLS": Info(title: "", defaultValue: "1", note: "The in-game Aspect & scaling choice sticks to the game. MADEIRA_SESSION_TOOLS=0 hides that picker and leaves the stored choice alone."),
        "env.MADEIRA_SETTINGS_PAGES": Info(title: "", defaultValue: "1", note: "On by default: the Settings tab lists its pages, each opening the sections it holds. 0: the one long page with every section, as before."),
        "env.MADEIRA_SETUPAPI_MEDIA_FIX": Info(title: "", defaultValue: "", note: "Madeira ask for the media again only when the answer named a new place to look. An unattended install's callback (the default one included) answers \"same place\" forever, and the loop never ended; report a copy error instead. Idea..."),
        "env.MADEIRA_SHARED_SECTION_EXEC": Info(title: "", defaultValue: "", note: "env.MADEIRA_SHARED_SECTION_EXEC = 1"),
        "env.MADEIRA_SHARED_SECTION_PRIVATE": Info(title: "", defaultValue: "", note: "0 fails the load of an image whose shared writable section is not aligned to the host page, as before; otherwise that section is mapped private."),
        "env.MADEIRA_SHARE_PROBE": Info(title: "", defaultValue: "", note: "task #34 [share-probe]: DEFAULT-OFF (set MADEIRA_SHARE_PROBE=1). ml79: running it inline here (pre-detach, on explorer's boot thread) wedged the session — exec-at-alias hangs while the debugger is attached. Gated + deferred to a scratch ..."),
        "env.MADEIRA_SIGNING_REFRESH": Info(title: "", defaultValue: "0", note: "Off by default: no Settings section, no refresh or offer over the library and no sign-in taken from an installer. A refresh asks Apple's portal for a profile on the Apple ID that signs other apps too, so the installer that signed Madeira..."),
        "env.MADEIRA_SMALL_STACK_EXES": Info(title: "Programs whose threads keep a 2 MB stack", defaultValue: "", note: "Empty by default: every thread stack is at least 8 MB (Chromium needs that). Exe names, separated by commas (e.g. RDR2.exe): threads of these programs get the stack they ask for, at least 2 MB, so their stacks take less of the shared memor…"),
        "env.MADEIRA_SMC_HOT_PAGE": Info(title: "", defaultValue: "", note: "MADEIRA: hot SMC pages (InvalidationTracker::EnableHotSMCPages). MADEIRA_SMC_HOT_PAGE: unset = 64 write faults within a second, 0 = off (every write to a code page invalidates it), N = threshold."),
        "env.MADEIRA_SOCK_WIRE": Info(title: "", defaultValue: "", note: "OFF for the timing run. Each call costs a getpeername(), and this fires on every send/recv — Steam's CM ping budget is 1000 ms total. * Also note before re-enabling: the 0x17 classifier below is WRONG FOR TLS 1.3. Everything after..."),
        "env.MADEIRA_SPAWN_BLOCK": Info(title: "", defaultValue: "", note: "madeira-bcd: more optional helpers, named per game. Every x64 pseudo- process copies its own system DLLs into the JIT pool and gets a 16 MB code buffer. GTA V Enhanced build 374 (2026-10-04 09:25): with SocialClubHelper.exe's 240 MB libc..."),
        "env.MADEIRA_SPIN_DIAG": Info(title: "", defaultValue: "", note: "env.MADEIRA_SPIN_DIAG=0: no [spin] at all"),
        "env.MADEIRA_SRCWATCH": Info(title: "", defaultValue: "", note: "competing for it means whichever runs first silently wins and the other is never armed at all — a probe that reports nothing while looking healthy. There are now two subjects: * \"render\" — win32u's dibdrv_PutImage, Chromium's SOURCE bitm..."),
        "env.MADEIRA_SRCWATCH_ROWS": Info(title: "", defaultValue: "", note: "1. TARGETING. Arming the whole 1.2MB bitmap spreads a 400-attribution budget across ~76 pages, so the clear (which touches EVERY page first) dominates and the content painters — the writers that would name a displaced band — stay invisib..."),
        "env.MADEIRA_SRV_DIRECT": Info(title: "Run simple server requests on the calling thread", defaultValue: "0", note: "Default off. 1: the Wine server's simplest requests (opening files and their descriptors, closing handles, mappings looked up, registry keys and values, events, semaphores, mutexes, completion ports) run on the thread that asks, under the…"),
        "env.MADEIRA_SRV_DOORBELL": Info(title: "", defaultValue: "", note: "0: read every client fd on every pass, as before"),
        "env.MADEIRA_SRV_ECO_FOLLOW": Info(title: "Server thread follows ECO", defaultValue: "0", note: "Default off. 1: while ECO is on, the Wine server thread runs at utility QoS (ECO's default class) instead of user-interactive, so it moves to the efficiency cores with the game's threads, and back when ECO goes off. In Horizon Zero Dawn's…"),
        "env.MADEIRA_SRV_FD_SOCKET": Info(title: "File descriptors through the process socket", defaultValue: "0", note: "Kill switch, default 0: a file's descriptor comes back in the server's get_handle_fd reply (a copy the server makes; it shares this process's descriptor table), the same descriptor without a sendmsg, a recvmsg, an fcntl and two server log…"),
        "env.MADEIRA_SRV_FGETPATH": Info(title: "Name opened files with one call (server)", defaultValue: "0", note: "1: the Wine server takes the path of a file it has just opened from its descriptor (fcntl F_GETPATH) instead of realpath, which checks the path one folder at a time (~0.5 ms a file on the device). Same resolved path; realpath stays the fal…"),
        "env.MADEIRA_SRV_FULLSCAN_MS": Info(title: "", defaultValue: "", note: "ms between reads of every client fd with the doorbell on (default 10)"),
        "env.MADEIRA_SRV_IDLE_US": Info(title: "Server loop's longest sleep (us)", defaultValue: "1000", note: "Default 1000 (1 ms, as before); 100 to 50000. Requests and timers wake the Wine server at once; only its socket polls and fd scans wait for this tick, so a longer one means fewer server wake-ups while idle (1000 a second at the default) an…"),
        "env.MADEIRA_SRV_LOG_ALL": Info(title: "Every per-descriptor server log line", defaultValue: "0", note: "Kill switch, default 0: the Wine server's add_poll_user and send_client_fd log lines (one per opened file or descriptor sent, each a formatted write to the log file on the server thread) are written for their first 64 and then every 1000th…"),
        "env.MADEIRA_SRV_NOSEM": Info(title: "", defaultValue: "", note: "zero, semaphore_timedwait returns instantly forever, and the loop stops sleeping — measured 2,935 iter/s against a 1 ms floor that caps it at ~1,000/s. * This gate changes ONLY the wait mechanism. sleep_ns is computed identically a..."),
        "env.MADEIRA_SRV_POLL_US": Info(title: "", defaultValue: "", note: "us between socket polls and fd scans with the doorbell on (default 1000, 0 every pass)"),
        "env.MADEIRA_SRV_WAKE_COALESCE": Info(title: "", defaultValue: "", note: "0: one wake signal per request, as before"),
        "env.MADEIRA_SRW_HANG_DIAG_S": Info(title: "Diagnostic: 32-bit SRW-lock hangs", defaultValue: "30", note: "a 32-bit thread that has waited this many seconds without a timeout for an SRW lock held by shared owners has every 32-bit thread of its process logged once ([srw-hang]: x86 registers, EBP chain, module-resolved stack words), so the holder…"),
        "env.MADEIRA_SRW_HANG_KILL_S": Info(title: "End a process stuck on an SRW lock", defaultValue: "", note: "unset (default): never. N: once a 32-bit thread has waited N seconds for an SRW lock as above, the wineserver ends its process, as TerminateProcess from another process would, so a parent that restarts its helper gets a new one (Steam rest…"),
        "env.MADEIRA_STACK_OVERFLOW_EXIT": Info(title: "", defaultValue: "", note: "the whole pseudo-process ends, as on Windows (idea from the published patch 0058 of another iOS port). Ending only the thread left a half-dead process behind: a browser helper without its renderer thread stays up and is never res..."),
        "env.MADEIRA_STDIN_PIPE": Info(title: "", defaultValue: "", note: "env.MADEIRA_STDIN_PIPE = 1 puts a pipe on fd 0 so a guest can read stdin at all; without it fd 0 is whatever iOS gave us, which reads as immediate EOF. Off by default: an unread pipe fills at 64 KB and blocks the guest on its next write,..."),
        "env.MADEIRA_STDOUT_PIPE": Info(title: "", defaultValue: "", note: "env.MADEIRA_STDOUT_PIPE = 1 moves the guest's stdout onto its own pipe, leaving fd 2 on madeira-log.txt. That is the seam the code already had: Wine's err:/warn: channels and every dprintf(STDERR_FILENO, ...) are stderr, the guest's prin..."),
        "env.MADEIRA_STEAM_ALLOW_CRASHPAD": Info(title: "Steam web helper: allow its crash reporter", defaultValue: "0", note: "1 (the Steam Big Picture list) lets steamwebhelper.exe start exactly one kind of child, --type=crashpad-handler, with its command line unchanged; without it the 32-bit web helper ends itself at start (crash server failed to launch). Every…"),
        "env.MADEIRA_STEAM_APPID": Info(title: "", defaultValue: "", note: "set by the library for one direct Steam start (Start with: The game); not a setting"),
        "env.MADEIRA_STEAM_APPPATH": Info(title: "", defaultValue: "", note: "that game's install folder, with MADEIRA_STEAM_APPID; not a setting"),
        "env.MADEIRA_STEAM_CLOUD": Info(title: "", defaultValue: "1", note: "Whether Steam Cloud saves sync: Settings › Steam Cloud saves, kept in madeira.cfg as env.MADEIRA_STEAM_CLOUD (on unless it is 0; docs/STEAM_CLOUD.md). Turning it back on syncs the installed games at once."),
        "env.MADEIRA_STEAM_CLOUD_AUTO": Info(title: "", defaultValue: "1", note: "`env.MADEIRA_STEAM_CLOUD_AUTO = 0`: compare only; nothing is copied either way without the user asking on the game's page."),
        "env.MADEIRA_STEAM_CLOUD_PLAY_CHECK": Info(title: "", defaultValue: "1", note: "Saves that need the user's choice (count)."),
        "env.MADEIRA_STEAM_CLOUD_QUIT": Info(title: "", defaultValue: "1", note: "A game cannot be closed from Madeira, so its saves otherwise reach the cloud only at the next app start. The session menu's \"Upload saves and close Madeira\" sends them now: the app takes the account back from the session's client, upload..."),
        "env.MADEIRA_STEAM_CLOUD_REMOTECACHE": Info(title: "", defaultValue: "1", note: "`env.MADEIRA_STEAM_CLOUD_REMOTECACHE = 0`: Valve's client's remotecache.vdf is left as the client wrote it, as before SteamRemoteCache."),
        "env.MADEIRA_STEAM_DLC": Info(title: "", defaultValue: "1", note: "Owned DLC is listed and downloaded with its game (SteamDLC); off with `env.MADEIRA_STEAM_DLC = 0`, when downloads take no DLC as before."),
        "env.MADEIRA_STEAM_LIBRARY": Info(title: "", defaultValue: "1", note: "Off with `env.MADEIRA_STEAM_LIBRARY = 0`, or without Madeira Dock (a downloaded game starts through it)."),
        "env.MADEIRA_STEAM_SIGNIN": Info(title: "", defaultValue: "1", note: "`env.MADEIRA_STEAM_SIGNIN = 0` hides the sign-in button."),
        "env.MADEIRA_STEAM_TRACE": Info(title: "", defaultValue: "0", note: "Logging for Steam sign-in. `event` lines are the always-on, low-volume record ([steam-signin]). They never contain tokens, passwords, Steam Guard codes, account names, Steam IDs or message payloads. `trace` lines are protocol-level detai..."),
        "env.MADEIRA_STEAM_WORKSHOP": Info(title: "", defaultValue: "1", note: "Off with `env.MADEIRA_STEAM_WORKSHOP = 0`: no Workshop page or area."),
        "env.MADEIRA_STORAGE_DEVICE": Info(title: "", defaultValue: "", note: "0: no \\\\.\\\\PhysicalDrive0 (the prefix disk's capacity)"),
        "env.MADEIRA_STORE_STEAM_IDENTITY": Info(title: "Give games from other stores the fixed Steam identity", defaultValue: "0", note: "off (default): a game from another store (an Epic library entry) starts without the fixed Steam identity (SteamAppId, SteamGameId, SteamAppPath) every other launch outside Madeira Dock gets. With it, a game's launcher took its Steam path,…"),
        "env.MADEIRA_STRICT_SPLITLOCK": Info(title: "", defaultValue: "", note: "MADEIRA: StrictInProcessSplitLocks defaults ON for 32-bit guests. * An x86 LOCK op on a word that crosses a 16-byte boundary faults on this host and FEX emulates it as two separate half-width CASes. Without the strict mode two threads do..."),
        "env.MADEIRA_STUCK_CHECK": Info(title: "", defaultValue: "", note: "MADEIRA_STUCK_CHECK=0 turns off the check that completes a store stuck across a 16 KB page."),
        "env.MADEIRA_STUCK_WAIT_SECS": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_SUBFLOOR_HIGH": Info(title: "Images based just above 4 GB run through a window", defaultValue: "1", note: "on (default): a 64-bit exe or DLL without relocations whose base lies between 4 GB and the start of the app's address space (an old x64 linker's default 0x100000000, which iOS never maps) is mapped elsewhere, its header names the real base…"),
        "env.MADEIRA_SUBFLOOR_LOWENTRY": Info(title: "", defaultValue: "", note: "0 = a fixed-base exe starts at its real (high) entry"),
        "env.MADEIRA_SUBFLOOR_SEH": Info(title: "", defaultValue: "", note: "0 = no unwind data for code at a fixed-base image's low addresses"),
        "env.MADEIRA_SUBFLOOR_VM": Info(title: "", defaultValue: "", note: "0 = VirtualProtect/VirtualQuery leave fixed-base image windows alone"),
        "env.MADEIRA_SURF_SENTINEL": Info(title: "", defaultValue: "", note: "them, and I reported the first as settled when the data did not support it. * Fix: after each flush, stamp every currently-zero pixel with a sentinel. That leaves NO zero pixels behind, so the next flush classifies every pixel with no bo..."),
        "env.MADEIRA_SURF_SEQ": Info(title: "", defaultValue: "", note: "Also drives MADEIRA_SURF_SEQ: bursts of N CONSECUTIVE frames, so the black regions that change every frame can be measured frame-to-frame offline. The 2s-throttled first/latest dump structurally cannot show that. Dirty rect goes in the f..."),
        "env.MADEIRA_SWAP_CHURN_TIGHT_MB": Info(title: "", defaultValue: "", note: "MB left before the app's memory limit below which churny sizes are tiered too (default 768, 0 = never)"),
        "env.MADEIRA_SWAP_COVERAGE": Info(title: "Swap tier coverage", defaultValue: "", note: "Which allocations the swap tier backs with its file (only when the tier is on). Large allocations (classic, the default): single 8 MB+ commits in the guest band. All allocations of 1 MB+ (blocks). 1 MB+ and overflow (wide): blocks plus all…"),
        "env.MADEIRA_SWAP_DONOR_ONLY": Info(title: "", defaultValue: "", note: "the tier maps the donor pool only, no file"),
        "env.MADEIRA_SWAP_FILE": Info(title: "", defaultValue: "", note: "the tier maps the donor pool only, no file"),
        "env.MADEIRA_SWAP_HEAT": Info(title: "", defaultValue: "", note: "1: [swap] heat census of re-read swap extents; 2: plus new blocks of re-read sizes stay anonymous while the footprint has room; unset/0: off"),
        "env.MADEIRA_SWAP_HEAT_FP_MB": Info(title: "", defaultValue: "", note: "swap-heat 2: the filter pauses while the footprint is at or above this (MB, 6656)"),
        "env.MADEIRA_SWAP_HEAT_MIN": Info(title: "", defaultValue: "", note: "swap-heat 2: re-reads of a block size (in two extents or more) before its new blocks stay anonymous (6)"),
        "env.MADEIRA_SWAP_MB": Info(title: "", defaultValue: "", note: "the tier maps the donor pool only, no file"),
        "env.MADEIRA_SWAP_PUNCH_DEFER": Info(title: "", defaultValue: "", note: "MADEIRA_SWAP_PUNCH_DEFER=0 keeps every swap file punch synchronous, under the virtual lock."),
        "env.MADEIRA_SWAP_RESERVE_MAX_MB": Info(title: "Swap tier: largest reservation backed (MB)", defaultValue: "", note: "The largest new reservation the swap tier backs whole: 256 MB in wide (at most 4 GB), 8 GB in broad (at most 16 GB). 9216 with broad coverage (swap-mode = 2) also backs Red Dead Redemption 2's 8960 MB heap with the file. Read at session st…"),
        "env.MADEIRA_SWAP_TITLE_CHURN": Info(title: "Short-lived memory of the game stays in RAM", defaultValue: "1", note: "On by default: a 64-bit game started beside 32-bit helpers keeps memory it frees and allocates again soon in RAM instead of the swap file, until less than MADEIRA_SWAP_CHURN_TIGHT_MB is left before the memory limit. 0: that memory goes to…"),
        "env.MADEIRA_SWAP_X64_CHURN": Info(title: "Swap tier: churn filter for 64-bit programs beside a 32-bit one", defaultValue: "0", note: "off (the default) sends a 64-bit program's short-lived allocation sizes to the swap file too while a 32-bit program is in the session, instead of leaving them anonymous (the churn filter): beside a 32-bit title the launcher chain is idle,…"),
        "env.MADEIRA_SWAP_X64_TITLE": Info(title: "", defaultValue: "", note: "1 (the app): the session's title is 64-bit, its 32-bit programs helpers; donor RAM first beside them"),
        "env.MADEIRA_TAIL_CARVE_EXEC_CHECK": Info(title: "Refuse a code buffer that cannot execute", defaultValue: "1", note: "Default on: a new emulator code buffer whose first 16 MB hold a JIT-pool page that lost execute permission for good is refused, and the emulator asks for half the size elsewhere. 0: every buffer is granted, as before. Read once per session."),
        "env.MADEIRA_TASK_EXC": Info(title: "", defaultValue: "", note: "Opt-out only: this strictly removes a dependency on a port we do not own, so it defaults ON. MADEIRA_TASK_EXC=0 restores the pre- behaviour for a same-build A/B against the ~54s stall."),
        "env.MADEIRA_THERMAL_CAP": Info(title: "", defaultValue: "0", note: "Opt-in `env.MADEIRA_THERMAL_CAP = 1`: when iOS reports the device as serious or critical, a session paced at the 60 cap, MAX or RAW drops to the 40 cap (three refreshes at 120 Hz, so evenly spaced; the 30 cap where 40 is not offered). A ..."),
        "env.MADEIRA_THIN_RESERVE": Info(title: "", defaultValue: "", note: "1 unread, 0 off, 1 on"),
        "env.MADEIRA_THIN_RESERVE_AFTER_GB": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_THIN_RESERVE_MB": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_THREADNAME_SWALLOW": Info(title: "", defaultValue: "", note: "healthy, over a printf. On Windows with no debugger attached this is a no-op. * So swallow it and continue, exactly as the DBG_CONTINUE path above does. This does not paper over the stuck unwind (task #38) -- it stops a benign event from..."),
        "env.MADEIRA_THREAD_QOS": Info(title: "", defaultValue: "", note: "end = 0;"),
        "env.MADEIRA_THREAD_REAP_CHECKED": Info(title: "Check the previous exited thread before freeing it", defaultValue: "1", note: "on (default): a thread that exits frees the previous exited thread's stacks only after finding that thread, by its process, thread id and pthread, in the live TEB list (the hand-off env.MADEIRA_EA_CEF = 1 already used). 32-bit processes st…"),
        "env.MADEIRA_THREAD_REUSE": Info(title: "", defaultValue: "", note: "On by default. MADEIRA_THREAD_REUSE=0 never gives a full thread registry's exited or purged entries to new threads (a session again registers 512 threads at most)."),
        "env.MADEIRA_THREAD_STACK_SPILL": Info(title: "New threads may use the kernel's pick when memory space is full", defaultValue: "0", note: "Default off. 1: a new thread's 1 MB kernel stack (and its emulator stack) is looked for from the start of Wine's furniture band instead of from 4 GB (each new thread no longer tries about 300 refused addresses first), and when that band is…"),
        "env.MADEIRA_TIMER_FAIRNESS": Info(title: "Timers run while a window keeps repainting", defaultValue: "1", note: "Default on. A thread gets its paint messages before its timers, so a window that invalidates itself while it paints starved every timer of that thread for good: the Rockstar Games Launcher installer, whose status text and finish page run o…"),
        "env.MADEIRA_TINY_WINDOW_FIX": Info(title: "Size a tiny game window to the screen", defaultValue: "0", note: "Default off. 1: a window a swapchain presents into whose client area stays under 160x120 for 3 seconds while the swapchain draws 320x200 or more is sized to the virtual screen (at most twice per window). Needs a desktop (Dock) session. Log…"),
        "env.MADEIRA_TLSWATCH": Info(title: "", defaultValue: "", note: "OPT-IN. The diagnosis is closed ( fixed the TLS-slot aliasing), but this stayed armed on every new thread, write-protecting its 16 KB TLS page. A UE 5.4 worker's plain TLS-slot store compiles to a store-release (stlr), ..."),
        "env.MADEIRA_TLS_X64": Info(title: "", defaultValue: "0", note: "x64 fast path for TlsGetValue (kernelbase). Default off (experimental). 1: a TLS index below 64 is read in the x64 JIT code, without a round trip into native code. Read when a 64-bit program starts."),
        "env.MADEIRA_TOTAL_PHYS_MB": Info(title: "", defaultValue: "", note: "The limit is MEASURED, not assumed: os_proc_available_memory() is what remains before jetsam, and TASK_VM_INFO.phys_footprint is what is already charged, so their sum is this process's effective total. Cached on first use so the advertis..."),
        "env.MADEIRA_TOUCH_MOUSE": Info(title: "", defaultValue: "", note: "1: touches always reach the program as a mouse, 0: never; default: not while touch controller mappings are shown"),
        "env.MADEIRA_TOUCH_XINPUT": Info(title: "Touch controller as XInput player 1", defaultValue: "", note: ""),
        "env.MADEIRA_UI_LOG_IDLE": Info(title: "", defaultValue: "1", note: "Pending batched diffs to apply on main thread"),
        "env.MADEIRA_UNIX_EXIT_ROUTE": Info(title: "", defaultValue: "", note: "MADEIRA_UNIX_EXIT_ROUTE=0: a fatal unix-side error calls plain (shimmed) exit() again"),
        "env.MADEIRA_USD_TIME": Info(title: "", defaultValue: "", note: "The same frozen page makes every \"N ms have passed since X\" test in a guest false for the life of the process: a headless host that sits online and re-checks a condition \"5 s after sign-in\" never reaches its check, and its own 90 s wall-..."),
        "env.MADEIRA_USER_VA_GB": Info(title: "Address space the game is told it has (GiB)", defaultValue: "0", note: "Default 0 (off): a 64-bit game is told its user address space is what the device maps. N (4-4096, never more than the real figure): it is told N GiB; only the figure changes, not placement. For a game that sizes one reservation from it and…"),
        "env.MADEIRA_USE_ARM64EC": Info(title: "", defaultValue: "", note: "Heuristic: x86_64 guest exes (cube-x64, hello-x64, real games like Thumper) need the arm64ec-windows bundle (ARM64EC hybrid system DLLs that interop with FEX-translated x86_64 code). ARM64-native tests (cube.exe) use the aarch64-windows ..."),
        "env.MADEIRA_VALLOC_LOG_ALL": Info(title: "", defaultValue: "", note: "Bounded. A WoW64 process lives in its own 4 GB window, so every one of its allocations carries zero_bits and lands \"above\" its 32-bit limit by design; the uncapped branch below logged each of them: 127,000 lines (22 MB of a 25 MB device ..."),
        "env.MADEIRA_VA_PRESSURE_GAP_OK": Info(title: "A slow scan through the refused hole is not pressure", defaultValue: "0", note: "Default off. 1: an address-space scan that succeeded after grinding through the hole iOS refuses below the app image does not mark the address space as under pressure (which steers big reservations away from the swap tier). Read once."),
        "env.MADEIRA_VCREDIST": Info(title: "", defaultValue: "1", note: "`env.MADEIRA_VCREDIST = 0` (madeira.cfg or the environment) leaves the Visual C++ runtime installer out of setup and Settings. On by default."),
        "env.MADEIRA_VCREDIST_X86": Info(title: "", defaultValue: "", note: "0: 32-bit programs keep Wine's own C++ runtime instead of the Microsoft x86 runtime the app downloaded (Documents/vcruntime32)"),
        "env.MADEIRA_VCRT_ARM64_KEY": Info(title: "ARM64 Visual C++ runtime marker", defaultValue: "", note: "Default empty: nothing written. 1 (or a version such as 14.50.35717): the session has the ARM64 Visual C++ 2015-2022 redistributable's Installed marker (volatile keys; one the prefix has is left alone), for an Unreal bootstrap program that…"),
        "env.MADEIRA_VDCFG_PATH": Info(title: "QueryDisplayConfig lists the monitor's path", defaultValue: "0", note: "Default off: success with no path, as before. 1: QueryDisplayConfig returns the virtual monitor's one path (source and target mode, the desktop size) and DisplayConfigGetDeviceInfo names its source, target and adapter, for a game that buil…"),
        "env.MADEIRA_VFETCH_ALIGN1": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_VFETCH_BOUNDS": Info(title: "", defaultValue: "", note: "madeira-bcd: vertex fetch bounds (tools/patch-dxmt-vfetch-bounds.py) -- D3D10 reads zero past the end of the binding; route such a fetch to the null-binding branch of pull_vec4_from_addr instead of reading on. Default: SM 4.x shaders onl..."),
        "env.MADEIRA_VIRTUAL_MODE_SET": Info(title: "", defaultValue: "", note: "MADEIRA_VIRTUAL_MODE_SET=0: accept a listed mode without programming it -- the monitor keeps the session default size, as before this change."),
        "env.MADEIRA_VK_DIAGNOSTICS": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_VK_HOST_SUBOPTIMAL": Info(title: "", defaultValue: "", note: "The host surface can measure its size in other units than the client rect (an iOS CAMetalLayer reports points), so the host may call a swapchain suboptimal although it matches the window's client rect. The application cannot fix that: a ..."),
        "env.MADEIRA_VMON_IDS": Info(title: "", defaultValue: "", note: "synthesized branch; DXGI_OUTPUT_DESC::DeviceName says the same), and one monitor under it, the virtual monitor, which has no source. Upstream's code gives a sourceless monitor the GDI name \"WinDisc\" -- Windows' name for a DISCONNECTED di..."),
        "env.MADEIRA_VULKAN_LIBRARY": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_WAIT_CHILDREN": Info(title: "", defaultValue: "", note: "A launcher stub that starts the game and exits at once (GTA V Enhanced: PlayGTAV.exe -> GTA5_Enhanced.exe) must not end the session -- stopping the wineserver here killed the game while it loaded. If a child process that is not a crash r..."),
        "env.MADEIRA_WARMER_SWEEP_CYCLES": Info(title: "", defaultValue: "", note: "cycles of ~2 s between the warmer's map walk and slot/window inventory (default 30; 5 = old)."),
        "env.MADEIRA_WATCH_CHASE": Info(title: "", defaultValue: "", note: "predecessor fragment's tail). the first version kept six candidates and stopped on more; here a fragment every six bytes put six neighbours' entries in the window before the writer's own, so nothing was followed. MADEIRA_WATCH_CH..."),
        "env.MADEIRA_WATCH_WRITES": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_WGI_HOST_PADS": Info(title: "Controllers in Windows.Gaming.Input", defaultValue: "0", note: "Default off. 1: each connected XInput controller (a paired pad or the touch controller) is also a Windows.Gaming.Input gamepad, an Xbox pad to the game, with rumble. For games that read their controller only that way (Horizon Zero Dawn); a…"),
        "env.MADEIRA_WG_64BIT": Info(title: "", defaultValue: "", note: "MADEIRA: winegstreamer's unix side is bound for 32-bit (wow64) callers, and for 64-bit (ARM64EC) ones too: without it an x64 program's xWMA voices (FAudio's WMA decoder DMO, wmadmod -> winegstreamer) decode to silence. A 64-bit caller ge..."),
        "env.MADEIRA_WG_PARSER": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_WG_VIDEO": Info(title: "Media: MP4 video (32-bit programs)", defaultValue: "", note: "0 limits the media parser to MP3/WAV; by default MP4 with H.264/HEVC video decodes through VideoToolbox."),
        "env.MADEIRA_WG_VIDEO_FORMAT": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_WIDE_USER_VA": Info(title: "", defaultValue: "", note: "device. already applied exactly this reasoning to size the ARM64EC code bitmap (\"nothing on iOS can be mapped at or above host_addr_space_limit\"); this extends the same measured ceiling to what we tell applications. * Correct on bo..."),
        "env.MADEIRA_WIN32U": Info(title: "", defaultValue: "", note: "Register win32u's NtUser / NtGdi syscall table in slot 1. Activating this causes user32 process_attach to crash until wineserver shared-memory bringup is complete; gated on the MADEIRA_WIN32U env var so we can flip it on for debugging."),
        "env.MADEIRA_WINDOW_LINEAGE": Info(title: "", defaultValue: "", note: "1: report window lineage to the desktop compositor (off by default; this app's hook is a stub)"),
        "env.MADEIRA_WINEMONO_BRIDGE": Info(title: "", defaultValue: "", note: "FEX's Mono backpatcher bridge . On by itself for Wine Mono, 32- and 64-bit (/); for the 32-bit runtime in a guest window it also turns SMC detection off once the backpatcher is found . 0 keeps it off."),
        "env.MADEIRA_WINE_VCRT": Info(title: "", defaultValue: "", note: "Layer Microsoft's real VC++ Runtime DLLs ON TOP of the ARM64EC bundle (only for x86_64 guests). These overwrite Wine's stub builtins — Wine then loads the real MS x86_64 implementation (via FEX) instead of its partial ARM64EC reimplement..."),
        "env.MADEIRA_WINPROC_HANDLE": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_WIN_THREAD_PRIORITY": Info(title: "", defaultValue: "", note: "madeira-bcd: thread priority keeps the pthread QoS (tools/patch-wine-thread-qos.py). Below the realtime band the Mach precedence/throughput/latency policies only demote a USER_INTERACTIVE guest thread onto the efficiency cores."),
        "env.MADEIRA_WMA_DUMP": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_WMA_SEARCH": Info(title: "", defaultValue: "", note: "MADEIRA_WMA_SEARCH=0 pins the decoder to the rate and flags this file worked out from the media type alone, which is what shipped before the ladder. A packet it cannot decode is then concealed with silence of that packet's length..."),
        "env.MADEIRA_WORKDIR": Info(title: "", defaultValue: "", note: "set by the library for one launch: the working folder (Steam's, or the entry's); not a setting"),
        "env.MADEIRA_WOW64_BY_TEB": Info(title: "", defaultValue: "", note: "Guest windows are reserved lazily; this reserves nothing unless a 32-bit main image was published or MADEIRA_WOW_PLACEHOLDERS=1 (see ios_wow_session_start). Last, after the holdback, whose first page the lowest slot borrows as its guard."),
        "env.MADEIRA_WOW64_PEB_SELF": Info(title: "", defaultValue: "", note: "Madeira wow64-peb-self: wow_peb is a session global that init_peb() sets for a 32-bit child and loader_ios.c temporarily clears while a 64-bit child runs unix_init_startup_info(). A 32-bit thread querying ProcessWow64Information during t..."),
        "env.MADEIRA_WOW_AFFINITY32": Info(title: "32-bit thread group affinity", defaultValue: "1", note: "on (default): a 32-bit program's GROUP_AFFINITY thread attribute (12 bytes, a 32-bit mask) is decoded field by field when the thread is created; read as the 16-byte native struct, NtCreateThreadEx failed with c000000d and a 32-bit Chromium…"),
        "env.MADEIRA_WOW_AREA_BY_REQUEST": Info(title: "32-bit windows: judge a merged area by the request", defaultValue: "1", note: "on (default): when two adjacent guest windows' reserved areas have merged into one (a slot carved from the holdback beside slot 0), a 32-bit process's allocation is judged by the window that holds its request. Before, the first window in t…"),
        "env.MADEIRA_WOW_ARENA_HOLD_GB": Info(title: "", defaultValue: "", note: "GB at the top of the FEX arena kept for a 32-bit program's emulator while MADEIRA_WOW_HOLD_WINDOWS is set (default 3); 0: none"),
        "env.MADEIRA_WOW_CHILD_PEB": Info(title: "", defaultValue: "", note: "A thread of a child process in its own guest window gets THAT process's PEB32 (the page after its PEB), not the main process's wow_peb, when its argument is the PEB. MADEIRA_WOW_CHILD_PEB=0 always passes wow_peb as before."),
        "env.MADEIRA_WOW_CPU_POOL_ONLY": Info(title: "32-bit emulator module runs from its JIT-pool copy only", defaultValue: "1", note: "Default on. Where the kernel lets an image become executable in place (iOS 18; iOS 26 without TXM), the 32-bit emulator module (xtajit.dll) kept an executable view beside its JIT-pool copy, and its start-up code ran in the view while the e…"),
        "env.MADEIRA_WOW_EXTRA_WINDOW": Info(title: "", defaultValue: "", note: "A launcher -> helper -> program chain needs a THIRD window. After the carve, finish the held upper half of the cage, [0x7300000000, 0x73ffff0000), on demand. The missing 64 KB and the guard are acquired together with tryfixed, which refu..."),
        "env.MADEIRA_WOW_FEX_BAND": Info(title: "", defaultValue: "", note: "madeira-bcd [wow-band]: the WOW64 CPU module (xtajit.dll) is never handed the arena (its ios_get_fex_arena unix call is unsupported), so its rpmalloc band selector asks for the whole hardware FEX band [0x7c00000000, 0x7fffffffff]. With e..."),
        "env.MADEIRA_WOW_GUARD_INSIDE": Info(title: "", defaultValue: "", note: "0: a 32-bit guest window reserves 4 GB plus a guard page above it, as before (default 1: the guard is the window's top page, so the 4 GB gap above stays 4 GB-aligned)"),
        "env.MADEIRA_WOW_HOLD_FOR": Info(title: "", defaultValue: "", note: "Windows folder whose 32-bit programs alone may adopt the MADEIRA_WOW_HOLD_WINDOWS placeholders (the app sets the Dock game's folder); unset: any 32-bit program may"),
        "env.MADEIRA_WOW_HOLD_FOR_GAME": Info(title: "", defaultValue: "1", note: "0: any 32-bit program may take the held window, as before 2026-11-02"),
        "env.MADEIRA_WOW_HOLD_WINDOWS": Info(title: "", defaultValue: "", note: "bytes at the top of the arena the ARM64EC module's requests leave alone, for a 32-bit program that starts later in the session: its WoW64 module asks for the hardware band and nothing else, so when the 64-bit launcher chain has f..."),
        "env.MADEIRA_WOW_LIMIT_BY_WINDOW": Info(title: "", defaultValue: "", note: "Guest windows are reserved lazily; this reserves nothing unless a 32-bit main image was published or MADEIRA_WOW_PLACEHOLDERS=1 (see ios_wow_session_start). Last, after the holdback, whose first page the lowest slot borrows as its guard."),
        "env.MADEIRA_WOW_LIVE_WINDOW_GUARD": Info(title: "", defaultValue: "", note: "Worker threads of the exited process can stay asleep long after its main thread is gone; their TEBs are inside the window. Keep it (the next process takes another slot) while any of them still exists. MADEIRA_WOW_LIVE_WINDOW_GUARD=0 disa..."),
        "env.MADEIRA_WOW_LOW_RIP_GUEST": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_WOW_MAIN_FAIL_EXIT": Info(title: "", defaultValue: "", note: "This is the SESSION'S OWN program, not a child (a 32-bit program started on a device whose address space has no 4 GB window left). The pthread_exit() inside fatal_error() ends the boot thread (wine_process_thread) in the middle of __wine..."),
        "env.MADEIRA_WOW_PRESSURE_RELEASE_MB": Info(title: "", defaultValue: "", note: "MB: when the 32-bit band has less free address space than this, idle 32-bit window placeholders are handed back (default 256); 0: never"),
        "env.MADEIRA_WOW_REAP_DEAD": Info(title: "", defaultValue: "", note: "[wow-reap]: a thread of an EXITED process that is held suspended (the [zombie] rule's or ios_thread_registry_end_dead_range's fallback when thread_terminate is refused) never runs again, so it cannot touch the window: it does not hold it..."),
        "env.MADEIRA_WOW_RWX_PLAIN": Info(title: "", defaultValue: "", note: "Unset: a 32-bit window's anonymous RWX memory is plain read/write to the host once Wine Mono's libmono-2.0-x86.dll is mapped there (/). 1: in every 32-bit window. 0: never (stores go through the JIT pool's alias, and FEX's Mono bridge stay…"),
        "env.MADEIRA_WOW_SPILL_CEF": Info(title: "", defaultValue: "", note: "Still nothing: a 32-bit client with several 32-bit helpers can need more windows than the band holds. [0x7400000000, 0x7c00000000) is kept for a 64-bit Chromium's PartitionAlloc pools, which a 32-bit client does not use. Spill into it to..."),
        "env.MADEIRA_WOW_STACK_FREE_OWNER": Info(title: "", defaultValue: "", note: "process's window and released that process's live memory. Device log 95: a game creating and ending a short-lived thread in a loop while the Steam client started beside it lost guest 0x167e0000+0x10000 (\"NO wine view\", then a read access..."),
        "env.MADEIRA_WOW_STRICT_LIMITS": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_WOW_SYSCALL_SWEEP": Info(title: "", defaultValue: "", note: ""),
        "env.MADEIRA_WOW_WINDOW_KEEP": Info(title: "", defaultValue: "", note: "0: other programs' views may be placed inside a 32-bit guest window or its placeholder again (default 1: only the window's own process maps there)"),
        "env.MADEIRA_WRITE_COMBINED": Info(title: "", defaultValue: "", note: "no write-combined CPU mappings. DXMT asks for MTLCPUCacheModeWriteCombined on what the CPU only writes (dynamic buffers and textures, upload staging). Under FEX's TSO emulation every x86 integer store is an STLR, and a store-rele..."),
        "env.MADEIRA_WSEX_MINCORE": Info(title: "", defaultValue: "", note: "1: QueryWorkingSetEx's Valid bit from mincore() (iOS has no /proc pagemap); unset/0: every page reads as not resident, as before"),
        "env.MADEIRA_WX": Info(title: "", defaultValue: "", note: "OFF BY DEFAULT. This optimization has known stale-translation and address-reuse hazards and has already produced deterministic crashes in two builds; silent corruption on a fresh install would be worse than a clean crash, and a ki..."),
        "env.MADEIRA_X18_SIGNED_LOAD": Info(title: "", defaultValue: "", note: "ios_mach_exception_thread). It decoded the zero-extending unsigned-offset loads (LDR X, LDR W, LDRB, LDRH) but not the sign-extending ones, so the access was declined as \"UNRECOGNIZED\" and the thread died: `ldrsw x28, [x18, #0x180c]` (0x..."),
        "env.MADEIRA_X18_TRAMP_ALIGN": Info(title: "x18 trampolines on their own page", defaultValue: "1", note: "1 (default): an image whose .data was shifted to a 16 KB page gets its x18 trampolines on the page after it, not on its last .data page (mapped without exec). 0: the old offsets."),
        "env.MADEIRA_X64_GRAPHICS_ENTRY": Info(title: "Patchable x64 graphics method entries", defaultValue: "0", note: "Default off. 1 exposes typed x64 ARM64EC entries for swapchain Present/Present1, ResizeBuffers/ResizeBuffers1 and queue ExecuteCommandLists/GetTimestampFrequency/GetClockCalibration/GetDesc/Signal/Wait. With a DXMT dxgi that has the x64 en…"),
        "env.MADEIRA_X64_IMAGE_NOCOPY": Info(title: "Pure-x64 images without a JIT-pool copy", defaultValue: "0", note: "Default off. 1: an x64-only image (not ARM64EC hybrid, not a Wine builtin) in a 64-bit process is not copied into the JIT pool; the emulator runs its code from the loaded image, as 32-bit programs already do, and its executable protections…"),
        "env.MADEIRA_XCTEST_TYPING": Info(title: "", defaultValue: "", note: "True while a hardware keyboard delivers raw key events. The text bridge (MetalBackedView's UIKeyInput) receives the same presses from UIKit, so it stands aside while this is true instead of typing every key twice. An explicit test sessio..."),
        "env.MADEIRA_XINPUT": Info(title: "Physical controllers (XInput)", defaultValue: "1", note: "physical and touch controller snapshots share the same serial publisher. Slot/profile/timer state belongs exclusively to `queue`. The app lifecycle and observer registration belong to the main actor. Guest readers use the C snaps..."),
        "env.MADEIRA_XINPUT_BATTERY": Info(title: "Controller battery level to XInput", defaultValue: "1", note: "On (default): XInputGetBatteryInformation reports each pad's GameController battery (wired while charging, else a level) and XInputGetCapabilities flags a battery-powered pad as wireless. 0: an unknown battery, as before."),
        "env.MADEIRA_XINPUT_ENABLE_FOREGROUND": Info(title: "Ignore a stale XInput disable while the game is in front", defaultValue: "1", note: "On (default): when a game has switched XInput off (XInputEnable(FALSE), usually on losing focus) but its window is in front, it still reads the pad; activation messages at startup can leave it off for good. 0: the pad reads at rest while d…"),
        "env.MADEIRA_XINPUT_PROFILE_CHECK": Info(title: "Re-read a controller's input profile", defaultValue: "1", note: "on (default): every 2 s the app checks each connected controller's extended-gamepad profile and, when GameController has replaced it (a remap or a mode change after the controller joined), reads the live one; the first 8 times the sticks l…"),
        "env.MADEIRA_XINPUT_SLOT0_RECONNECT": Info(title: "Reconnected controller back to player 1", defaultValue: "1", note: "On (default): when player 1's controller reconnects and GameController reports it as a new controller before the old one leaves, it is moved from the slot it landed in back to slot 0. 0: it stays where it landed, as before."),
        "env.MADEIRA_ZERO_MITIGATION_POLICY": Info(title: "", defaultValue: "", note: "uninitialised PROCESS_MITIGATION_CONTROL_FLOW_GUARD_POLICY, and when EnableControlFlowGuard (bit 0) happens to be set it looks up SetProcessValidCallTargets in api-ms-win-core-memory-l1-1-3.dll, which this Wine does not export, and calls..."),
        "env.VKD3D_CONFIG": Info(title: "vkd3d-proton options", defaultValue: "", note: "Comma-separated vkd3d-proton flags (e.g. no_upload_hvv, force_static_cbv, skip_driver_workarounds); with d3d12 = vkd3d. See vkd3d-proton's README."),
        "env.VKD3D_DEBUG": Info(title: "vkd3d-proton log level", defaultValue: "", note: "vkd3d-proton's log: none, err, warn, fixme (default), info, trace. Passed to the Windows environment like any env line; only with d3d12 = vkd3d."),
        "env.VKD3D_SHADER_DEBUG": Info(title: "vkd3d-proton shader log level", defaultValue: "", note: "The shader translators' log level (none, err, warn, fixme, info, trace); with d3d12 = vkd3d."),
        "env._JAVA_OPTIONS": Info(title: "Java runtime options", defaultValue: "", note: "Passed into the game's environment and read by a bundled Java runtime (e.g. -XX:-UseZGC to leave a garbage collector off that cannot map its heap here)."),
        "exe-window-mb": Info(title: "Executable window size (MB)", defaultValue: "128", note: "The address range at 0x140000000 kept for a game exe without relocations, which can only run there. Unset: 128 MB, or for a Madeira Dock launch the size of the largest such exe in the game's folder (The Adventures of Elliot: 473 MB -> 480)…"),
        "f6-compute-open": Info(title: "", defaultValue: "1", note: "see f6_begin counts only madeira-bcd f6-rar"),
        "f6-rar": Info(title: "Experiment: fence-chain 6 ignores read-to-read barriers", defaultValue: "0", note: "Default off; only with fence-chain = 6. 1: a ResourceBarrier whose every transition goes from read states to read states (or is the first half of a split barrier) no longer makes the next GPU pass wait for all earlier ones, and no longer e…"),
        "fence-chain": Info(title: "D3D12 fence chain mode", defaultValue: "1", note: "2 was clamped to 1 in -"),
        "fence-early": Info(title: "Fences advance when the GPU reached their batch", defaultValue: "0", note: "Default off. 1: a job whose command buffers have no query results advances its fence right after the GPU's shared event, and its buffers are retired in order on a second thread; under the CPU clamp the completion bookkeeping took 2-5 ms pe…"),
        "fence-poll-backoff": Info(title: "", defaultValue: "0", note: "N >= 2 = a thread that polls one unchanged fence N times in a row (each within 50 us) sleeps until it moves, at most fence-poll-backoff-us; 0 = the locked read, as before"),
        "fence-poll-backoff-us": Info(title: "", defaultValue: "200", note: "fence-poll-backoff: the longest sleep in microseconds (20..2000), rounded up to whole milliseconds"),
        "fence-strict": Info(title: "", defaultValue: "0", note: "diagnostic: 1 = Queue::Wait waits for the commit and batches finish in serial order; 2 = also synchronous Signal and Present waits for its frame (slow)"),
        "fexfail": Info(title: "", defaultValue: "", note: "deterministic call-ret allocation failure injection. Documents/madeira-fexfail.txt holds \"reserve:N\" or \"commit:N\". The containment path it exercises only occurs naturally when a title exhausts the emulator's address band, and onl..."),
        "fft-arena-patch": Info(title: "", defaultValue: "0", note: "Final Fantasy Tactics - The Ivalice Chronicles: shrink its 64 GB arena to the real part of oversize-reserve-mb"),
        "fi-field-check": Info(title: "", defaultValue: "0", note: "diagnostic: every N presents (1 = 60) read back FSR 3's R32 vector fields before its Setup pass and after each later FidelityFX dispatch of that frame; log texels whose low half is a NaN/Inf half-float ([fi-field])"),
        "fi-nan-clean": Info(title: "", defaultValue: "0", note: "fix: after each FidelityFX dispatch that binds one of the R32 vector fields FSR 3's Setup pass binds, a helper kernel zeroes the field's texels whose vector half (bits 0..15) is a NaN/Inf half-float (HFW's black squares); 2 = also when b..."),
        "fi-setup-zero": Info(title: "", defaultValue: "0", note: "fix: zero-fill the R32 UAV textures of FSR 3's frame-interpolation Setup pass with a blit just before it (black squares: is Setup's own clear lost?)"),
        "fullscreen-window": Info(title: "Full screen moves the game's window over the whole screen", defaultValue: "0", note: "Default off. 1: when a Direct3D 12 game switches to full screen, its window is moved to the screen's top-left corner and over the whole screen first, as Windows does; the game then sizes it to the chosen mode. Without it a game that only r…"),
        "gl-backend": Info(title: "", defaultValue: "", note: "OpenGL backend for the winios GL driver (build/win32u-unix/opengl_ios.c): zink - desktop OpenGL 3.3-4.x: Mesa OSMesa + Zink on MoltenVK, from the bundle's gl/ folder (build/mesa-ios, build/moltenvk-ios) gles - Apple's OpenGL ES 3.0 (EAGL..."),
        "gl-vulkan": Info(title: "Vulkan driver for OpenGL (Zink)", defaultValue: "", note: "The Vulkan driver Zink runs desktop OpenGL (and d3d9 = wined3d) on: MoltenVK (default) or KosmicKrisp (gl/libvulkan_kosmickrisp.dylib); any other value is a .dylib name in the gl folder or an absolute path. env.MADEIRA_GL_VULKAN is the fal…"),
        "gpu-fault-info": Info(title: "", defaultValue: "1", note: "Batch command buffers are created with encoder execution status (madeira_ctl op 8, winemetal in DXMT), and a failed one logs its faulted encoders by label (op 9). After the first fault every encoder is labelled, a compute encoder runs ON..."),
        "gpu-fault-skip": Info(title: "", defaultValue: "1", note: ""),
        "gpu-sync": Info(title: "", defaultValue: "0", note: "diagnostic: every ExecuteCommandLists commits its batch and waits until the GPU has finished it (no CPU/GPU overlap at all; slow)"),
        "gs-null-fragment": Info(title: "Empty fragment function for pipelines without a pixel shader", defaultValue: "1", note: "Default on. Metal aborts on a mesh pipeline (geometry shader or tessellation emulation) with rasterization on and no fragment function, while D3D allows a pipeline with no pixel shader. On: such a pipeline gets an empty fragment function a…"),
        "heap-backing": Info(title: "", defaultValue: "1", note: ""),
        "iat-noexec": Info(title: "", defaultValue: "0", note: "madeira.cfg iat-noexec = 1"),
        "ignore-volatile-metadata": Info(title: "FEX: x86 ordering for the whole image", defaultValue: "0", note: "Default off. 1: an x64 image's PE volatile metadata (MSVC /volatileMetadata) is cleared when it is mapped, so FEX orders every instruction of it by its TSO settings instead of only the listed ones. Slower; for testing memory-ordering bugs.…"),
        "ind-count": Info(title: "", defaultValue: "0", note: "diagnostic: log N frames (1 = 3000) of per-pipeline ExecuteIndirect instance / threadgroup totals read back from the GPU; one-frame dips are flagged"),
        "ind-count-from": Info(title: "", defaultValue: "0", note: "ind-count: the first present logged"),
        "ind-probe": Info(title: "ExecuteIndirect probe (diagnostic)", defaultValue: "1", note: "Default on. Every 3 s per pipeline, the first argument record of an ExecuteIndirect is read back by a small compute pass and logged as a [probe] line, 1500 lines at most. Each probe ends the open render pass. 0: no probes (Red Dead Redempt…"),
        "indirect-fast": Info(title: "Encode ExecuteIndirect records without per-record setup", defaultValue: "0", note: "Default off. 1: after the first record of an ExecuteIndirect, the other records (which share all state but their offset) are encoded 64 at a time with only their offset and the indirect draw or dispatch, instead of the whole per-draw setup…"),
        "inproc-sync": Info(title: "Madsync (in-process sync)", defaultValue: "0", note: "1 selects madsync (Settings > Sync engine > Madsync). Unset: fastsync, the default engine; 0 without env.MADEIRA_FASTSYNC: Wine standard sync."),
        "jumbo-keep-mb": Info(title: "", defaultValue: "0", note: "the keep floor, same units. madeira.cfg jumbo-keep-mb = N"),
        "jumbo-mb": Info(title: "", defaultValue: "0", note: "madeira.cfg jumbo-mb = N"),
        "madsync-lock-spin": Info(title: "", defaultValue: "256", note: "the lock is held for well under a microsecond; a contended pthread_mutex_lock sleeps in the kernel (__psynch_mutexwait, ~20 us measured on average in ph-rdr74, 3.4 k times a second). Spin on trylock first. madeira.cfg madsync-loc..."),
        "madsync-spin-us": Info(title: "", defaultValue: "0", note: "madeira.cfg madsync-spin-us (default 0 = sleep at once)"),
        "metal-validation": Info(title: "", defaultValue: "0", note: "Metal API validation for this launch (debug layer, reports instead of aborts)."),
        "metalfx-upscale": Info(title: "MetalFX upscaling factor", defaultValue: "", note: "Scales the presented picture with Apple's MetalFX spatial scaler (Direct3D 11 and 12). Usually set per game in Game details > Display."),
        "mip0-full": Info(title: "", defaultValue: "0", note: "fix: a texture created with MipLevels 0 gets the full mip chain and GetDesc answers its count, as D3D12 does (FSR 3.1 frame generation's inpainting pyramid: Horizon Forbidden West's black squares); 0 = one level, GetDesc answers 0"),
        "mono-bridge": Info(title: "", defaultValue: "", note: "wine-mono backpatcher bridge A/B. Documents/madeira-mono-bridge.txt == \"1\" sets MADEIRA_WINEMONO_BRIDGE, which arms FEX's Mono code-patching optimisation for wine-mono (recognised since but activation left opt-in because the..."),
        "mono-suspend": Info(title: "", defaultValue: "", note: "Mono suspend-policy A/B. Documents/madeira-mono-suspend.txt containing \"preemptive\" (or \"coop\"/\"hybrid\") sets MONO_THREADS_SUSPEND for wine-mono, so the comparison needs no rebuild. EXPERIMENT, NOT A FIX, and deliberately not a de..."),
        "msc-bounds-check": Info(title: "", defaultValue: "1", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1"),
        "msc-fail-memo": Info(title: "Remember refused shaders for the session", defaultValue: "0", note: "Default off. 1: a shader the converter refused is not converted again for the next pipeline that uses it (same bytecode, root signature and options) until the game exits. Horizon Zero Dawn converted each refused shader ~6 times, ~30,000 co…"),
        "msc-position-inf-nan": Info(title: "", defaultValue: "1", note: "madeira-bcd: madeira_ir_unix.mm, build 217"),
        "msc-position-invariance": Info(title: "", defaultValue: "1", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1"),
        "msc-sample-nan-zero": Info(title: "", defaultValue: "1", note: "madeira-bcd: madeira_ir_unix.mm, build 217"),
        "msc-sampler-lod-bias": Info(title: "", defaultValue: "1", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1"),
        "msc-strict-nan": Info(title: "", defaultValue: "1", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1"),
        "msc-unbounded-retry": Info(title: "Retry refused shaders with sized unbounded ranges", defaultValue: "0", note: "Default off. 1: a DXIL shader the converter refuses with code 4 (a resource not in the root signature) is converted once more with the root signature's unbounded descriptor ranges given a size (2048 samplers, 1000000 others). Horizon Zero…"),
        "no-local-read": Info(title: "", defaultValue: "0", note: "madeira.cfg no-local-read = 1"),
        "occlusion-visible": Info(title: "", defaultValue: "0", note: ""),
        "oversize-reserve": Info(title: "", defaultValue: "0", note: "serve a reserve too big for the map in part (Game details > Large memory reservations)"),
        "oversize-reserve-mb": Info(title: "", defaultValue: "16384", note: "its real part (MB)"),
        "perf-log": Info(title: "", defaultValue: "1", note: "where does the frame go? GPU busy (union of command-buffer GPU intervals), CPU time blocked in retire, presents -- logged every 5 s from Present. Off with madeira.cfg perf-log = 0."),
        "pool": Info(title: "JIT pool size (MB)", defaultValue: "", note: "madeira.cfg pool: the JIT pool size in MB (256 to 1152); wins over the size above. The game's own file wins over madeira.cfg, so a game can size the pool to fit a free run above its executable window and pair it with pool-low."),
        "pool-low": Info(title: "JIT code buffers below the executable window", defaultValue: "0", note: "1: a free run below the 0x140000000 executable window (less pool-low-margin) becomes a third debugger region for the emulator's code buffers, so the whole JIT pool is left to DLL copies (GTA V: about 300 MB more). Needs the pool above the…"),
        "pool-low-margin": Info(title: "Code-buffer region: MB left free below the window", defaultValue: "128", note: "With pool-low on: how much of the free run below the executable window stays free for programs that load there (child processes' main executables). A run with a free run at least this large below it keeps none. 128 by default."),
        "pool-mid": Info(title: "Split JIT pool: use the free run between the regions", defaultValue: "0", note: "With pool-split on: when another mapping sits between the pool's two regions and leaves a free run of 64 MB or more there, that run becomes a third debugger region in the same pool (RDR2 build 470: 604 MB pool, a 71 MB mapping and 213 MB f…"),
        "pool-page-fit": Info(title: "Fit split pool regions to memory pages", defaultValue: "0", note: "With pool-split on: fit regions A/B to 16 KB pages instead of 16 MB steps, retaining small remainders in free runs without increasing the requested pool budget. With pool-low on, also fit region C to pages while preserving pool-low-margin.…"),
        "pool-pair": Info(title: "Split JIT pool: prefer two runs above the window", defaultValue: "1", note: "With pool-split on: the pool takes two runs above the 0x140000000 executable window when together they are larger than the single run it would get -- whether that run lies below the window, where the pool cannot split (GTA V: 368 + 320 MB…"),
        "pool-split": Info(title: "Split JIT pool around the main thread's stack", defaultValue: "0", note: "1: when the pool would shrink below its size (pool, 896 MB by default) because the main thread's stack splits the only executable band, the free run above the stack becomes a second debugger region and both form one pool (about 880 MB inst…"),
        "present-min-ms": Info(title: "", defaultValue: "0", note: "diagnostic: Present sleeps so that frames are at least N ms apart (200 = 5 fps), like the main menu's slow first seconds"),
        "pso-archive": Info(title: "", defaultValue: "0", note: "compiled pipelines kept in Metal binary archives of our own (1; 0 = Metal's cache only)"),
        "pso-async": Info(title: "", defaultValue: "0", note: "madeira.cfg pso-async: 1 = a new render pipeline is built on a background thread and its draws are skipped until it is ready (no frame waits for the compiler); 0 = built at its first draw"),
        "pso-first-use": Info(title: "", defaultValue: "0", note: "diagnostic: log every pipeline the first time a command list binds it, with the present it was created at"),
        "pso-lazy": Info(title: "", defaultValue: "1", note: "madeira-bcd: madeira.cfg pso-lazy (default 1), see mad_pso_realize"),
        "pso-lazy-libs": Info(title: "Shader libraries only for pipelines in use", defaultValue: "0", note: "Default off. 1: a pipeline built at its first draw (or dispatch) lets its converted Metal libraries go once the game has created it, and reads them back from the shader cache at that first draw. Horizon Zero Dawn creates ~52,000 pipelines…"),
        "pso-parallel": Info(title: "", defaultValue: "1", note: "madeira.cfg pso-parallel (default 1): a batch's new pipelines built in parallel"),
        "pso-placeholder": Info(title: "Placeholder for pipelines whose shaders did not convert", defaultValue: "0", note: "Default off. 1: a graphics pipeline whose vertex or pixel shader did not convert is returned to the game as a placeholder whose draws are skipped, instead of a failure. Horizon Zero Dawn stopped with an \"Error\" box when its settings menu g…"),
        "pso-share-libs": Info(title: "", defaultValue: "1", note: "madeira.cfg pso-share-libs (default 1): identical converted libraries share one MTLLibrary. 0 keeps one per pipeline (the table is never trimmed, so this is the switch to compare memory with)."),
        "pso-warm": Info(title: "", defaultValue: "0", note: "pipeline cache warm-up: N background compiles of every lazy pipeline at creation (1-4; 0 = off)"),
        "query-timestamps": Info(title: "Timestamp queries from the CPU clock", defaultValue: "0", note: "Default off: every timestamp resolves to zero. 1: a resolved timestamp is the process's monotonic clock in ns when the resolve is recorded (plus its place in the range), and GetClockCalibration's GPU value is the same clock, for a game tha…"),
        "queue-trace": Info(title: "", defaultValue: "0", note: "diagnostic: log the first N ExecuteCommandLists / Signal / Wait calls (1 = 400) with thread, queue type and fence state"),
        "quiet-log": Info(title: "Cheaper Direct3D 12 logging (no census frames)", defaultValue: "0", note: "1: the Direct3D 12 runtime's log lines skip OutputDebugString (an exception and a server request each, ~0.5 ms a line on the device) and reach the log through Wine's own debug output and stderr only; the census frames between presents 1500…"),
        "ram-reserve-mb": Info(title: "", defaultValue: "1536", note: "RAM left to iOS, MB; 0 = limit only"),
        "readback-far": Info(title: "Experiment: empty culling readback", defaultValue: "0", note: "Default off. 1: a readback of a depth pyramid (an R32_FLOAT mip of 1 or more of a texture with 4+ mips, up to 64x64) is not copied; the CPU fills it with 4096, so a game that culls on the CPU against it culls nothing (everything is drawn:…"),
        "readback-swap": Info(title: "D3D12 readback buffers on file-backed memory", defaultValue: "1", note: "Default on: like upload buffers (upload-swap), READBACK buffers of 8 MB or more live on file-backed storage, off the memory footprint. 0: READBACK buffers get Metal's own memory (Horizon Zero Dawn: two 32 MB buffers), so what the GPU write…"),
        "real-suspend": Info(title: "", defaultValue: "", note: "this session, or nil to leave it unset. Without it a Wine SuspendThread only snapshots the target's registers while the thread keeps running (build/wineserver/mach_ios.c). A Unity IL2CPP game's garbage collector suspends every thr..."),
        "remote": Info(title: "", defaultValue: "", note: "remote Metal backend. Documents/madeira-remote.txt holds \"<host-ip> <token>\" and routes winemetal to a Metal daemon on that host instead of the local device. The mode is decided ONCE per process: flipping it later would leave hand..."),
        "remote-batch": Info(title: "", defaultValue: "", note: "coalesced remote messages. Documents/madeira-remote-batch.txt == \"1\" makes the pre-submission flush send many buffer ranges per round trip and drains autorelease pools in one call. It is OPT-IN because the measurement it is meant ..."),
        "replay-split": Info(title: "Log where Direct3D 12 submission time goes", defaultValue: "0", note: "Default off, logging only. 1: every 5 seconds a [perf] replay split line divides the time ExecuteCommandLists takes per frame into waiting for the queue, preparation, opening a command buffer, each kind of command (draws, dispatches, copie…"),
        "ring-share": Info(title: "Share argument buffers between command lists", defaultValue: "0", note: "Default off. 1: a command list gives the argument-buffer chunks its replay wrote back as soon as the GPU is done with them, instead of keeping them until it is recorded again; all lists then share one pool. Red Dead Redemption 2 kept 1.5 G…"),
        "rp-carry": Info(title: "Experiment: render passes go on into the next command list", defaultValue: "0", note: "Default off. 1: when a command list ends inside a render pass and the next list of the same submission draws to the same targets first, with only state between the two draws, the pass stays open: its targets are not written to memory and r…"),
        "rp-discard": Info(title: "Experiment: no load after, no store before DiscardResource", defaultValue: "0", note: "Default off. 1: after a game discards a whole render target or depth buffer (DiscardResource), the next render pass that draws to it does not read its old contents from memory, and a pass whose target is discarded (or cleared whole) next,…"),
        "rp-lean": Info(title: "Render passes fill only the targets they use", defaultValue: "1", note: "Default on. A Metal render pass is described with only the colour targets it uses; the bridge filled all eight slots for every pass (~240 Objective-C calls and 8 allocations a pass, a few hundred passes a frame). Metal ignores a slot witho…"),
        "sampler-census": Info(title: "", defaultValue: "0", note: "diagnostic: log every distinct sampler filter value once with its Metal mapping"),
        "sampler-reduction": Info(title: "", defaultValue: "0", note: "madeira-bcd: native sampler reduction (tools/patch-winemetal-sampler-reduction.py)"),
        "shader-cache": Info(title: "", defaultValue: "1", note: ""),
        "shader-cache-native": Info(title: "D3D12 shader cache files read natively", defaultValue: "1", note: "On by default. The Direct3D 12 runtime's shader cache (AppData\\Local\\Madeira\\ShaderCache) is read and written by Madeira itself instead of through Wine's file calls, which asked Wine's server three times per entry (~3.5 ms each in Horizon…"),
        "shadow": Info(title: "", defaultValue: "", note: "shadow-pack mode. Documents/madeira-shadow.txt == \"1\" packs and validates every real render batch into the remote wire format, then discards it and renders locally as normal. Exercises the packer against live traffic where being w..."),
        "skin-check": Info(title: "Diagnostic: check meshes skinned on the GPU", defaultValue: "0", note: "Default 0 (off). N: windows of N frames (1 = 8) log every draw that reads a vertex buffer a compute shader wrote, the dispatches that wrote it with every binding, a summary of up to 32 KB of each such stream copied just before the draw, an…"),
        "skin-check-capture": Info(title: "Diagnostic: skin-check copies the streams", defaultValue: "1", note: "On by default with skin-check. 0: log only, with no GPU copies, which add a copy between the skinning dispatches and the draw (to compare what the frames look like)."),
        "skin-check-every": Info(title: "Diagnostic: presents between skin-check windows", defaultValue: "300", note: "With skin-check on: a window starts this many presents after the previous one began (at least 30); the first starts 60 presents after the first such draw."),
        "skin-check-trace": Info(title: "Diagnostic: skin-check traces whole frames", defaultValue: "0", note: "Default off. 1, with skin-check on: the first frame of the first two windows logs every draw in one line (shaders, counts, streams, input layout); a pipeline with integer vertex inputs (a mesh skinned in its vertex shader) also gets its ve…"),
        "skin-dump": Info(title: "Diagnostic: skin-check dumps the skinning data", defaultValue: "0", note: "Default off. 1, with skin-check on: in the first window's first two frames the compute shaders that skin a mesh have their inputs and the stream they wrote copied whole (up to 256 KB each) and logged as base64 (4 MB at most), so the skinni…"),
        "skip-ps": Info(title: "", defaultValue: "", note: "diagnostic: drop the draws of these shader entries (comma list, exact names)"),
        "skip-ps-cycle": Info(title: "", defaultValue: "0", note: "diagnostic: rotate skip-ps one name at a time, N seconds each (0 = skip all at once)"),
        "sm5-flat-views": Info(title: "", defaultValue: "1", note: ""),
        "stale-probe": Info(title: "", defaultValue: "0", note: "the probe found its bug ; off unless madeira.cfg stale-probe = 1"),
        "static-cbv": Info(title: "Constant buffers as the draw was recorded", defaultValue: "0", note: "Default off: the GPU reads every descriptor of a table when it runs. 1: a descriptor table's single constant-buffer ranges are read when each draw or dispatch is recorded, as NVIDIA's driver and vkd3d-proton do; a game that rewrites one af…"),
        "swap-canary": Info(title: "", defaultValue: "0", note: "madeira.cfg swap-canary = 1"),
        "swap-images": Info(title: "Swap tier: pure-x64 DLLs and programs in the file", defaultValue: "0", note: "Default off. 1: the sections of pure-x64 images (with env.MADEIRA_X64_IMAGE_NOCOPY = 1: libcef.dll, steamclient64.dll, launchers, the game exe) move to the swap tier's file once they are read, so they stop counting against the memory limit…"),
        "swap-mb": Info(title: "Swap tier size", defaultValue: "0", note: "Moves game data to a file on this device's storage when memory runs short, up to this size. Off by default; read at launch."),
        "swap-min-kb": Info(title: "", defaultValue: "0", note: "madeira-bcd: swap-min-kb (madeira.cfg or the game's config) lowers the tier's 8 MB eligibility floor. Upstream's virtual_ios.c reads MADEIRA_SWAP_MIN_KB only in its \"blocks\" coverage, so swap-min-kb selects that; an env.MADEIRA_SWAP_COVE..."),
        "swap-min-mb": Info(title: "Swap tier floor (MB)", defaultValue: "0", note: "The smallest allocation the swap tier backs : 8 MB in classic, 1 MB in blocks and wide, 4 MB in broad unless set. MADEIRA_SWAP_MIN_KB overrides it for blocks, wide and broad."),
        "swap-mode": Info(title: "Swap tier mode (2 = broad)", defaultValue: "1", note: "2 selects broad swap coverage when env.MADEIRA_SWAP_COVERAGE is unset; any other value, classic. The coverage key wins when set."),
        "swap-wow64": Info(title: "Swap tier for 32-bit programs", defaultValue: "0", note: "what the tier may do with memory a 32-bit program commits (inside its WoW64 guest window). Unset: donor RAM only, the memory stays ordinary RAM when the pool has none; it never goes to the swap file, which paged a 32-bit title's heap in an…"),
        "swap-x64": Info(title: "Swap tier: where 64-bit programs go first", defaultValue: "0", note: "the stage a 64-bit program's memory takes first; the other is the fallback. Unset: the swap file while a 32-bit program is in the session (a guest window held or in use), so the kernel can evict the launcher chain's idle pages and the dono…"),
        "tf-trace": Info(title: "", defaultValue: "", note: "Theorafile call tracer. Documents/madeira-tf-trace.txt == \"1\" redirects libtheorafile's tf_* exports through wrappers in tftrace-x64.dll that call the original and report the RETURN value. The intro decodes and plays, the stream r..."),
        "totalphys": Info(title: "Reported physical memory (MB)", defaultValue: "0", note: "madeira.cfg totalphys = N"),
        "tv-hash": Info(title: "", defaultValue: "1", note: "fix: typed-buffer views are found through a hash table once a resource has 32 of them, instead of a scan of all of its views under the device-wide view lock; 0 = the scan as before"),
        "typed-uav-atomic": Info(title: "", defaultValue: "0", note: "fix attempt: R32 UAV texture-buffer views (RWBuffer<uint>, UAV counters) get ShaderAtomic usage"),
        "typed-view-align": Info(title: "Typed buffer view alignment", defaultValue: "0", note: "Default 0 (64 bytes, as before). 16 or 256: a typed buffer view's texture starts at that boundary, never below Metal's minimum for its format (logged once per format); 16 is what Apple's converter documents, so a float4 view has no padding…"),
        "typed-view-rgb32": Info(title: "", defaultValue: "0", note: "fix: typed SRVs of UPLOAD memory in an R32G32B32 format (no Metal texture-buffer format) read a copy with 16-byte elements through an RGBA32 texture buffer"),
        "typed-view-shadow": Info(title: "Aligned copies of offset typed views", defaultValue: "0", note: "Default off. 1: a typed shader-resource view of UPLOAD memory whose first element is not on a 16-byte boundary reads a 16-byte-aligned copy of its bytes, made when the view is made and refreshed at every ExecuteCommandLists (the GPU rounds…"),
        "upload-guard": Info(title: "", defaultValue: "0", note: "diagnostic: 1 = log UPLOAD-heap data the game rewrites while the GPU still uses it; 2 = also compare with what the GPU read"),
        "upload-guard-bytes": Info(title: "", defaultValue: "256", note: "bytes upload-guard hashes per range (16..4096)"),
        "upload-swap": Info(title: "D3D12 upload buffers on file-backed memory", defaultValue: "1", note: "madeira.cfg upload-swap (default 1)"),
        "usd-time": Info(title: "", defaultValue: "", note: "Windows shared-data clock A/B. Documents/madeira-usd-time.txt == \"1\" makes wineserver update KUSER_SHARED_DATA's SystemTime, InterruptTime and TickCount again. Without it those stay frozen at their init values, so GetTickCount/Env..."),
        "use-dedup": Info(title: "", defaultValue: "1", note: "A draw's declarations count only once its chain has been encoded: a draw that returns early leaves them uncommitted, and the next begin drops them."),
        "valley-args": Info(title: "", defaultValue: "", note: "AncientGame-Win64-Shipping.exe ValleyoftheAncient and nothing else, which is why the launcher is skipped here. Flags come from Documents/madeira-valley-args.txt so a UE switch can be tried without rebuilding and reinstalling. The default..."),
        "view-census": Info(title: "Diagnostic: report buffer views that fall back", defaultValue: "0", note: "Default off. 1: typed buffer views that cannot become a Metal texture buffer (the shader then sees no data), views cut short at the end of their resource, and views or constant buffer views past their resource are counted and named in the…"),
        "vis-trace": Info(title: "Diagnostic: per-frame draws and culling readback", defaultValue: "0", note: "Default off. 1: one log line per present (the HUD's frame number): draws, depth-only and 3+-target draws, indices, dispatches, depth-pyramid readback copies, new offset typed views, and Queue::Wait calls (how many passed before the awaited…"),
        "vmwatch": Info(title: "", defaultValue: "", note: "madeira.cfg vmwatch = 0x<hex>"),
        "vram-count-donor": Info(title: "Video memory budget counts donated RAM", defaultValue: "0", note: "The video memory budget a game reads shrinks as memory runs short (vram-trim-mb), judged by the app's own memory. 1: the donor pool's memory counts as well, since it is the device's RAM even though it is not under the app's limit, so with…"),
        "vram-mb": Info(title: "Video memory budget (MB)", defaultValue: "0", note: "madeira.cfg vram-mb = N"),
        "vram-trim-mb": Info(title: "", defaultValue: "1536", note: "madeira.cfg vram-trim-mb = distance below the kill line where the trim starts (default 1536, the value); 0 = never trim. ph-rdr56: raising vram-mb to 3072 doubled the snow-scene frame rate, but in the city the footprint re..."),
        "vsps-fill": Info(title: "", defaultValue: "1", note: "0: shaders converted without D3D12's robust buffer access (bounds check), as env MADEIRA_IR_NO_BOUNDS_CHECK=1"),
        "vulkan": Info(title: "Vulkan library (x64)", defaultValue: "", note: "The Vulkan driver Wine's winevulkan loads: moltenvk = gl/libMoltenVK.dylib (the one Zink uses), kosmickrisp = gl/libvulkan_kosmickrisp.dylib, or a .dylib path (absolute or bundle-relative). Setting it turns Vulkan on for x64 programs (vulk…"),
        "write-buffer-immediate": Info(title: "WriteBufferImmediate writes its values", defaultValue: "0", note: "Default off: the method stays a stub (nothing written). 1: the values are written by the GPU in list order and a submission that wrote one is committed at once. CheckFeatureSupport still reports no support either way. Read once per game st…"),
        "wx": Info(title: "", defaultValue: "", note: "W^X A/B switch. Documents/madeira-wx.txt containing \"0\" disables page demotion for the SAME binary, so the on/off comparison needs one rebuild, not two. The previous gate read container paths that can never exist, so it silently f..."),
        "wxprobe": Info(title: "", defaultValue: "", note: "W^X A/B probe. Documents/madeira-wxprobe.txt == \"1\" runs it. Loading xtajit64.dll faults writing its .rdata on the jailbroken research VM and not on this phone, with CS_DEBUGGED live in both, so attachment is not the variable. Eit..."),
        "yield-sleep-us": Info(title: "", defaultValue: "100", note: "madeira.cfg yield-sleep-us (default 100, 0 = never sleep), yield-streak (256)"),
        "yield-streak": Info(title: "", defaultValue: "256", note: "madeira.cfg yield-sleep-us (default 100, 0 = never sleep), yield-streak (256)"),
